import{a as o}from"./adhd-D1IrBcDG.js";import{c as s}from"./calm-c0GQjegR.js";import{c as n}from"./confidence-DD8mQuzl.js";import{f as i}from"./faith-CLCsJ7UA.js";import{f as r}from"./focus-CDbEM4RI.js";import{m as t}from"./manifest-B3lH1fO8.js";import{m as l}from"./meditation-DsuEcsJh.js";import{m as c}from"./motivation-DiIbERl-.js";import{p as u}from"./procrastination-BPTyB7Hv.js";import{s as d}from"./sleep-DuFAH-jR.js";import{s as p}from"./suggestion-CQdSIf12.js";import{t as m}from"./turning-day-AqFMYU9C.js";const b=[{id:"compassion-neff-definition",title:"Kristin Neff · What is self-compassion? (self-compassion.org)",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"Neff define la autocompasión como ofrecerte a ti mismo la calidez y la comprensión que le ofrecerías a un amigo que atraviesa un momento difícil, con tres componentes: amabilidad hacia ti mismo frente a autojuicio, humanidad compartida frente a aislamiento, y atención plena frente a sobreidentificación. Distingue entre la autocompasión tierna (consolarte y aceptarte) y la autocompasión firme (actuar para protegerte, poner límites, perseguir metas o salir de situaciones dañinas), y separa la autocompasión de la autoestima, la autocompasión mal entendida como lástima de uno mismo y la indulgencia excesiva.",limitation:"Es una definición escrita por la investigadora que desarrolló el concepto, no un estudio; explica el modelo en lugar de ponerlo a prueba. Se consultó la página."},{id:"compassion-neff-exercises",title:"Kristin Neff · Self-Compassion (2011) y ejercicios de autocompasión (self-compassion.org)",url:"https://self-compassion.org/",type:"technique",finding:"Neff ofrece ejercicios prácticos para desarrollar la autocompasión, entre ellos preguntarte cómo tratarías a un amigo, la pausa de autocompasión (reconocer el dolor, recordar la humanidad compartida, ofrecerte amabilidad, a menudo con un gesto de contacto que te reconforte), un diario de autocompasión y escribirte una carta desde la perspectiva de un amigo que te quiere incondicionalmente.",limitation:"Es una guía de práctica de la creadora del concepto. Los ejercicios individuales no se han probado cada uno en ensayos; la evidencia proviene de programas que los combinan."},{id:"compassion-mindful-self-compassion-rct",title:"Neff & Germer · 2013 · A pilot study and randomized controlled trial of the Mindful Self-Compassion program (Journal of Clinical Psychology)",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"En un ensayo aleatorizado con adultos de la población general, el programa de autocompasión consciente de ocho semanas produjo mayores aumentos en la autocompasión, la atención plena, la compasión hacia los demás y la satisfacción con la vida, y mayores descensos en la depresión, la ansiedad, el estrés y la evitación emocional, que un grupo de control en lista de espera. Las mejoras se mantuvieron en los seguimientos a los seis meses y al año, y una mayor práctica se asoció con mayores avances en la autocompasión.",limitation:"Es un ensayo pequeño dirigido por los creadores del programa, comparado con una lista de espera y no con una alternativa activa, con medidas basadas sobre todo en lo que contaban los participantes. Evalúa el programa completo, no ejercicios sueltos."},{id:"compassion-ferrari",title:"Ferrari et al. · 2019 · Self-compassion interventions and psychosocial outcomes: a meta-analysis of RCTs (Mindfulness)",url:"https://doi.org/10.1007/s12671-019-01134-6",type:"research",finding:"Al reunir 27 ensayos controlados aleatorizados de intervenciones de autocompasión, el metaanálisis halló mejoras en una variedad de resultados psicosociales, entre ellos la propia autocompasión, la rumiación, la autocrítica, el estrés, la depresión y la ansiedad.",limitation:"Muchos de los ensayos incluidos eran pequeños y variaban en formato, población y condición de control; la mayoría de los resultados se basaban en lo que contaban los participantes y los periodos de seguimiento fueron cortos."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · The origins and nature of compassion focused therapy (British Journal of Clinical Psychology)",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"Gilbert describe cómo se desarrolló la terapia centrada en la compasión (CFT, por sus siglas en inglés) para personas con mucha vergüenza y autocrítica que entendían la lógica de la terapia pero tenían dificultades para sentirse tranquilizadas o seguras. Se apoya en un modelo de tres sistemas de regulación emocional que interactúan: amenaza y protección, impulso y búsqueda de recursos, y calma, satisfacción y vínculos con los demás.",limitation:"Es una revisión teórica y clínica, no un ensayo. El modelo de tres sistemas es un marco clínico simplificado, y la evidencia de la CFT como terapia todavía se está desarrollando."},{id:"compassion-gilbert-mind",title:"Paul Gilbert · The Compassionate Mind (2009) y la Compassionate Mind Foundation",url:"https://www.compassionatemind.co.uk/",type:"technique",finding:"El entrenamiento de la mente compasiva de Gilbert incluye la respiración a un ritmo calmante (hacer más lenta la respiración hasta un ritmo constante y cómodo) y la imaginación de tu yo compasivo, una versión sabia, fuerte y cariñosa de ti, como formas de activar el sistema de calma.",limitation:"Es una guía de práctica del creador de la CFT y de su fundación. Estos ejercicios suelen enseñarse dentro de una terapia o de un entrenamiento estructurado y no se han probado aquí como autoayuda independiente."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig & Mashek · 2007 · Moral emotions and moral behavior (Annual Review of Psychology)",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"La revisión distingue la vergüenza, una mirada dolorosa sobre toda la persona, de la culpa, una mirada centrada en una conducta concreta. La propensión a la culpa se asocia con la empatía y con la acción reparadora, mientras que la propensión a la vergüenza se asocia con esconderse, negar, la ira defensiva, culpar a otros y síntomas psicológicos.",limitation:"Es sobre todo investigación correlacional sobre disposiciones (ser propenso a la vergüenza o a la culpa); no demuestra que pasar de la vergüenza a la culpa en un momento concreto cambie los resultados."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Shame resilience theory: a grounded theory study on women and shame (Families in Society)",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"A partir de entrevistas con mujeres, el estudio describe la resiliencia a la vergüenza a través de cuatro aspectos que pueden desarrollarse en distinto grado: reconocer la vergüenza y comprender sus detonantes, practicar la conciencia crítica, acercarse a otras personas y hablar de la vergüenza.",limitation:"Es investigación cualitativa que propone una teoría a partir de entrevistas solo con mujeres; describe patrones pero no comprueba si practicar los cuatro elementos reduce la vergüenza."},{id:"compassion-brown-practice",title:"Brené Brown · I Thought It Was Just Me (2007) y brenebrown.com",url:"https://brenebrown.com/",type:"technique",finding:"Brown distingue la vergüenza (la sensación dolorosa de que algo falla en ti y no mereces aceptación) de la culpa (malestar por algo que hiciste) y presenta la resiliencia a la vergüenza como un conjunto de habilidades: reconocer la vergüenza y sus detonantes, comprobar con la realidad los mensajes que hay detrás, acercarse a otros y hablar de la vergüenza.",limitation:"Es un libro y un sitio web populares basados en la investigación cualitativa de la autora; las prácticas no se han probado como intervención."}],g={id:"compassion",title:"¿Te castigas por cada error? Cómo ponerte de tu lado y volver a intentarlo",subtitle:"6 lecciones de 8 a 12 minutos. Revisa una crítica hacia ti y elige una respuesta justa y útil.",description:"¿Y si la voz en tu cabeza pudiera ser honesta y estar de tu lado al mismo tiempo? Este curso explora lo que dicen la investigación y la práctica sobre la autocompasión, y cómo puede hacer que asumir la responsabilidad sea más fácil, no más difícil.",scope:"Para adultos que son duros consigo mismos después de errores, contratiempos o momentos dolorosos. Es un curso educativo con ejercicios personales. No es terapia. Si tienes un trauma, sufres abuso o sientes una vergüenza persistente o abrumadora, trabaja con un profesional cualificado; los ejercicios de autocompasión a veces pueden remover dolores antiguos. Si estás en una crisis o piensas en hacerte daño, llama ahora al número de emergencias de tu zona.",outcome:"Una idea clara de lo que es y lo que no es la autocompasión, una pausa de autocompasión de dos minutos para los momentos difíciles, una forma de reconocer tus sistemas de amenaza, impulso y calma, un plan para la próxima vez que sientas vergüenza y una carta compasiva que termina en un paso concreto y responsable.",photo:{id:"1470252649378-9c29740c9fa8",alt:"Un campo tranquilo bajo la cálida luz del atardecer"},lessons:[{id:"compassion-1",title:"La compasión no es debilidad",minutes:8,goal:"Descubre por qué ser amable contigo después de un fracaso puede ayudarte a hacerlo mejor, sin dejar de exigirte.",reading:["Muchas personas creen que su voz crítica interior es lo que las mantiene a raya. Piensan que, si dejaran de ser duras consigo mismas, se volverían perezosas, descuidadas o egoístas. La psicóloga Kristin Neff, que desarrolló la investigación moderna sobre este tema, describe la autocompasión de una manera muy distinta: darte a ti mismo la misma calidez y comprensión que le ofrecerías a un buen amigo que está pasando un mal momento. Eso no significa fingir que nada salió mal. Un buen amigo también ve el error. Simplemente no le suma desprecio, y se queda de tu lado mientras averiguas qué hacer después.","La investigación sugiere que tratarte con amabilidad no significa rendirte. En una serie de experimentos de Juliana Breines y Serena Chen, las personas a las que se animó a mirar con autocompasión una debilidad, un error moral o un examen suspendido se sintieron más motivadas a mejorar. Era más probable que creyeran que la debilidad podía cambiar y estaban más dispuestas a reparar el daño, y tras suspender un examen dedicaron más tiempo a estudiar para el siguiente. Los grupos de comparación, incluido uno que recibió un impulso a la autoestima, no mostraron el mismo patrón. La dureza puede parecer responsabilidad. A menudo solo añade miedo."],deeper:[{heading:"Por qué el crítico parece tan útil",paragraphs:["La autocrítica suele empezar como protección. Si te criticas tú primero, nadie más puede sorprenderte con ello, y el dolor parece una prueba de que te importa. El problema es cómo afecta el miedo a tus ganas de esforzarte. Cuando un error significa un ataque, la manera más fácil de evitar el ataque es evitar mirar el error: excusas, culpar a otra persona o no volver a intentarlo.","La autocompasión hace menos doloroso mirar el error. Cuando la respuesta a un fracaso es apoyo y no castigo, resulta más seguro admitir lo que pasó y estudiarlo. Esa es la lógica detrás de los hallazgos de Breines y Chen, y es la razón por la que este curso une una y otra vez la amabilidad con la responsabilidad."],visual:{kind:"table",title:"Creencias comunes sobre la autocompasión",columns:["Creencia común","Lo que sugieren la evidencia y las definiciones"],rows:[["Me hará perezoso.","En experimentos de laboratorio aumentó el esfuerzo por mejorar, como más tiempo de estudio tras un examen suspendido."],["Es solo autoestima.","La autoestima depende de sentirte bien o especial en comparación con otros; la autocompasión no tiene que ganarse."],["Es lástima de mí mismo.","La lástima de uno mismo se queda atrapada en el “¿por qué a mí?”; la autocompasión recuerda que todos pasan por dificultades."],["Me deja libre de responsabilidad.","Su lado firme incluye poner límites y perseguir metas."]],note:"Resumen de Breines & Chen (2012) y de las definiciones de Kristin Neff."}},{heading:"Lo que dice la investigación y lo que no",paragraphs:["En 56 ensayos aleatorizados, los programas de autocompasión mostraron reducciones a corto plazo, de pequeñas a medianas, en el estrés, la ansiedad y los síntomas depresivos, aunque el riesgo general de sesgo en esos estudios era alto. Un metaanálisis independiente de 27 ensayos aleatorizados halló mejoras en resultados como la rumiación, la autocrítica, el estrés y la depresión. Son efectos reales pero modestos, medidos sobre todo a lo largo de semanas o meses.","Breines y Chen estudiaron sobre todo a estudiantes universitarios y midieron la motivación a corto plazo. Así que no podemos afirmar que la autocompasión garantice el éxito. Sí podemos decir que puedes tratarte con amabilidad y exigirte a la vez."]}],example:{title:"Daniel, 34 años, gerente de proyectos",text:"Daniel no cumplió la fecha de entrega de un informe para un cliente porque había subestimado cuánto tardaría la depuración de los datos. En el tren de regreso a casa, su cabeza repetía el guion de siempre: descuidado, poco profesional, siempre haces lo mismo. Notó que también estaba redactando excusas para enviarle a su jefe. Probó con otra pregunta: ¿qué le diría a un colega en la misma situación? Probablemente que había sido un fallo real, que les pasa a las buenas personas y que lo útil ahora era una nueva fecha y una mejor estimación la próxima vez. Lo escribió en su teléfono. A la mañana siguiente le contó a su jefe con claridad lo ocurrido, le dio una fecha realista y añadió una línea para prever un margen de tiempo a su plantilla de planificación. El informe salió con dos días de retraso. Siguió usando la plantilla modificada."},practice:["Escribe, palabra por palabra, la última frase dura que te dijiste después de un error.","Reescríbela como se la dirías a un buen amigo en la misma situación, conservando los hechos pero sin el desprecio.","Añade una frase que nombre un siguiente paso concreto, para que la versión amable siga apuntando a hacerlo mejor."],reflection:"¿Qué temes que pasaría si dejaras de ser duro contigo mismo?",question:"En los experimentos de Breines y Chen, ¿qué ocurrió cuando las personas miraron un fracaso con autocompasión?",options:["Se sintieron más motivadas a mejorar, por ejemplo estudiando más tiempo tras un examen suspendido.","El resultado dejó de importarles.","Se sintieron mejor pero no se esforzaron más que los demás."],correct:0,feedback:"En comparación con las condiciones que reforzaban la autoestima o eran neutras, la autocompasión aumentó la motivación para mejorar y para reparar el daño. La amabilidad redujo el miedo a mirar el error.",takeaway:"Puedes exigirte mucho y aun así estar de tu propio lado.",sources:["state-self-compassion-motivation","compassion-neff-definition","compassion-neff-exercises","self-compassion","compassion-ferrari"],visual:{kind:"compare",title:"Después de un error: ¿crítico interno o entrenador interno?",left:{label:"Crítico interno",items:["Ataca a la persona: no sirvo para nada.","Hace que mirar el error duela, y por eso lo evitas.","Añade miedo al siguiente intento."]},right:{label:"Entrenador compasivo",items:["Nombra la conducta: esa estimación no fue acertada.","Permite examinar lo que pasó sin miedo.","Señala un siguiente paso."]},note:"Resumen propio del contraste entre el autojuicio y la amabilidad hacia uno mismo."},technique:{name:"¿Cómo tratarías a un amigo?",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Piensa en una ocasión en que un amigo cercano se sintió mal por un error o una dificultad, y recuerda cómo respondiste, incluidas tus palabras y tu tono.","Ahora piensa en una ocasión en que te sentiste mal contigo, y recuerda cómo te respondiste a ti mismo.","Observa la diferencia entre las dos respuestas y pregúntate qué la impulsa.","Escribe cómo podrías responderte si te trataras como tratas a ese amigo.","Prueba esa respuesta la próxima vez que pases por un mal momento y observa qué cambia."],evidence:"Este ejercicio de reflexión no se ha probado por sí solo. Apunta al núcleo de la autocompasión tal como la define Neff, y los programas de autocompasión que incluyen ejercicios como este muestran beneficios a corto plazo, de pequeños a medianos, en ensayos aleatorizados.",sourceId:"compassion-neff-exercises"},photo:{id:"1474418397713-7ede21d49118",alt:"Una persona sentada en una roca viendo salir el sol sobre las montañas"}},{id:"compassion-2",title:"Las tres partes",minutes:9,goal:"Conoce los tres componentes de la autocompasión según Neff e identifica el que más sueles pasar por alto.",reading:["Neff describe la autocompasión como tres partes que trabajan juntas. La primera es la amabilidad hacia ti mismo en lugar del autojuicio: ser cálido y comprensivo contigo cuando pasas por un mal momento, en vez de frío e hiriente. La segunda es la humanidad compartida en lugar del aislamiento: recordar que el sufrimiento y la imperfección forman parte de ser humano y no demuestran que solo tú tienes ese problema. La tercera es la atención plena en lugar de la sobreidentificación: ver con claridad un sentimiento doloroso, sin apartarlo y sin dejar que ocupe todo el espacio. Cada parte tiene un opuesto que casi todos conocemos bien, y cada una apoya a las otras dos.","Las partes se ven con más facilidad cuando falta una. La amabilidad sin atención plena puede convertirse en apresurarte a sentirte mejor antes de haber admitido siquiera lo que duele. La atención plena sin humanidad compartida puede dejarte viendo tu dolor con claridad pero sintiéndote completamente solo en él. La humanidad compartida sin amabilidad puede sonar indiferente: todos fallan, ¿y qué? Juntas suenan más bien así: esto duele, otras personas han estado aquí también, y puedo tratarme con decencia mientras lo afronto. No necesitas sentir las tres con fuerza. Notar cuál es la más débil en ti es un buen comienzo."],deeper:[{heading:"Lo que la autocompasión no es",paragraphs:["Neff separa la autocompasión de tres conceptos con los que se suele confundir. La autoestima depende de juzgarte de forma positiva, a menudo sintiéndote especial o por encima del promedio, y por eso tiende a desaparecer justo cuando fallas. La lástima de uno mismo se centra en tus propios problemas y olvida que otras personas también los tienen. La indulgencia excesiva cambia el bienestar a largo plazo por el placer a corto plazo. La autocompasión, en su descripción, ofrece un sentido de valía más estable que no tiene que ganarse."],visual:{kind:"compare",title:"Dos preguntas distintas",left:{label:"La autoestima pregunta",items:["¿Soy mejor que los demás?","¿Tuve éxito esta vez?","¿Soy lo bastante bueno para merecer respeto?"]},right:{label:"La autocompasión pregunta",items:["¿Qué necesito ahora mismo?","¿Qué me ayudaría a aprender de esto?","¿Cómo puedo cuidarme mientras lo arreglo?"]},note:"Ilustración propia de la distinción que traza Kristin Neff."}},{heading:"Errores comunes",paragraphs:["El primer error es tratar la autocompasión como un sentimiento que debes producir. No tienes que sentir calidez; la intención de ser amable ya cuenta. El segundo es usar las tres partes para esquivar la responsabilidad, por ejemplo diciendo que todos cometen errores y luego no reparando el que cometiste. La humanidad compartida sirve para reducir el aislamiento, sin eliminar la responsabilidad.","El tercer error es esperar que resulte natural desde el primer momento. Si llevas años hablándote con dureza, tratarte con amabilidad puede resultar extraño o incluso incómodo al principio. Mantén la práctica breve y sencilla, y toma la incomodidad como parte de aprender algo nuevo."]}],example:{title:"Aisha, 27 años, médica residente",text:"Después de un turno largo, Aisha se sentó con un cuaderno. Ese día había pasado por alto una interacción entre fármacos que la farmacéutica detectó. Su primera línea fue puro juicio: soy peligrosa, nunca debí titularme. Debajo escribió las tres partes. Atención plena: siento miedo y vergüenza, y tengo el pecho apretado. Humanidad compartida: los errores de interacción son un riesgo conocido, y por eso los farmacéuticos revisan dos veces, y colegas a quienes respetaba le habían contado errores que habían estado a punto de cometer. Amabilidad: estoy cansada, y esto duele porque me importan mis pacientes. Luego añadió lo que haría: leer sobre esa clase de fármacos y preguntarle a su supervisor cómo señala el equipo estas interacciones. No se sintió genial. Sí durmió, y al día siguiente hizo las dos cosas."},practice:["Recuerda un momento difícil reciente y escribe una frase para cada parte: lo que sientes, quién más ha vivido algo parecido y una cosa amable que puedes decirte.","Marca la frase que más te costó escribir; esa es la parte que puedes practicar esta semana.","Antes de que termine el día, usa esa parte más difícil una vez más en un pequeño momento de estrés."],reflection:"¿Cuál de los tres opuestos te resulta más familiar: el autojuicio, el aislamiento o sentir que la emoción lo ocupa todo?",question:"¿Qué opción enumera los tres componentes de la autocompasión según Neff?",options:["Amabilidad hacia uno mismo, humanidad compartida y atención plena.","Autoestima, pensamiento positivo y confianza.","Autodisciplina, perfeccionismo y resiliencia."],correct:0,feedback:"Neff empareja cada parte con un opuesto: la amabilidad hacia uno mismo con el autojuicio, la humanidad compartida con el aislamiento y la atención plena con la sobreidentificación.",takeaway:"Esto duele, no soy el único al que le pasa y puedo ser amable conmigo mientras lo afronto.",sources:["compassion-neff-definition","compassion-neff-exercises","self-compassion"],visual:{kind:"table",title:"Tres partes y sus opuestos",columns:["Parte","Su opuesto","Cómo puede sonar"],rows:[["Amabilidad hacia uno mismo","Autojuicio","Esto es difícil, y estoy haciendo lo mejor que puedo."],["Humanidad compartida","Aislamiento","Otras personas también pasan por esto."],["Atención plena","Sobreidentificación","Noto que ahora mismo siento vergüenza."]],note:"Componentes de Kristin Neff; las frases de ejemplo son propias."},technique:{name:"Diario de autocompasión",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Al final del día, anota todo lo que te hizo sentir mal, todo por lo que te juzgaste o cualquier experiencia difícil.","Para la atención plena, nombra los sentimientos tal como son, sin dramatismo y sin descartarlos.","Para la humanidad compartida, escribe cómo esta experiencia te conecta con otras personas que han sentido lo mismo.","Para la amabilidad hacia ti mismo, escríbete unas palabras comprensivas y de apoyo, con el tono que usarías con un amigo.","Sé breve; unas pocas líneas cada noche bastan."],evidence:"El diario no se ha probado por sí solo. La evidencia corresponde a los programas de autocompasión en su conjunto, que muestran beneficios a corto plazo, de pequeños a medianos, en ensayos aleatorizados.",sourceId:"compassion-neff-exercises"},photo:{id:"1529156069898-49953e39b3ac",alt:"Amigos sentados del brazo, vistos de espaldas"}},{id:"compassion-3",title:"La pausa de autocompasión",minutes:8,goal:"Aprende una práctica de dos minutos para el momento en que algo duele.",reading:["La pausa de autocompasión es la práctica breve de Neff para cuando algo duele: el correo que lamentas haber enviado, la mala noticia, la discusión que acaba de terminar. Sigue las tres partes en orden. Primero reconoces que este es un momento de sufrimiento, con palabras sencillas, como esto duele o esto es estresante. Luego te recuerdas que la dificultad es parte de la vida y que otras personas también se sienten así. Por último te ofreces algo de amabilidad, a menudo con una mano sobre el corazón u otro contacto suave, y te preguntas qué necesitas oír ahora mismo.","Importa más la intención que las palabras. Algunas personas encuentran demasiado dramática la idea de un momento de sufrimiento y prefieren algo como uf, esto es difícil. A otras no les gusta la mano en el pecho y apoyan una mano en el brazo, o simplemente sueltan el aire despacio. La idea es reconocer el dolor en lugar de evitarlo, recordar que no eres la única persona a quien le pasa y tratarte con cariño. La práctica lleva unos dos minutos. No pretende arreglar el problema, pero puede ayudarte a recuperar la calma suficiente para afrontarlo."],deeper:[{heading:"¿Por qué un gesto de contacto?",paragraphs:["Neff propone un gesto de contacto porque el contacto cálido y suave es una de las formas más básicas en que se calma a las personas, desde la infancia. Puedes probarlo aunque no estés convencido de que vaya a ayudarte. Muchas personas encuentran que una mano en el pecho o un suave apretón en su propio brazo ayuda a sentir las palabras amables de forma más concreta.","Si el contacto no te resulta seguro o agradable, sáltalo. La práctica funciona mediante la atención y el tono, no mediante un gesto en particular."],visual:{kind:"compare",title:"Cómo afrontar un momento doloroso",left:{label:"Apartarse",items:["Distraerte, pasar contenido en el móvil o seguir adelante sin reconocer lo que sientes.","Decirte que no deberías sentirte así.","Repetir lo que hiciste mal."]},right:{label:"Reconocer el dolor",items:["Nombrarlo: esto es difícil.","Recordar que otros también lo sienten.","Ofrecerte una frase o un gesto amable."]},note:"Resumen propio de la lógica de la pausa de autocompasión."}},{heading:"Lo que dice la investigación",paragraphs:["La pausa de autocompasión forma parte de la autocompasión consciente (Mindful Self-Compassion), un programa de ocho semanas desarrollado por Neff y el psicólogo Christopher Germer. En su ensayo aleatorizado con adultos de la población general, las personas que hicieron el programa mostraron mayores aumentos en la autocompasión, la atención plena, la compasión hacia los demás y la satisfacción con la vida, y mayores descensos en la depresión, la ansiedad y el estrés, que las personas en lista de espera. Las mejoras seguían ahí seis meses y un año después.","Fue un ensayo pequeño, la comparación fue con una lista de espera y no con otro curso activo, y los propios creadores lo dirigieron. La pausa de dos minutos no se ha probado por sí sola. Lo mejor es verla como una pieza práctica de un programa con un respaldo prometedor, no definitivo."]},{heading:"Si despierta un dolor antiguo",paragraphs:["A veces la amabilidad hacia ti mismo hace aflorar un dolor antiguo, como el calor puede hacer que unas manos frías duelan al principio. Eso no es señal de que lo estés haciendo mal. Haz la práctica más corta, abre los ojos, siente los pies en el suelo, o detente y haz algo cotidiano. Si los recuerdos dolorosos siguen inundándote, o están vinculados con un trauma o un abuso, trabaja con un terapeuta cualificado en lugar de seguir solo."]}],example:{title:"Tomás, 45 años, conductor de autobús",text:"Tomás recibió una queja formal de una pasajera que dijo que le había cerrado las puertas encima. Él no la había visto, y se sintió mal durante todo su descanso. Sentado en la cantina de la cochera, probó por primera vez la pausa de autocompasión. Se dijo para sí: esto es muy estresante. Luego: todos los conductores que conocía habían tenido una queja en algún momento. Apoyó una mano en el antebrazo, que le resultó menos raro que el pecho, y se preguntó qué necesitaba oír. La respuesta fue sencilla: eres cuidadoso, y puedes afinar tu rutina. El nudo no desapareció, pero se aflojó. Le escribió a su supervisor una respuesta serena que incluía un cambio: una revisión extra del espejo antes de cerrar las puertas en las paradas concurridas."},practice:["Recuerda un pequeño momento de estrés de hoy hasta que notes un poco de esa sensación en el cuerpo.","Di en silencio tres frases: una que nombre el dolor, una que recuerde que otros también lo sienten y un deseo amable para ti.","Añade un gesto suave si te parece bien y luego escribe una línea sobre lo que necesitas a continuación."],reflection:"¿Qué palabras te sonarían a la vez amables y creíbles en un momento difícil?",question:"¿Cuál es el orden de la pausa de autocompasión?",options:["Reconocer el dolor, recordar la humanidad compartida y luego ofrecerte amabilidad.","Resolver primero el problema y luego intentar sentirte mejor al respecto.","Enumerar tus logros hasta que pase el sentimiento."],correct:0,feedback:"La pausa sigue las tres partes de Neff: atención plena al dolor, humanidad compartida y luego amabilidad hacia ti mismo. Te ayuda a recuperar la calma para que puedas afrontar el problema; no sustituye ese paso.",takeaway:"Dos minutos de atención al dolor pueden ayudarte a recuperar la calma suficiente para afrontarlo.",sources:["compassion-neff-exercises","compassion-mindful-self-compassion-rct","compassion-neff-definition"],visual:{kind:"steps",title:"La pausa de autocompasión",steps:[{label:"Nómbralo",text:"Esto duele. Esto es estresante. Uf."},{label:"Recuerda a los demás",text:"Otras personas también sienten esto; no soy el único al que le pasa."},{label:"Ofrece amabilidad",text:"Una mano sobre el pecho o en el brazo, y el deseo de ser amable contigo."},{label:"Pregunta",text:"¿Qué necesito oír, o hacer, ahora mismo?"}],note:"Contada con nuestras propias palabras a partir de la práctica de Kristin Neff; elige frases que te resulten naturales."},technique:{name:"Pausa de autocompasión",origin:"Kristin Neff · Self-Compassion (2011); programa Mindful Self-Compassion con Christopher Germer",steps:["Trae a la mente una situación que te está causando estrés o dolor ahora mismo y deja que sientas un poco de ella.","Reconoce el dolor con palabras sencillas, como esto duele o esto es difícil.","Recuérdate que la dificultad forma parte de ser humano y que otras personas también se sienten así.","Coloca una mano sobre el pecho u otro lugar que te reconforte y siente su calidez.","Ofrécete un deseo amable o pregúntate qué necesitas oír, y dítelo."],evidence:"La pausa es parte del programa Mindful Self-Compassion, que mostró beneficios frente a una lista de espera en un pequeño ensayo aleatorizado con seguimiento hasta un año. La pausa breve por sí sola no se ha probado en un ensayo.",sourceId:"compassion-neff-exercises"},photo:{id:"1499209974431-9dddcece7f88",alt:"Una persona abriendo los brazos hacia el sol poniente"}},{id:"compassion-4",title:"Amenaza, impulso y calma",minutes:10,goal:"Usa el modelo de tres sistemas de Paul Gilbert para notar qué sistema predomina y cómo recurrir a la calma.",reading:["El psicólogo británico Paul Gilbert desarrolló la terapia centrada en la compasión, o CFT, tras notar que muchas personas con mucha vergüenza y autocrítica podían seguir la lógica de la terapia pero seguían sin sentir calidez ni tranquilidad. Su modelo describe tres sistemas emocionales. El sistema de amenaza detecta el peligro y responde con ansiedad, ira o asco, empujándote a luchar, huir o paralizarte. El sistema de impulso busca recompensas y logros y trae emoción y deseo. El sistema de calma trae una sensación de seguridad, satisfacción y conexión cuando no estás bajo amenaza ni persiguiendo algo.","Los tres son útiles. Los problemas empiezan cuando se desequilibran. Un crítico interno duro mantiene encendido el sistema de amenaza, y muchas personas intentan escapar de él sobrecargando el sistema de impulso: si logro lo suficiente, por fin me sentiré seguro. Eso rara vez dura, porque el logro no es lo que el sistema de amenaza está esperando. La idea de Gilbert es que la compasión, incluida la compasión hacia ti mismo, fortalece el sistema de calma, que puede calmar la amenaza desde dentro. Respirar más despacio, una voz interior cálida, la imagen de un rostro amable y la sensación de ser cuidado son formas de activar ese sistema."],deeper:[{heading:"Cómo se siente cada sistema",paragraphs:["Ayuda reconocer las señales de cada sistema en tu propio cuerpo y en tus pensamientos. No puedes convencer a un sistema de que se apague, pero sí puedes notar cuál está al mando y elegir qué reforzar."],visual:{kind:"table",title:"Los tres sistemas de un vistazo",columns:["Sistema","Cómo se manifiesta","Pensamiento típico","Qué ayuda"],rows:[["Amenaza","Pecho tenso, corazón acelerado, ira o pavor","Algo va mal; no estoy a salvo.","Ir más despacio, señales de seguridad, una voz amable"],["Impulso","Energía, deseo, inquietud","Necesito conseguir o lograr más.","Disfrutarlo y luego hacer una pausa a propósito"],["Calma","Respiración más lenta, calidez, alivio","Ahora mismo estoy bien.","Conexión, descanso, prácticas de compasión"]],note:"Basado en el modelo de Paul Gilbert; los ejemplos son una simplificación propia."}},{heading:"Lo que dice la investigación",paragraphs:["El modelo de tres sistemas es un marco clínico que se apoya en la investigación sobre la evolución y el cerebro, no un mapa preciso de circuitos cerebrales, y Gilbert lo presenta como una simplificación. La evidencia de la CFT como terapia crece, aunque aún es inicial.","La investigación sobre ejercicios de amabilidad ayuda a entender la magnitud de los efectos. Un metaanálisis de la meditación de bondad amorosa y compasión halló que, en estudios aleatorizados, estas prácticas aumentaban las emociones positivas cotidianas en comparación con las listas de espera. Las prácticas centradas en la bondad amorosa mostraron un efecto más claro que las centradas en la compasión, cuya estimación fue menor y no alcanzó la certeza estadística."],visual:{kind:"bars",title:"Meditación de bondad y emociones positivas diarias",bars:[{label:"Centrada en la bondad amorosa",value:.424,display:"g = 0.424"},{label:"Centrada en la compasión",value:.286,display:"g = 0.286"}],note:"Tamaños del efecto estandarizados de un metaanálisis de 24 estudios con 1,759 personas. La estimación centrada en la compasión tenía un intervalo de confianza que incluía el cero, y el 38.9% de los estudios tenía un alto riesgo de sesgo. No es una prueba de la CFT ni de esta lección.",sourceId:"meditation-lovingkindness"}}],example:{title:"Mei, 38 años, contadora",text:"En la última semana del trimestre, Mei notó que llevaba tres noches seguidas respondiendo correos a medianoche. Usando el modelo de Gilbert, se preguntó qué sistema predominaba. El impulso, claramente, pero debajo de él la amenaza: el miedo a que un solo error pasado por alto la dejara en evidencia como incompetente. Más trabajo estaba reforzando el sistema equivocado. Esa noche puso un temporizador de cinco minutos, hizo más lenta su respiración hasta que cada exhalación fuera un poco más larga que la inhalación, y dejó que la voz en su cabeza sonara como la de una jefa amable que tuvo una vez. El primer minuto le pareció una tontería. Al final había relajado los hombros. Cerró el portátil a las diez, dejó una nota con tres tareas para la mañana y durmió mejor que en toda la semana."},practice:["Haz una pausa tres veces hoy y pregúntate qué sistema predomina ahora mismo: amenaza, impulso o calma.","Cuando sea la amenaza, haz más lenta tu respiración durante un minuto, dejando que cada exhalación sea un poco más larga que la inhalación.","Imagina una presencia cálida y sabia, real o imaginaria, y deja que te diga una frase amable."],reflection:"Cuando se dispara tu sistema de amenaza, ¿sueles intentar calmarlo o compensarlo buscando más logros?",question:"En el modelo de Gilbert, ¿qué sistema ayuda a calmar el sistema de amenaza desde dentro?",options:["El sistema de calma, alimentado por la seguridad, la conexión y la compasión.","El sistema de impulso, logrando más.","El propio sistema de amenaza, planeando para cada peligro."],correct:0,feedback:"El logro puede distraer de la amenaza durante un tiempo, pero en el modelo de Gilbert es el sistema de calma, construido con calidez y conexión, el que produce una sensación de seguridad.",takeaway:"No puedes salir de la inseguridad a base de logros, pero puedes aprender a calmarte.",sources:["compassion-gilbert-cft","compassion-gilbert-mind","meditation-lovingkindness"],visual:{kind:"cycle",title:"Tres sistemas emocionales",center:"Equilibrio",nodes:[{label:"Amenaza",text:"Detecta el peligro: ansiedad, ira, autocrítica. Te protege, pero limita la atención."},{label:"Impulso",text:"Busca recompensas y metas: deseo, emoción, logro."},{label:"Calma",text:"Seguridad, satisfacción y conexión; calma la amenaza y estabiliza el impulso."}],note:"Según la terapia centrada en la compasión de Paul Gilbert. Los sistemas interactúan y ninguno es malo."},technique:{name:"Respiración a un ritmo calmante y yo compasivo",origin:"Paul Gilbert · The Compassionate Mind (2009)",steps:["Siéntate cómodamente con los pies en el suelo y deja que tu respiración se haga un poco más lenta, sin forzarla.","Deja que cada exhalación sea un poco más larga que la inhalación y encuentra un ritmo suave y parejo.","Suaviza el rostro y, si te ayuda, adopta una expresión amable y relajada.","Imagínate en tu versión más sabia y más amable: tranquila, fuerte y cuidadosa. Observa cómo se sentaría y hablaría esa versión de ti.","Desde ahí, dile una frase a la parte de ti que está pasando un mal momento."],evidence:"Son ejercicios centrales de la terapia centrada en la compasión. La CFT es un enfoque en desarrollo, con evidencia inicial pero alentadora; los ejercicios no se han probado aquí como autoayuda independiente y no sustituyen la terapia.",sourceId:"compassion-gilbert-mind"},photo:{id:"1441974231531-c6227db76b6e",alt:"La luz del sol filtrándose por un bosque en calma"}},{id:"compassion-5",title:"Vergüenza y culpa",minutes:10,goal:"Distingue la vergüenza de la culpa y usa cuatro pasos para afrontar la vergüenza en lugar de esconderte.",reading:["La investigadora Brené Brown hace una distinción sencilla entre ambas. La culpa tiene que ver con algo que hiciste: eso estuvo mal. La vergüenza tiene que ver con quién eres: soy malo. La distinción se apoya en la investigación de la psicóloga June Tangney y sus colegas. La culpa se centra en una conducta específica y tiende a apuntar a la reparación: pedir perdón, confesar, arreglar las cosas. La vergüenza se dirige a toda tu persona. Hace que las personas quieran esconderse, negar o arremeter, y en la investigación se asocia con la ira, la actitud defensiva y el malestar, más que con hacerlo mejor. La culpa puede ser incómoda y aun así útil. La vergüenza suele hacerte sentir pequeño.","A partir de su investigación con entrevistas, Brown desarrolló lo que llama resiliencia a la vergüenza: no evitar la vergüenza, algo que nadie logra, sino atravesarla sin perderte a ti mismo. Describe cuatro elementos. Reconoce la vergüenza y conoce tus detonantes, incluido cómo aparece en tu cuerpo. Practica la conciencia crítica, es decir, contrasta con la realidad los mensajes y las expectativas que hay detrás de la vergüenza. Acércate a alguien de confianza y cuéntale tu historia. Y habla de la vergüenza: nómbrala en voz alta en lugar de dejar que actúe en silencio. La autocompasión apoya cada paso, porque convierte un veredicto global en un hecho concreto con el que puedes lidiar."],deeper:[{heading:"Los cuatro elementos en la práctica",paragraphs:["El estudio de Brown describió la resiliencia a la vergüenza como un conjunto de habilidades y no como un rasgo fijo, lo que significa que se puede practicar. Los pasos siguientes cuentan sus cuatro elementos con nuestras propias palabras. No tienes que seguirlos en un orden perfecto; reconocer la vergüenza suele ser la parte más difícil y más importante."],visual:{kind:"steps",title:"Cuatro elementos de la resiliencia a la vergüenza",steps:[{label:"Reconoce",text:"Observa las señales del cuerpo y las situaciones que te provocan vergüenza."},{label:"Contrasta con la realidad",text:"Pregúntate de quién son estas expectativas y si son realistas."},{label:"Acércate",text:"Cuéntale a una persona de confianza lo que pasó, en lugar de esconderlo."},{label:"Habla de la vergüenza",text:"Nombra el sentimiento en voz alta: siento vergüenza por esto."}],note:"Según la teoría de la resiliencia a la vergüenza de Brené Brown; la redacción es nuestra."}},{heading:"Por qué la culpa puede ayudar y la vergüenza rara vez",paragraphs:["En la investigación de Tangney, las personas propensas a la culpa tendían a mostrar más empatía y a emprender acciones reparadoras, mientras que las propensas a la vergüenza tenían más probabilidad de esconderse, sentir ira defensiva y culpar a otros. Eso no hace agradable la culpa, y la culpa intensa por cosas que no causaste es un problema en sí misma. Pero un sentido claro y proporcionado de haber hecho algo mal es parte de una conciencia que funciona.","La autocompasión ayuda a llevar la vergüenza hacia una culpa sana. Cuando no tienes que defender todo tu valor, puedes examinar lo que hiciste y decidir cómo repararlo."]},{heading:"Cuándo buscar más ayuda",paragraphs:["La vergüenza que es persistente, que te sigue en muchas situaciones o que está ligada a un trauma o un abuso requiere más apoyo que un ejercicio de cuatro pasos. Un terapeuta cualificado puede ayudar, y la terapia centrada en la compasión se diseñó pensando en la vergüenza intensa. Si alguna vez la vergüenza viene acompañada de pensamientos de hacerte daño, llama ahora al número de emergencias de tu zona o a una línea de ayuda en crisis."]}],example:{title:"Jonas, 31 años, maestro",text:"Jonas habló con brusquedad a un alumno delante de la clase, y el chico se quedó callado el resto de la lección. Para la hora del almuerzo, Jonas había pasado de lo manejé mal a soy un maestro terrible y no debería hacer este trabajo. Reconoció el calor familiar en la cara y el impulso de evitar la sala de profesores. Entonces contrastó con la realidad: un momento duro en seis años, en un día con muy poco sueño, no anulaba toda su trayectoria. Se acercó a una colega de confianza y le contó lo ocurrido. Al decirlo en voz alta, pudo separar las dos cosas: no era un mal maestro, pero había hecho algo que necesitaba reparación. A la mañana siguiente le pidió perdón al alumno en privado y le preguntó cómo estaba."},practice:["Recuerda un momento reciente en que te sentiste mal contigo y escribe la frase exacta que tenías en la cabeza.","Comprueba si es culpa por una acción o vergüenza por todo tu ser, y reescribe cualquier frase de vergüenza como una conducta específica.","Decide si esa conducta necesita reparación y, si es así, nombra el paso honesto más pequeño, como una disculpa o una corrección."],reflection:"¿A quién podrías acudir la próxima vez que la vergüenza te haga querer esconderte?",question:"¿Cuál de estas afirmaciones es culpa y no vergüenza?",options:["Fui grosero con ella y necesito pedirle perdón.","Soy una persona horrible.","Siempre lo arruino todo."],correct:0,feedback:"La culpa se centra en una conducta específica y apunta a la reparación. Las otras dos son juicios sobre toda tu persona, que es como habla la vergüenza.",takeaway:"Nombra lo que hiciste, no lo que eres, y repara lo que puedas.",sources:["compassion-brown-shame-resilience","compassion-brown-practice","compassion-tangney-moral-emotions","compassion-gilbert-cft"],visual:{kind:"compare",title:"¿Vergüenza o culpa?",left:{label:"Vergüenza",items:["Soy malo.","Se centra en toda la persona.","Te empuja a esconderte, negar o culpar a otros.","Asociada con ira defensiva y malestar."]},right:{label:"Culpa",items:["Hice algo malo.","Se centra en una acción específica.","Te empuja hacia la disculpa y la reparación.","Asociada con la empatía."]},note:"Según la investigación de June Tangney y la distinción de Brené Brown. La culpa excesiva también puede ser dañina."},technique:{name:"Resiliencia a la vergüenza",origin:"Brené Brown · I Thought It Was Just Me (2007)",steps:["Cuando te sientas expuesto, pequeño o sin valor, nombra el sentimiento para ti como vergüenza.","Observa dónde lo sientes en el cuerpo y qué situación lo desencadenó.","Contrasta el mensaje con la realidad: ¿de quién es esta expectativa y es realista?","Acércate a una persona de confianza y cuéntale lo que pasó.","Habla directamente de la vergüenza y pide lo que necesitas."],evidence:"La teoría de la resiliencia a la vergüenza proviene de una investigación cualitativa con entrevistas, que describe patrones en lugar de poner a prueba una intervención. La distinción entre vergüenza y culpa en que se apoya está bien respaldada por la investigación sobre las emociones morales.",sourceId:"compassion-brown-practice"},photo:{id:"1544027993-37dbfe43562a",alt:"Dos manos que se tienden una hacia la otra"}},{id:"compassion-6",title:"Una carta para ti: amabilidad y responsabilidad",minutes:12,goal:"Escribe una carta compasiva sobre algo que lamentas o no te gusta de ti, y conviértela en un paso responsable.",reading:["El ejercicio de la carta de Neff te pide escribir sobre algo que te hace sentir mal contigo, como un error, un hábito o un rasgo, desde el punto de vista de un amigo imaginario que te quiere incondicionalmente. Ese amigo conoce todas tus fortalezas y debilidades, incluido aquello con lo que estás luchando. Entiende cómo tu historia y tus circunstancias te moldearon, y es amable sin ignorar los problemas. Escribir con su voz te da algo de distancia de tu voz crítica. También tiende a producir un relato más equilibrado de lo ocurrido que el que escribe tu sistema de amenaza.","Una carta compasiva no sirve para buscar excusas. El amigo que te quiere también querría que cambiaras lo que te daña a ti o a otros, y ahí es donde entra la responsabilidad. Neff llama a esto el lado firme de la autocompasión: protegerte, poner límites y perseguir metas porque te importa tu bienestar, no porque te rechaces. La autocompasión tierna consuela y acepta; la firme actúa. Así que termina tu carta con el amigo haciendo una pregunta práctica: con todo esto en mente, ¿qué podrías hacer de otra manera y qué apoyo te ayudaría a hacerlo?"],deeper:[{heading:"Cómo escribir la carta",paragraphs:["Reserva quince minutos en un lugar privado. Escribe a mano si puedes y no corrijas el estilo. Luego guarda la carta y vuelve a leerla más tarde, dejando que las palabras te lleguen."],visual:{kind:"steps",title:"Cómo escribir una carta compasiva",steps:[{label:"Elige",text:"Escoge una cosa por la que te sientes mal, no toda la historia de tu vida."},{label:"Imagina",text:"Visualiza a un amigo que te quiere incondicionalmente y conoce todo el contexto."},{label:"Escribe",text:"Deja que te diga lo que entiende, lo que siente por ti y lo que espera para ti."},{label:"Pregunta",text:"Termina con un cambio práctico y el apoyo que necesitarías."},{label:"Relee",text:"Guárdala, relee más tarde y observa cómo te hace sentir."}],note:"Contada con nuestras propias palabras a partir del ejercicio de la carta de Kristin Neff."}},{heading:"Tierna y firme, juntas",paragraphs:["La mayoría tendemos hacia un lado. Algunas personas se consuelan bien pero nunca ponen un límite; otras empujan con fuerza para cambiar pero nunca descansan. La idea de Neff es que ambas son formas de cuidado. Un padre que solo consuela y un padre que solo exige ofrecen cada uno la mitad de lo que necesita un niño.","La responsabilidad compasiva usa las dos. Nombra el daño con honestidad, siente la incomodidad sin dejar que la vergüenza lo domine todo, repara lo que se puede reparar y planea un cambio. Los hallazgos de Breines y Chen encajan aquí: cuando las personas afrontaron un error moral con autocompasión, se sintieron más motivadas a reparar el daño y a no repetirlo."]},{heading:"Lo que dice la investigación",paragraphs:["La carta es una de las prácticas que se enseñan en el programa Mindful Self-Compassion, cuyo ensayo aleatorizado halló beneficios frente a una lista de espera que se mantuvieron hasta el seguimiento a un año. Un metaanálisis de 27 ensayos aleatorizados de intervenciones de autocompasión halló mejoras en resultados como la rumiación, la autocrítica, la depresión y la ansiedad. La carta en sí no se ha probado de forma aislada, y la base de investigación sigue compuesta sobre todo por estudios pequeños, así que conviene tratarla como una práctica prometedora y no como un tratamiento probado."]}],example:{title:"Rosa, 52 años, dueña de una tienda",text:"Durante años Rosa había odiado cómo manejaba el dinero: evitaba abrir las cartas del banco hasta que se amontonaban. Escribió una carta para sí misma desde la perspectiva de un amigo imaginario que la conocía bien. El amigo entendía que había crecido en una casa donde las facturas significaban gritos, así que evitarlas la había mantenido a salvo en su momento. El amigo también dijo, con suavidad y claridad, que el montón la estaba dañando ahora y que merecía algo mejor que el pavor. Al final el amigo le pidió un cambio. Rosa eligió el sábado a las nueve, con un café en la mano, para abrir todas las cartas de la semana, y le pidió a su hijo que se sentara con ella la primera vez. Releyó la carta una semana después. El montón era más pequeño y el miedo, algo menos intenso."},practice:["Elige una cosa de ti por la que te sientes mal y pon un temporizador de quince minutos.","Escribe una carta para ti desde el punto de vista de un amigo que te quiere incondicionalmente y conoce todo el contexto.","Termina la carta con un cambio concreto y responsable y el apoyo que pedirás, y luego pon ese cambio en tu calendario."],reflection:"¿En cuál te apoyas más, en la autocompasión tierna o en la firme, y qué añadiría la otra?",question:"¿Cómo se une la autocompasión a la responsabilidad en esta lección?",options:["Combina el consuelo con nombrar honestamente el daño, repararlo y hacer un cambio concreto.","Significa no sentirte mal nunca por nada de lo que haces.","Significa castigarte lo suficiente para no repetir nunca el error."],correct:0,feedback:"La autocompasión tierna y la firme trabajan juntas: el consuelo evita que la vergüenza tome el control, y el cuidado firme convierte la lección en reparación y cambio.",takeaway:"Un amor que dice la verdad y luego te ayuda a hacer algo al respecto.",sources:["compassion-neff-exercises","compassion-neff-definition","compassion-mindful-self-compassion-rct","compassion-ferrari","state-self-compassion-motivation","self-compassion"],visual:{kind:"table",title:"Autocompasión tierna y firme",columns:["Pregunta","Tierna","Firme"],rows:[["Qué hace","Consuela, calma, acepta","Protege, pone límites, persigue metas"],["Cómo puede sonar","Esto es difícil, y estoy aquí contigo.","Esto no está bien, y voy a hacer algo al respecto."],["Cuándo puedes necesitarla","Estás sufriendo o de duelo.","Se ha cruzado un límite o una meta importa."],["Sin la otra","Puede derivar en evitación.","Puede convertirse en un trato duro."]],note:"Autocompasión tierna y firme según la describe Kristin Neff; la última fila es nuestra interpretación."},technique:{name:"Carta compasiva",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Elige algo de ti que te haga sentir insuficiente, avergonzado o no lo bastante bueno.","Imagina a un amigo que te quiere y te acepta incondicionalmente, conoce todas tus fortalezas y debilidades, y entiende tu historia.","Escríbete una carta desde la perspectiva de ese amigo sobre aquello con lo que estás luchando.","Deja que el amigo reconozca tu dolor, te recuerde que todos somos imperfectos y sugiera, con amabilidad, qué podría ayudarte a cambiar.","Deja la carta a un lado y vuelve más tarde a leerla despacio."],evidence:"La carta es parte del programa Mindful Self-Compassion, que mostró beneficios frente a una lista de espera en un pequeño ensayo aleatorizado. La carta no se ha probado por sí sola.",sourceId:"compassion-neff-exercises"},photo:{id:"1455390582262-044cdead277a",alt:"Una mano escribiendo con un bolígrafo en un cuaderno"}}]},y=Object.freeze(Object.defineProperty({__proto__:null,COURSE:g,SOURCES:b},Symbol.toStringTag,{value:"Module"})),v=[{id:"identity-dispenza-habit",title:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (Hay House, 2012)",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Dispenza presenta un programa de meditación de cuatro semanas: llevar la atención al cuerpo y al momento presente, reconocer y admitir el viejo patrón de pensamientos, emociones y reacciones que quieres cambiar, soltarlo, vigilarlo durante el día e interrumpirlo, y ensayar el nuevo yo en el que quieres convertirte, incluyendo cómo se siente ese yo.",limitation:"Tomar conciencia de los hábitos y ensayar una conducta nueva encaja bien con la investigación. La descripción de la editorial también promete que los lectores pueden reprogramar su biología y su genética con principios de la física cuántica; esas afirmaciones no cuentan con respaldo científico. Se leyó la página de la editorial; el programa en sí no se ha probado en ensayos controlados."},{id:"identity-dispenza-supernatural",title:"Dr. Joe Dispenza · Becoming Supernatural (Hay House, 2017)",url:"https://books.google.com/books/about/Becoming_Supernatural.html?id=NWL6DwAAQBAJ",type:"technique",finding:"El libro se apoya en el programa anterior con más meditaciones, entre ellas meditaciones caminando, y añade ideas sobre sintonizar con un “campo cuántico de infinitas posibilidades”, la coherencia del corazón para sanar, la glándula pineal como puerta a la experiencia mística y el equilibrio de los centros de energía del cuerpo.",limitation:"Solo las partes de ensayo mental y de atención de estas meditaciones coinciden con la investigación. Las afirmaciones sobre un campo cuántico, la curación, la glándula pineal y los centros de energía no tienen respaldo científico. Se leyó la descripción de la editorial en Google Books."},{id:"identity-dispenza-change",title:"Dr. Joe Dispenza · The Art of Change (blog, 2019)",url:"https://drjoedispenza.com/dr-joes-blog/the-art-of-change",type:"technique",finding:"Dispenza describe el cambio como un paso de pensar a hacer y a ser: darte cuenta de los hábitos automáticos de la mente y de la reacción, repasar mentalmente el viejo patrón para que se dispare menos, desaprender los estados emocionales que se han vuelto parte de la personalidad y acondicionar el cuerpo a una emoción nueva mediante la repetición.",limitation:"La publicación también afirma que el campo cuántico responde a quienes somos, algo que no tiene respaldo científico. Sus explicaciones sobre el cableado cerebral están simplificadas. Se leyó la publicación completa."},{id:"identity-dispenza-new-self",title:"Dr. Joe Dispenza · The Habit of Your New Self (blog, 2018)",url:"https://drjoedispenza.com/dr-joes-blog/the-habit-of-your-new-self",type:"technique",finding:"Dispenza sostiene que un cambio duradero implica dejar atrás pensamientos, conductas y emociones conocidos, y practicar el nuevo yo a lo largo del día, no solo en la meditación: caminar, sentarte y elegir como lo haría tu yo futuro, y enseñarle al cuerpo a sentir las emociones de ese yo futuro.",limitation:"Es una entrada de blog personal, no una investigación. La idea de la práctica repetida encaja con la investigación sobre hábitos; las explicaciones neuronales están simplificadas. Se leyó la publicación completa."},{id:"identity-clear-identity",title:"James Clear · Hábitos basados en la identidad (fragmento de Atomic Habits, 2018)",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear describe tres capas de cambio (resultados, procesos e identidad) y un enfoque en dos pasos: decidir qué tipo de persona quieres ser y luego demostrártelo con pequeños logros, por ejemplo empezar un hábito de movimiento con solo unas pocas decenas de pasos.",limitation:"Es una síntesis práctica de un escritor, no un programa probado. Se leyó la página del propio autor."},{id:"identity-clear-votes",title:"James Clear · Cómo cambiar tus creencias y cumplir tus metas (votos de identidad, Atomic Habits)",url:"https://jamesclear.com/identity-votes",type:"technique",finding:"Clear compara cada acción con un voto a favor del tipo de persona en la que quieres convertirte: ningún voto decide nada por sí solo, necesitas una mayoría, aunque no todos los votos sean a favor, y los hábitos pequeños van aportando pruebas de una nueva identidad con el tiempo.",limitation:"Es una metáfora útil que encaja con la investigación sobre autopercepción, pero no se ha probado como método. Se leyó la página del propio autor."},{id:"identity-clear-stacking",title:"James Clear · Encadenamiento de hábitos (Atomic Habits, 2018; a partir de BJ Fogg)",url:"https://jamesclear.com/habit-stacking",type:"technique",finding:"El encadenamiento de hábitos de Clear une un hábito nuevo con uno actual mediante la fórmula “Después de / Antes de [hábito actual], voy a [hábito nuevo]”. Atribuye el método a Tiny Habits de BJ Fogg (donde se llama anclaje) y aconseja elegir una señal concreta que ocurra con la misma frecuencia con la que debe ocurrir el hábito nuevo.",limitation:"El encadenamiento de hábitos como tal no se ha probado como método con nombre propio; se apoya en la investigación sobre señales del contexto y planes «si… entonces…». Se leyó la página del propio autor."},{id:"identity-clear-environment",title:"James Clear · Diseño del entorno (jamesclear.com)",url:"https://jamesclear.com/environment-design",type:"technique",finding:"Clear recomienda moldear tu entorno para que los buenos hábitos cuesten menos esfuerzo (deja preparado lo que necesitas, mantenlo a la vista) y los no deseados cuesten más (saca la señal de tu vista), y señala que las personas tienden a quedarse con las opciones por defecto.",limitation:"Son consejos prácticos basados en la ciencia del comportamiento; los consejos concretos no se han probado como conjunto. Se leyó la página del propio autor."},{id:"identity-clear-second-mistake",title:"James Clear · Evita el segundo error (jamesclear.com, 2014)",url:"https://jamesclear.com/second-mistake",type:"technique",finding:"Clear sostiene que un día perdido es un caso aislado, mientras que dos seguidos pueden empezar un patrón nuevo, y sugiere centrarte en volver al camino en lugar de compensar lo perdido, programar los hábitos y eliminar lo que causó el tropiezo.",limitation:"Es una regla práctica, no un método probado. Se leyó la página del propio autor."},{id:"identity-oyserman",title:"Daphna Oyserman · Motivación basada en la identidad (resumen de la investigación, USC)",url:"https://dornsife.usc.edu/daphna-oyserman/identity-and-self/",type:"research",finding:"La teoría de la motivación basada en la identidad sostiene que las identidades que nos vienen a la mente dependen del contexto, que las personas prefieren acciones que encajan con la identidad que tienen presente en ese momento, y que una misma dificultad puede leerse como señal de importancia (“esto me importa”), de imposibilidad (“esto no es para gente como yo”) o de mejora (los tiempos difíciles forjan el carácter).",limitation:"Es el resumen que hace la propia investigadora de su programa de investigación; los estudios que lo respaldan se centran sobre todo en estudiantes y resultados escolares. Se leyó la página del resumen."},{id:"identity-pathways",title:"Oyserman, O’Donnell, Sorensen y Wingert · 2021 · Intervención en el aula Pathways-to-Success",url:"https://files.eric.ed.gov/fulltext/ED618114.pdf",type:"research",finding:"En 1,142 estudiantes de octavo grado de 10 escuelas de Chicago en zonas de mucha pobreza, un programa de 12 sesiones dirigido por docentes y basado en la motivación basada en la identidad aumentó esa motivación y mejoró los resultados académicos cuando los docentes lo aplicaron con mayor fidelidad; pasar de un 60% a un 80% de fidelidad se asoció con una diferencia de 0.50 desviaciones estándar en el rendimiento académico.",limitation:"Es un programa escolar para adolescentes, analizado según la fidelidad de la aplicación; no demuestra que un ejercicio de autoayuda para adultos funcione igual. Se leyeron el resumen y la síntesis."},{id:"identity-bem",title:"Bem · 1972 · Teoría de la autopercepción",url:"https://www.sciencedirect.com/science/chapter/bookseries/pii/S0065260108600246",type:"research",finding:"Bem propuso que las personas llegamos a conocer nuestras propias actitudes y emociones en parte deduciéndolas de nuestra propia conducta y sus circunstancias, igual que lo haría un observador externo, sobre todo cuando las señales internas son débiles o poco claras.",limitation:"Es una teoría clásica con respaldo desigual que compite con otras explicaciones; no predice con qué rapidez se forma una identidad nueva. Se leyó el resumen del capítulo."},{id:"identity-hershfield",title:"Hershfield · 2011 · Continuidad con el yo futuro",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3764505/",type:"research",finding:"Esta revisión informa de que las personas que se sienten parecidas y conectadas con su yo futuro, que lo ven con claridad y que lo valoran de forma positiva tienden a tomar decisiones más favorables para el futuro; por ejemplo, ver imágenes de uno mismo envejecido aumentó el ahorro hipotético para la jubilación en comparación con las condiciones de control.",limitation:"La mayoría de los estudios tratan de dinero y de tareas breves de laboratorio, no de programas de cambio personal. Se leyeron la revisión y el resumen."},{id:"identity-cole",title:"Cole, Smith, Ragan, Suurmond y Armitage · 2021 · Metaanálisis sobre simulación mental y cambio de conducta",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8500882/",type:"research",finding:"94 estudios aleatorizados (123 efectos, 5,685 personas): simular mentalmente una conducta futura tuvo, en conjunto, un efecto moderado en la conducta posterior (g = 0.49). Ensayar hacerlo bien (g = 0.67) y el ensayo estándar del desempeño (g = 0.48) funcionaron mejor; imaginar un resultado deseado tuvo un efecto pequeño (g = 0.23); imaginar solo los pasos del proceso no fue fiable (g = 0.17, cinco efectos).",limitation:"La mayoría de los participantes eran estudiantes; algunos subtipos se apoyan en pocos estudios. Las conductas eran sobre todo de salud, deporte y habilidades, no la identidad en sí. Se leyeron el resumen y los resultados del artículo."},{id:"identity-toth",title:"Toth et al. · 2020 · ¿Sigue mejorando el rendimiento la práctica mental? Un seguimiento a 24 años",url:"https://www.sciencedirect.com/science/article/abs/pii/S1469029219301530",type:"research",finding:"37 estudios publicados entre 1995 y 2018 (115 efectos): la práctica mental tuvo un efecto positivo pequeño pero significativo en el rendimiento (r = 0.131), influido por el tiempo practicado, el tipo de tarea y el tipo de imágenes mentales. La práctica física fue más eficaz que la práctica mental por sí sola.",limitation:"Trata sobre todo de habilidades motoras y deportivas; no evalúa el cambio de personalidad, el estado de ánimo ni las enfermedades. Se leyó el resumen."},{id:"identity-gollwitzer",title:"Gollwitzer y Sheeran · 2006 · Metaanálisis sobre intenciones de implementación",url:"https://www.sciencedirect.com/science/chapter/bookseries/abs/pii/S0065260106380021",type:"research",finding:"En 94 pruebas independientes, formular planes «si… entonces…» (intenciones de implementación) tuvo un efecto positivo de moderado a grande en el logro de metas (d = 0.65). Los planes hacían que la situación elegida fuera más fácil de notar y la respuesta planeada más automática.",limitation:"Los estudios variaban mucho en metas y contextos, y los estudios publicados pueden exagerar los efectos. No demuestra que los planes funcionen igual para todos ni para un cambio de identidad a largo plazo. Se leyó el resumen."},{id:"identity-lally",title:"Lally, van Jaarsveld, Potts y Wardle · 2010 · Cómo se forman los hábitos",url:"https://www.researchgate.net/publication/32898894_How_are_habits_formed_Modeling_habit_formation_in_the_real_world",type:"research",finding:"96 voluntarios repitieron durante 12 semanas una conducta diaria de alimentación, bebida o actividad elegida por ellos, siempre en el mismo contexto. La acción se fue volviendo más automática, con avances cada vez menores; el tiempo para alcanzar el 95% de ese nivel osciló entre 18 y 254 días (mediana de unos 66 días entre las 39 personas cuyos datos se ajustaban al modelo). Perder una sola oportunidad no afectó de forma importante la formación del hábito.",limitation:"Es un estudio pequeño y autoinformado; el modelo se ajustó a menos de la mitad de las personas con datos suficientes, y los tiempos superiores a los 84 días observados son estimaciones. Se leyó el resumen; la mediana de 66 días proviene del artículo completo, según lo citó un artículo posterior del mismo equipo y resúmenes secundarios."},{id:"identity-gardner",title:"Gardner, Lally y Wardle · 2012 · Convertir las acciones saludables en hábitos",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3505409/",type:"research",finding:"Al resumir la investigación sobre hábitos para médicos, los autores señalan que la automaticidad se estabilizó tras una media de 66 días, con mucha variación, que las acciones simples se volvían automáticas más rápido que las exigentes, y que perder algún día ocasional no perjudicó seriamente la formación del hábito. Su consejo: elige una acción simple, hazla a una hora y en un lugar constantes, y repítela.",limitation:"Es una revisión narrativa y una guía práctica, no un ensayo nuevo. Se leyó el artículo completo."},{id:"identity-wood-everyday",title:"Wood, Quinn y Kashy · 2002 · Los hábitos en la vida cotidiana",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/Wood.Quinn_.Kashy_.2002_Habits_in_everyday_life.pdf",type:"research",finding:"En dos estudios con diarios por hora, el 35% (Estudio 1) y el 43% (Estudio 2) de las conductas eran hábitos, realizados casi a diario y por lo general en el mismo lugar. Durante los hábitos, los pensamientos de las personas coincidían con lo que hacían solo el 40% y el 44% del tiempo, frente al 70% y el 60% durante la conducta no habitual.",limitation:"Solo estudiantes universitarios de EE. UU.; el hábito se definió por su frecuencia y su lugar estable. Se leyeron el resumen y la síntesis del artículo."},{id:"identity-wood-runger",title:"Wood y Rünger · 2016 · Psicología del hábito",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-122414-033417",type:"research",finding:"Esta revisión describe los hábitos como respuestas que se forman cuando las personas repiten la misma acción en el mismo contexto mientras persiguen metas, y que luego son activadas por el contexto. Los hábitos actúan como una opción por defecto eficiente y pueden persistir incluso cuando cambian las intenciones.",limitation:"Es una revisión narrativa; explica mecanismos en lugar de probar un método concreto. Se leyó el resumen."},{id:"identity-killingsworth",title:"Killingsworth y Gilbert · 2010 · Una mente que divaga es una mente infeliz (nota de Harvard Gazette)",url:"https://news.harvard.edu/gazette/story/2010/11/wandering-mind-not-a-happy-mind/",type:"research",finding:"Un estudio con móviles en unos 2,250 adultos, con cerca de 250,000 datos, encontró que la mente de las personas divagaba el 46.9% del tiempo, y al menos el 30% del tiempo en casi todas las actividades. Las personas eran menos felices cuando su mente divagaba.",limitation:"Voluntarios que usaban una aplicación, en su mayoría de EE. UU. Los datos son observacionales; el análisis con desfase temporal sugirió que la divagación tendía a preceder a la infelicidad, pero no es un experimento controlado. Se leyó una nota de prensa universitaria sobre el artículo de Science."},{id:"identity-lieberman",title:"Lieberman et al. · 2007 · Poner los sentimientos en palabras (etiquetado emocional)",url:"https://sanlab.psych.ucla.edu/wp-content/uploads/sites/31/2015/05/Lieberman_AL-2007.pdf",type:"research",finding:"En 30 adultos dentro de un escáner cerebral, elegir una palabra para la emoción de un rostro (como “enojado” o “asustado”) se asoció con una menor respuesta de la amígdala que elegir un nombre que coincidiera con el género del rostro, y con más actividad en la corteza prefrontal ventrolateral derecha.",limitation:"Es un único estudio pequeño de laboratorio sobre reacciones breves a imágenes; no demuestra que nombrar los sentimientos mejore el ánimo a lo largo de semanas. Se leyó el artículo."},{id:"identity-breines",title:"Breines y Chen · 2012 · La autocompasión aumenta la motivación para mejorar",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167212445599",type:"research",finding:"En cuatro experimentos, las personas a quienes se animó a adoptar una mirada autocompasiva ante una debilidad, un fracaso o un error moral se sintieron más motivadas a mejorar que quienes estaban en condiciones de autoestima o de control neutro; por ejemplo, dedicaron más tiempo a estudiar para un examen difícil después de haber fracasado en uno inicial.",limitation:"Son experimentos breves de laboratorio, sobre todo con estudiantes; no se midió la conducta a largo plazo. Se leyó el resumen."},{id:"identity-harkin",title:"Harkin et al. · 2016 · ¿Seguir el progreso hacia una meta favorece alcanzarla?",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/",type:"research",finding:"Un metaanálisis de 138 estudios con 19,951 personas encontró que las intervenciones que aumentaban el seguimiento del progreso mejoraban el logro de metas (d = 0.40). Los efectos fueron mayores cuando el progreso se registraba físicamente o se comunicaba a otras personas.",limitation:"Las metas y las formas de seguir el progreso variaban mucho; la revisión no evalúa un formato concreto de revisión semanal como el de esta lección. Se leyó el resumen."}],q={id:"identity",title:"¿Siempre caes en lo mismo? Cómo convertirte en quien quieres ser",subtitle:"7 lecciones de 8 a 12 minutos. Elige tus valores y ensaya pequeños gestos que los reflejen.",description:"¿Y si el cambio duradero empieza por quién crees que eres, y no solo por lo que te obligas a hacer? Aprende a reconocer a tu yo anterior en piloto automático y a practicar cómo actuar desde uno nuevo, con un breve ensayo matutino y con pequeñas pruebas cada día.",scope:"Para adultos que quieren una forma cotidiana de cambiar un patrón conocido de pensar, sentir o reaccionar. Se apoya en el Dr. Joe Dispenza y en James Clear, y dice con claridad cuáles de sus ideas respalda la investigación y cuáles no. No es terapia ni un tratamiento para la depresión, la ansiedad, el trauma ni ninguna enfermedad; si estás pasando por un momento difícil, habla con un profesional de la salud, y en una crisis llama al número de emergencias de tu país.",outcome:"Un retrato escrito de tu yo anterior y del nuevo yo que eliges, un ensayo matutino de 10 minutos, tres planes «si… entonces…» para tus momentos más difíciles y una revisión semanal que te acompañe durante los primeros meses.",photo:{id:"1611569518992-0927098278b7",alt:"Una mujer caminando sola por un camino de tierra entre árboles verdes"},lessons:[{id:"identity-1",title:"Conoce a tu yo anterior",minutes:8,goal:"Escribir un retrato honesto y amable de los pensamientos, emociones y reacciones que repites casi todos los días.",reading:["En gran parte del día repites lo que ya conoces. Te despiertas, retomas los mismos pensamientos sobre los mismos problemas, caes en los mismos estados de ánimo de siempre y reaccionas a las mismas personas de la misma manera. El Dr. Joe Dispenza, en Breaking the Habit of Being Yourself, llama a este conjunto el “yo anterior”: no una mala persona, solo un conjunto de patrones muy repetidos. La investigación coincide en que buena parte de la vida diaria es habitual. En dos estudios con diarios, entre una tercera parte y casi la mitad de lo que hacían las personas se repetía casi a diario en el mismo lugar, y a menudo con la mente en otra parte.","El cambio empieza por ver el programa con claridad. Ese es el objetivo de esta lección: un inventario, no un veredicto. Vas a notar qué pensamientos vuelven con más frecuencia, qué emociones los siguen y qué sueles hacer después. Intenta describirte como lo haría un investigador amable con alguien a quien observa: con precisión, con curiosidad y sin insultos. “Soy una persona floja” no te ayuda a saber qué cambiar. “Después de comer, en mi escritorio, pienso ‘esto es demasiado’ y paso veinte minutos mirando el móvil” te muestra exactamente dónde intervenir."],deeper:[{heading:"Por qué el primer paso es darte cuenta",paragraphs:["Los hábitos los activa el contexto, no tus últimas intenciones. En su revisión de la investigación sobre hábitos, Wendy Wood y Dennis Rünger describen los hábitos como una respuesta que el cerebro activa para ahorrar esfuerzo: una vez que una respuesta se ha repetido mucho en un lugar, ese lugar puede activarla aunque tus metas hayan cambiado. Por eso un propósito de Año Nuevo pierde tan a menudo contra una tarde cualquiera de martes.","El primer paso de Dispenza apunta en la misma dirección. Antes de intentar convertirte en alguien nuevo, conoces en detalle al yo automático: los pensamientos, emociones y conductas que quieres dejar atrás. No puedes interrumpir un bucle que nunca has notado."],visual:{kind:"cycle",title:"Cómo se mantiene en marcha el yo anterior",center:"Yo anterior",nodes:[{label:"Entorno conocido",text:"El mismo lugar, hora, persona o estado de ánimo."},{label:"Pensamiento conocido",text:"La historia de siempre: “otra vez lo mismo”."},{label:"Emoción conocida",text:"El estado de ánimo de siempre, agradable o no."},{label:"Reacción conocida",text:"Lo que haces después sin haberlo decidido."},{label:"Resultado conocido",text:"Parece demostrar que “así soy yo”."}],note:"Un esquema simplificado basado en la investigación sobre hábitos y en la descripción de Dispenza. La vida real es más desordenada, y cualquier punto del bucle es un lugar donde puedes intervenir."}},{heading:"Errores comunes",paragraphs:["Convertir el inventario en un juicio. Estás reuniendo información, no pruebas en tu contra. Las etiquetas duras pueden convertir la curiosidad en actitud defensiva, y una mente a la defensiva nota menos.","Anotar solo conductas. El yo anterior también está hecho de pensamientos y estados de ánimo. “Me salto el gimnasio” sirve; “Me salto el gimnasio cuando pienso ‘no tengo energía’ y me siento sin ánimo” sirve más, porque muestra el pensamiento y la emoción que puedes detectar antes."]},{heading:"Lo que esto no es",paragraphs:["Si el yo anterior que estás describiendo incluye un ánimo bajo que dura mucho tiempo, ataques de pánico, recuerdos intrusivos o pensamientos de hacerte daño, esto no es algo para manejar solo con una hoja de trabajo. Por favor, habla con un médico o un profesional de salud mental, y en una crisis llama al número de emergencias de tu país. Este curso es para patrones cotidianos; no sustituye un tratamiento."]}],example:{title:"Leyla, 34 años, coordinadora de proyectos",text:"Leyla puso tres recordatorios en el móvil para un miércoles normal. A las 10:40 escribió: leyendo un correo corto de mi jefa, pensando “cree que soy descuidada”, opresión en el pecho, reescribí la respuesta cuatro veces. A las 2:15: me salté el almuerzo, pensando “no tengo tiempo”, agitada y tensa. A las 6:30: me quedé hasta tarde revisando un informe que nadie había pedido revisar. Esa noche leyó sus notas y vio el mismo hilo en las tres: un detonante pequeño, el pensamiento de que estaba a punto de quedar en evidencia y la prisa por prepararse de más. Todavía no intentó arreglar nada. Escribió dos frases neutrales sobre “la Leyla de antes” y se sorprendió al sentir alivio. Ahora podía distinguir el patrón, dónde empezaba y dónde terminaba."},practice:["Pon tres recordatorios para hoy y, cada vez que suene uno, escribe una línea: qué estaba pensando, qué estaba sintiendo, qué estaba haciendo.","Esta noche, lee tus notas y rodea con un círculo el pensamiento, la emoción o la reacción que apareció más de una vez.","Escribe un retrato de dos frases de tu yo anterior con palabras neutrales, como si describieras a un amigo al que estás conociendo."],reflection:"¿Cuál de tus pensamientos o emociones te resulta tan familiar que casi nunca lo notas?",question:"¿Cuál es la nota más útil para conocer a tu yo anterior?",options:["Simplemente soy una persona floja.","Después de comer, en mi escritorio, pienso “esto es demasiado”, me siento con pesadez y paso el rato en el móvil.","A partir de mañana voy a ser una persona completamente distinta."],correct:1,feedback:"Una nota concreta muestra el entorno, el pensamiento, la emoción y la acción, así que puedes ver dónde intervenir. Las etiquetas y las grandes promesas no te dejan nada con qué trabajar.",takeaway:"No puedes cambiar un patrón que nunca has conocido, así que conócelo con curiosidad.",sources:["identity-dispenza-habit","identity-wood-everyday","identity-wood-runger"],visual:{kind:"table",title:"Tu inventario del yo anterior",columns:["Capa","Pregúntate","Ejemplo"],rows:[["Pensamientos","¿Qué me digo a mí mismo casi todos los días?","“Nunca me alcanza el tiempo.”"],["Emociones","¿Qué estado de ánimo me resulta más familiar?","Una preocupación leve a media mañana"],["Reacciones","¿Qué hago cuando aparece ese estado de ánimo?","Reviso el correo otra vez, me salto el almuerzo"],["Entorno","¿Dónde y cuándo suele empezar?","En mi escritorio, entre las 10 y las 11"]],note:"Completa tu propia versión. Busca que sea concreta y amable, no completa."},technique:{name:"El inventario del yo anterior",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Elige un área en la que quieras cambiar, como el estrés en el trabajo o la forma de reaccionar en casa.","Escribe los pensamientos que tienes con más frecuencia en esa área, tal como suenan en tu cabeza.","Nombra las emociones que acompañan a esos pensamientos y dónde las notas en el cuerpo.","Describe lo que sueles hacer o decir después: tus reacciones automáticas.","Anota los lugares, momentos y personas que tienden a disparar todo el patrón.","Relee la lista y admite ante ti, sin culpa, que así has estado funcionando. Esa mirada honesta es el punto de partida."],evidence:"Notar y escribir tus propios patrones encaja bien con la investigación sobre hábitos, que muestra que gran parte de la conducta cotidiana es activada por entornos conocidos. El inventario no se ha probado por sí solo; tómalo como un mapa inicial, no como una cura.",sourceId:"identity-dispenza-habit"},photo:{id:"1519087630026-63fb0dab69bb",alt:"Una mujer mirando su reflejo en un espejo de pared"}},{id:"identity-2",title:"Emociones memorizadas",minutes:9,goal:"Detectar una emoción que has practicado tantas veces que ya te parece parte de tu personalidad.",reading:["Dispenza describe un tipo particular de hábito: una emoción que has sentido tantas veces que tu cuerpo parece buscarla por sí solo. La preocupación antes de cada reunión. La irritación en cuanto entras a la cocina. La culpa cada vez que descansas. Él las llama emociones memorizadas. Quizá empezaron como reacciones a hechos reales, pero a fuerza de repetirse ahora llegan antes de que haya pasado nada, y empiezan a sentirse como si fueran quien eres: “Es que soy una persona ansiosa”.","No necesitas aceptar toda su teoría para que esta idea te sea útil. La investigación sobre hábitos muestra que las respuestas repetidas terminan activadas por el contexto, y parece plausible que algunas reacciones emocionales funcionen de forma parecida, aunque esto se ha estudiado menos directamente. Algunos estudios también sugieren que poner un sentimiento en palabras puede reducir su intensidad. En un estudio de neuroimagen, nombrar la emoción de un rostro se asoció con menos actividad en la amígdala, una zona del cerebro que interviene en las respuestas de amenaza. Hoy vas a practicar cómo detectar y nombrar tu emoción más familiar."],deeper:[{heading:"Qué dice la investigación",paragraphs:["En el estudio de Matthew Lieberman, 30 adultos miraron rostros emocionales dentro de un escáner cerebral. Cuando elegían una palabra para la emoción, como enojado o asustado, su amígdala respondía menos que cuando elegían un nombre que coincidiera con el género del rostro. La única zona más activa durante el etiquetado emocional fue una región en la parte frontal del cerebro vinculada con el autocontrol.","Es un solo estudio pequeño de laboratorio, y una respuesta menor de la amígdala durante unos segundos no equivale a sentirse mejor durante semanas. Aun así, coincide con la experiencia cotidiana: “Noto temor en el estómago” te da un poco de distancia que “todo está saliendo mal” no te da."],visual:{kind:"compare",title:"Identificarte con una emoción o ponerle nombre",left:{label:"Identificarte con ella",items:["No sirvo para nada.","Todo está saliendo mal.","Así soy yo."]},right:{label:"Nombrándola",items:["Noto temor en el estómago.","Ahí está mi preocupación habitual de los lunes.","Esta sensación es conocida, y pasa."]},note:"Nombrar una emoción no significa discutir con ella ni intentar apartarla."}},{heading:"Cómo lo plantea Dispenza y qué dejar fuera",paragraphs:["En sus libros y en su blog, Dispenza va mucho más lejos. Vincula los estados emocionales con reprogramar tus genes y tu biología, con la curación y con un “campo cuántico” que supuestamente responde a quien eres y reorganiza los hechos a tu alrededor. Estas afirmaciones no cuentan con respaldo de la investigación científica. Nunca retrases ni cambies un tratamiento médico por ellas.","Lo que sí puedes conservar es el núcleo práctico: notar temprano la emoción conocida, nombrarla y decidir no alimentarla con los mismos pensamientos y reacciones de siempre. Con el tiempo, le das a otra emoción la oportunidad de volverse la familiar."]},{heading:"Cuando una emoción es más que un hábito",paragraphs:["Algunas emociones son señales que vale la pena escuchar: la rabia ante una injusticia real, el duelo tras una pérdida, el miedo en una situación que de verdad es peligrosa. Y la ansiedad persistente o el ánimo bajo pueden necesitar ayuda profesional. Esta lección trata de emociones habituales de la vida ordinaria; no sustituye un tratamiento."]}],example:{title:"Daniel, 41 años, maestro",text:"Cada domingo, hacia las seis de la tarde, Daniel sentía un temor intenso. Durante años lo tomó como señal de que la semana siguiente sería mala, así que pasaba la tarde revisando el correo de la escuela y contestándole mal a su familia. Este domingo, cuando llegó el peso conocido, se dijo: ahí está, el viejo temor del domingo. Notó que tenía los hombros casi pegados a las orejas y soltó el aire despacio. Luego anotó la única tarea que de verdad necesitaba preparar, la hizo en quince minutos y cerró el ordenador. La sensación no desapareció, pero era más pequeña y ya no decidía su tarde. Vio una película con su hija, y el lunes la semana resultó normal."},practice:["Elige una emoción que aparezca casi todos los días y anota cuándo suele llegar y en qué parte del cuerpo la sientes.","La próxima vez que aparezca, nómbrala en silencio con una etiqueta corta, como “preocupación habitual” o “irritación del lunes”.","Después de nombrarla, respira lento tres veces y pregúntate: ¿qué haría ahora mismo si esta emoción no estuviera al mando?"],reflection:"¿A qué emoción recurres tan a menudo que quizá la hayas confundido con tu personalidad?",question:"¿Qué respuesta encaja mejor con el núcleo práctico de esta lección?",options:["Aceptar que la emoción es simplemente quien eres.","Intentar cambiar tus genes sintiéndote feliz durante el tiempo suficiente.","Notar temprano la emoción conocida, nombrarla y elegir tu siguiente acción."],correct:2,feedback:"Notar y nombrar una emoción conocida crea un pequeño espacio para elegir qué haces después. Las afirmaciones sobre cambiar los genes o sanar mediante la emoción no tienen respaldo en la investigación.",takeaway:"Una emoción que has repetido muchas veces no define quién eres.",sources:["identity-dispenza-change","identity-dispenza-habit","identity-dispenza-supernatural","identity-lieberman","identity-wood-runger"],visual:{kind:"cycle",title:"Cómo una emoción se vuelve estado de ánimo, y un estado de ánimo, un yo",center:"Emoción memorizada",nodes:[{label:"Detonante",text:"Un mensaje, una habitación, un recuerdo, una hora del día."},{label:"Emoción",text:"Preocupación, irritación o culpa, sentida en el cuerpo."},{label:"Pensamiento",text:"La mente busca razones que justifiquen la emoción."},{label:"Reacción",text:"Evitar, contestar mal, prepararse de más, retraerse."},{label:"Repetición",text:"La próxima vez la emoción llega antes y se queda más tiempo."}],note:"La idea de Dispenza dibujada como un bucle. El patrón general encaja con la investigación sobre hábitos; sus explicaciones biológicas más detalladas van más allá de lo que se ha probado."},technique:{name:"Desaprender una emoción",origin:"Dr. Joe Dispenza · The Art of Change (2019)",steps:["Elige una emoción en la que quieras dejar de vivir, como la preocupación, el resentimiento o la culpa.","Recuerda una ocasión reciente en que se apoderó de ti y repítela despacio en tu mente: los pensamientos, las sensaciones y lo que hiciste.","Mientras repasas lo ocurrido, decide que esa es la reacción que ya no vas a practicar.","Pregúntate cómo te gustaría sentirte en esa misma situación y déjate percibir ahora un poco de esa sensación.","Repite esta breve revisión a menudo, para que la nueva respuesta empiece a sentirse tan familiar como la vieja."],evidence:"Revisar un patrón y ensayar una respuesta distinta coincide con el ensayo mental y el etiquetado emocional, que tienen un respaldo modesto en la investigación. Las explicaciones de Dispenza sobre un campo cuántico, los genes y la curación no tienen respaldo científico.",sourceId:"identity-dispenza-change"},photo:{id:"1762126242240-cafa01fb1351",alt:"Una persona en un sillón mirando por una ventana con lluvia"}},{id:"identity-3",title:"Detecta el piloto automático",minutes:8,goal:"Interrumpir a tu yo anterior al menos una vez en medio de un día cualquiera.",reading:["Un momento de calma por la mañana es la parte fácil. La verdadera prueba llega a las tres de la tarde, cuando aparece el detonante conocido y el yo anterior toma el control antes de que lo notes. El programa de Dispenza incluye este paso durante el día: una vez que has estudiado a tu yo anterior, prestas atención a cuándo aparece y, en cuanto lo detectas, te recuerdas la decisión que tomaste y te reorientas. Darte cuenta en ese momento te permite decidir, en lugar de seguir con el ciclo automático.","Esto importa porque gran parte del día transcurre en piloto automático. En dos estudios con diarios de Wendy Wood y sus colegas, el 35 y el 43 por ciento de las conductas de los estudiantes eran hábitos realizados casi a diario en el mismo lugar, y durante esos hábitos las personas a menudo pensaban en otra cosa. Un estudio aparte con móviles, en unos 2,250 adultos, encontró que su mente divagaba en casi la mitad de los momentos registrados. No vas a detectar todos los ciclos; nadie lo logra. El cambio empieza cuando detectas algunos."],deeper:[{heading:"Adónde va tu atención durante los hábitos",paragraphs:["En esos mismos estudios con diarios, los pensamientos de las personas coincidían con lo que hacían mucho menos durante los hábitos que durante las acciones no habituales. Los hábitos dejan a la mente libre para divagar. Eso es cómodo cuando te atas los zapatos, y menos cuando el hábito es contestarle mal a alguien a quien quieres.","El estudio con móviles de Matthew Killingsworth y Daniel Gilbert también encontró que las personas eran menos felices cuando su mente divagaba. Ese hallazgo es observacional, así que no prueba que divagar cause infelicidad, pero puede animarte a volver al presente con más frecuencia."],visual:{kind:"bars",title:"¿Pensaban las personas en lo que estaban haciendo?",bars:[{label:"Estudio 1 · durante hábitos",value:40,display:"40%"},{label:"Estudio 1 · otras acciones",value:70,display:"70%"},{label:"Estudio 2 · durante hábitos",value:44,display:"44%"},{label:"Estudio 2 · otras acciones",value:60,display:"60%"}],note:"Proporción de entradas del diario en las que los pensamientos coincidían con la acción del momento, según Wood, Quinn y Kashy (2002). Los participantes eran estudiantes universitarios de EE. UU.",sourceId:"identity-wood-everyday"}},{heading:"Cómo detectarlo",paragraphs:["Detectar al yo anterior es una habilidad, y las habilidades mejoran con la práctica. Empieza con un solo patrón y busca su señal más temprana. Suele ser una sensación en el cuerpo o un pequeño movimiento, como estirar la mano hacia el móvil, antes de que llegue el pensamiento completo."],visual:{kind:"steps",title:"Detecta, nombra, haz una pausa y cambia de rumbo",steps:[{label:"Detecta",text:"Nota la primera señal: una sensación, un pensamiento conocido, el impulso de tomar el móvil."},{label:"Nombra",text:"Di en silencio tu palabra clave: “ahí está”."},{label:"Pausa",text:"Una exhalación lenta. Siente tus pies en el suelo."},{label:"Cambia de rumbo",text:"Pregúntate qué haría después tu nuevo yo, y haz la versión más pequeña de eso."}],note:"Adaptado de la práctica diurna de Dispenza. La pausa importa más que el orden exacto."}},{heading:"Errores comunes",paragraphs:["Regañarte por detectarlo tarde. Aunque te des cuenta después de haber repetido todo el ciclo, ya lo has reconocido; mañana quizá lo detectes un minuto antes.","Confiar solo en la memoria. Vincula tu práctica a recordatorios que de verdad vas a ver: una palabra en la pantalla de bloqueo del móvil, una nota adhesiva en el ordenador, una liga para el pelo en la muñeca. La lección 6 profundiza en las señales."]}],example:{title:"Sofía, 27 años, enfermera",text:"El yo anterior de Sofía aparecía en el camino a casa. Después de cada turno repasaba cada error, real o imaginado, y cruzaba la puerta de su casa tensa y de mal humor. Eligió una señal: el momento de girar la llave en el auto. El lunes se olvidó por completo. El martes lo detectó en un semáforo, a mitad de camino, y dijo en silencio: modo repaso. Exhaló, puso un pódcast que le gustaba y nombró una cosa que había hecho bien ese día. El miércoles lo detectó al girar la llave. No funcionó todas las tardes, pero tres tardes de esa semana llegó a casa notablemente más tranquila, y su pareja también lo notó."},practice:["Elige un momento del yo anterior para vigilar hoy, como el impulso de revisar el móvil o el primer destello de irritación.","Elige una palabra clave para decir en silencio cuando lo detectes, como “ahí está” o “cambio”.","Cada vez que lo detectes, exhala lento una vez, haz una cosa pequeña que haría tu nuevo yo y anota una raya."],reflection:"¿Cuál es la señal más temprana, en tu cuerpo o en tus pensamientos, de que tu yo anterior está a punto de tomar el control?",question:"Detectas tu reacción habitual cuando ya ha empezado. ¿Cuál es la respuesta más útil?",options:["Nombrarla, hacer una pausa de una respiración y elegir un paso pequeño.","Decidir que el día está arruinado y volver a intentarlo la semana que viene.","Criticarte con dureza para acordarte la próxima vez."],correct:0,feedback:"Detectar el ciclo en cualquier punto es un avance. Un nombre, una pausa y un paso pequeño te permiten elegir, en lugar de repetir el hábito; la autocrítica dura suele hacer que tengas menos ganas de mirar de cerca la próxima vez.",takeaway:"Cada vez que detectas el piloto automático, conviertes un hábito otra vez en una elección.",sources:["identity-dispenza-habit","identity-wood-everyday","identity-killingsworth"],visual:{kind:"bars",title:"¿Cuánto de la conducta cotidiana es hábito?",bars:[{label:"Estudio con diarios 1",value:35,display:"35%"},{label:"Estudio con diarios 2",value:43,display:"43%"}],note:"Proporción de conductas informadas que eran hábitos, es decir, realizadas casi a diario y por lo general en el mismo lugar, según Wood, Quinn y Kashy (2002). Los participantes eran estudiantes universitarios de EE. UU., así que la proporción puede ser distinta en tu caso.",sourceId:"identity-wood-everyday"},technique:{name:"Detectar y cambiar de rumbo durante el día",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Por la mañana, recuerda qué pensamiento habitual, emoción o reacción vas a soltar hoy.","Durante el día, vigila los momentos en que suele aparecer: las personas, lugares y horas de tu inventario.","Cuando lo notes, interrumpe el bucle a propósito; una palabra clave corta que digas en silencio puede ayudar.","Recuérdate a la persona que decidiste ser esta mañana.","Elige una respuesta acorde con esa persona, aunque sea muy pequeña.","Por la noche, mira atrás un momento: ¿cuándo lo detectaste y cuándo se te pasó?"],evidence:"Notar las señales y decidir de antemano cómo responder encaja con la investigación sobre hábitos y planes «si… entonces…». Esta rutina diurna concreta no se ha probado en estudios controlados.",sourceId:"identity-dispenza-habit"},photo:{id:"1626257690705-8d62125575b0",alt:"Un hombre con chaqueta oscura caminando por un paso peatonal de la ciudad a plena luz del día"}},{id:"identity-4",title:"Cada acción es un voto",minutes:9,goal:"Elegir la identidad que quieres hacer crecer y emitir hoy tu primer pequeño voto a su favor.",reading:["James Clear, en Atomic Habits, describe tres capas de cambio. La capa exterior son los resultados, como bajar de peso o terminar un libro. La capa intermedia es el proceso: tus rutinas y sistemas. La capa más profunda es la identidad, es decir, lo que crees sobre ti. La mayoría empezamos por fuera. Clear sugiere empezar por dentro: decide quién quieres ser y luego demuéstratelo con pequeños logros. Compara cada acción con un voto a favor de un cierto tipo de persona. Ningún voto gana la elección por sí solo, pero a medida que se acumulan, también se acumulan las pruebas de un nuevo yo.","La idea tiene raíces más antiguas en la psicología. La teoría de la autopercepción de Daryl Bem, de 1972, propone que en parte averiguamos cómo somos observando lo que hacemos, igual que lo haría un observador externo, sobre todo cuando nuestros sentimientos internos no están claros. La investigación de Daphna Oyserman sobre la motivación basada en la identidad añade que las personas prefieren las acciones que encajan con cómo se ven en ese momento; cuando algo parece “no ser para gente como yo”, se esfuerzan menos. Así que la meta no es un día heroico. Es una acción pequeña que encaje con el nuevo yo."],deeper:[{heading:"Por qué ayudan las pequeñas pruebas",paragraphs:["La investigación de Oyserman también examina cómo interpretan las personas la dificultad. Si una tarea te resulta difícil y concluyes que entonces no es para alguien como tú, tiendes a rendirte. Si concluyes que es difícil porque te importa, tiendes a seguir. Un programa de aula basado en estas ideas, Pathways-to-Success, se asoció con mejores calificaciones en estudiantes de octavo grado de escuelas de Chicago en zonas de mucha pobreza, sobre todo cuando los docentes lo aplicaron tal como fue diseñado.","Un programa escolar está muy lejos de tu caminata matutina, y no demuestra que esta lección vaya a funcionar contigo. Pero puedes aplicar el principio: interpreta la dificultad como señal de importancia, no como un veredicto sobre quién eres."],visual:{kind:"table",title:"Tres formas de interpretar la dificultad",columns:["Cuando te resulta difícil, piensas…","Lo que suele venir después"],rows:[["Esto no debe de ser para alguien como yo.","Te esfuerzas menos y vuelves al patrón anterior."],["Esto es difícil porque me importa.","Sigues adelante o pruebas un paso más pequeño."],["Los tiempos difíciles están moldeando en quién me estoy convirtiendo.","Los tropiezos pasan a ser parte de la historia, no su final."]],note:"Adaptado de la investigación de Daphna Oyserman sobre motivación basada en la identidad: la dificultad como imposibilidad, como importancia y como mejora."}},{heading:"Errores comunes",paragraphs:["Elegir una etiqueta en lugar de un rumbo. “Soy una persona disciplinada” puede sonar falso y ponerte a la defensiva. “Me estoy convirtiendo en alguien que cumple las pequeñas promesas que se hace a sí mismo” deja espacio para crecer.","Elegir votos demasiado grandes. El propio ejemplo de Clear de alguien que empieza a hacer ejercicio comienza con solo unas pocas decenas de pasos al día. Y no cuentes solo los días perfectos: en una elección necesitas la mayoría, no todos los votos."]}],example:{title:"Amir, 38 años, gerente de ventas",text:"Amir quería dejar de ser el papá que llegaba a casa y gritaba por los zapatos en el pasillo. Escribió: me estoy convirtiendo en un padre tranquilo. Su primer voto fue diminuto. Al estacionarse frente a la casa, se quedaba en el auto sesenta segundos, exhalaba despacio tres veces y se imaginaba saludando a sus hijos antes que nada. Llevó un conteo en el móvil. Para el viernes tenía cinco marcas. El jueves todavía habló con brusquedad por las tareas escolares, pero diez minutos después volvió y se disculpó, y también contó eso como un voto. No fue una transformación. Fue la primera semana en mucho tiempo en la que tuvo pruebas de que podía ser el padre que quería ser."},practice:["Termina esta frase por escrito: “Me estoy convirtiendo en alguien que…”, y que hable de quién eres, no de un resultado.","Elige un voto tan pequeño que podrías hacerlo en tu peor día, y hazlo dentro de la próxima hora.","Empieza un conteo sencillo en papel o en el móvil y suma una marca cada vez que emitas un voto."],reflection:"¿Qué pequeña acción de hoy serviría como prueba de que te estás convirtiendo en la persona que describiste?",question:"En los hábitos basados en la identidad, ¿qué es lo que más importa en las primeras semanas?",options:["Conseguir resultados impresionantes lo más rápido posible.","Emitir votos pequeños y repetidos que te demuestren la nueva identidad.","Esperar a sentirte una persona nueva antes de actuar."],correct:1,feedback:"Las acciones pequeñas y repetidas aportan pruebas de la nueva identidad. Los resultados llegan después; esperar a sentirte distinto primero suele significar esperar mucho tiempo.",takeaway:"No necesitas un historial perfecto, solo una mayoría creciente de votos.",sources:["identity-clear-identity","identity-clear-votes","identity-bem","identity-oyserman","identity-pathways"],visual:{kind:"compare",title:"Metas de resultados y hábitos basados en la identidad",left:{label:"Empezar por el resultado",items:["Quiero correr un medio maratón.","La motivación depende de un progreso visible.","Una semana perdida parece un fracaso."]},right:{label:"Empezar por la identidad",items:["Me estoy convirtiendo en alguien que se mueve todos los días.","Cada caminata corta cuenta como prueba.","Un día perdido es un voto, no la elección."]},note:"Basado en la descripción que hace James Clear de los hábitos basados en la identidad. Las metas de resultado siguen ayudando; la identidad les da un sentido personal."},technique:{name:"Hábitos basados en la identidad: decide y luego demuéstralo",origin:"James Clear · Atomic Habits (2018)",steps:["Mira un resultado que quieras y pregúntate qué tipo de persona lo lograría con naturalidad.","Escribe esa identidad en una frase corta: “Me estoy convirtiendo en alguien que…”.","Elige la acción más pequeña que esa persona haría hoy.","Hazla, aunque te parezca demasiado pequeña para importar.","Regístrala como un voto a favor de tu nueva identidad.","Haz crecer la acción poco a poco cuando te resulte fácil."],evidence:"El modelo de Clear es una síntesis práctica, no un programa probado. Encaja con la teoría de la autopercepción y con la investigación sobre motivación basada en la identidad, que sugieren que las acciones moldean cómo nos vemos y que las acciones que encajan con una identidad parecen merecer más la pena.",sourceId:"identity-clear-identity"},photo:{id:"1787154604447-4a62ed6654e3",alt:"Una mujer con hiyab oscuro y ropa deportiva trotando por una calle de la ciudad"}},{id:"identity-5",title:"Ensaya el nuevo yo",minutes:12,goal:"Practicar un ensayo matutino de 10 minutos de la persona en la que te estás convirtiendo y vincularlo con una acción real.",reading:["El centro del método de Dispenza es una meditación matutina en la que ensayas tu nuevo yo. Después de relajar el cuerpo y soltar el viejo patrón, imaginas con detalle cómo piensa, habla y actúa tu nuevo yo en situaciones reales de tu día, e intentas sentir ya las emociones que sentiría esa persona: calma, confianza, calidez. Sugiere hacerlo antes de que la rutina del día se apodere de ti, para empezar la jornada como el nuevo yo en lugar del anterior.","El ensayo mental tiene respaldo real en la investigación, con límites. Un metaanálisis de 2021 con 94 estudios aleatorizados encontró que simular mentalmente una conducta tuvo, en conjunto, un efecto moderado en la conducta posterior. Imaginarte haciendo bien la acción funcionó mejor; imaginar solo un resultado feliz funcionó mucho menos. La investigación deportiva encuentra que la práctica mental mejora un poco las habilidades, pero menos que la práctica real. Así que ensaya el proceso, no solo el premio, y después haz una acción real ese mismo día. Las afirmaciones de Dispenza de que la meditación remodela los genes, cura enfermedades o cambia la realidad mediante un campo cuántico no tienen respaldo científico."],deeper:[{heading:"El ensayo matutino de 10 minutos",paragraphs:["Puedes hacerlo sentado en el borde de la cama o en una silla, antes de mirar el móvil. Usa un temporizador para no tener que vigilar el reloj. Los minutos de abajo son una guía; una versión más corta en un día apurado también cuenta.","Si ensayar te trae una angustia fuerte o viejos recuerdos dolorosos, abre los ojos, siente tus pies en el suelo y detente. Esta no es la herramienta adecuada para trabajar un trauma; para eso puede ayudarte un profesional capacitado."],visual:{kind:"steps",title:"Diez minutos, cinco partes",steps:[{label:"Relajarte · 2 min",text:"Cierra los ojos, respira despacio y lleva tu atención de los pensamientos al cuerpo."},{label:"Soltar · 2 min",text:"Nombra el yo anterior que dejas atrás hoy y suéltalo."},{label:"Ensayar · 4 min",text:"Imagina a tu nuevo yo en dos o tres escenas reales de tu día, haciéndolo bien."},{label:"Sentir · 1 min",text:"Déjate sentir ahora un poco de la calma o la confianza de ese yo."},{label:"Comprometerte · 1 min",text:"Elige una acción concreta y el momento en que la harás."}],note:"Una adaptación abreviada de la meditación más larga de Dispenza, centrada en las partes que respalda la investigación."}},{heading:"Qué dice la investigación",paragraphs:["Una actualización de 2020 de un metaanálisis clásico sobre deporte analizó 37 estudios y encontró que la práctica mental tenía un efecto pequeño pero real en el rendimiento, menor que una estimación anterior de 1994, y que la práctica física funcionaba mejor. La revisión más amplia de 2021 encontró efectos mayores sobre la conducta cuando las personas ensayaban hacer la acción, en especial hacerla bien.","El ensayo sirve como preparación. Parece ayudar más cuando es concreto, lo repites y después haces la acción real."],visual:{kind:"compare",title:"Quédate con esto, deja aquello",left:{label:"Con respaldo de la investigación",items:["Ensayar en tu mente acciones específicas","Verte haciéndolo bien y luego probarlo de verdad","Imaginar a tu yo futuro con claridad y sentirlo cercano"]},right:{label:"Sin respaldo de la investigación",items:["Cambiar tus genes con el pensamiento","Curar enfermedades solo con la meditación","Cambiar la realidad mediante un campo cuántico","Habilidades místicas a través de la glándula pineal"]},note:"La meditación no reemplaza la atención médica. No suspendas ni retrases un tratamiento por ninguna afirmación como las de la derecha."}},{heading:"Mantén cerca a tu yo futuro",paragraphs:["La investigación de Hal Hershfield sobre la continuidad con el yo futuro sugiere por qué el ensayo puede importar. Las personas que se sienten parecidas y conectadas con su yo futuro, que pueden verlo con claridad y que lo valoran de forma positiva tienden a tomar decisiones que ayudan a ese yo futuro, como ahorrar más. Tu ensayo matutino es una manera de encontrarte con tu yo futuro todos los días, para que se sienta menos como un desconocido y más como tú."]}],example:{title:"Mei, 45 años, contadora",text:"Mei quería convertirse en alguien que habla en las reuniones. Cada mañana, después de servirse el té, se sentaba diez minutos con un temporizador. Soltaba a la Mei de antes que se quedaba callada y luego repasaba en su mente la reunión de las diez: levantando la mano, con la voz firme, con esa sensación de calma en el pecho. Terminaba con un compromiso: voy a hacer un comentario antes de que pasen los primeros veinte minutos. El primer día se quedó callada de todos modos. El tercer día hizo una pregunta. En la segunda semana compartió una idea sobre el presupuesto y su jefe le pidió que la pusiera por escrito. Seguía sintiendo nervios, pero ya no eran los nervios los que tomaban la decisión."},practice:["Escribe tres escenas breves de hoy en las que tu nuevo yo va a aparecer: quién está, qué pasa y qué haces.","Mañana por la mañana, antes de tomar el móvil, haz el ensayo de 10 minutos y recorre cada escena en tu mente al menos una vez, incluyendo la emoción.","Termina eligiendo una acción real para el día y vincúlala con un momento: “Cuando pase…, voy a…”."],reflection:"En tu ensayo, ¿qué hace tu nuevo yo de forma distinta en los primeros cinco minutos de un momento difícil?",question:"¿Qué tipo de ensayo es más probable que cambie lo que de verdad haces?",options:["Imaginarte haciendo bien la acción específica y luego probarla de verdad.","Imaginar solo la recompensa: los aplausos, el dinero o el cuerpo nuevo.","Meditar para cambiar tus genes y que el cambio ocurra solo."],correct:0,feedback:"Ensayar haciendo bien la acción tuvo los mayores efectos en la investigación, sobre todo cuando le siguió práctica real. Imaginar solo el resultado ayudó mucho menos, y las afirmaciones sobre los genes no tienen respaldo.",takeaway:"Ensaya el proceso en tu mente y luego dale una oportunidad real hoy.",sources:["identity-dispenza-habit","identity-dispenza-supernatural","identity-dispenza-new-self","identity-cole","identity-toth","identity-hershfield"],visual:{kind:"bars",title:"¿Qué tipo de ensayo mental cambió la conducta?",bars:[{label:"Ensayar hacerlo bien",value:.67,display:"g = 0.67"},{label:"Ensayar hacerlo",value:.48,display:"g = 0.48"},{label:"Imaginar un gran resultado",value:.23,display:"g = 0.23"},{label:"Imaginar solo los pasos",value:.17,display:"g = 0.17, no fiable"}],note:"Efectos promedio (g de Hedges) de Cole et al. (2021): 94 estudios aleatorizados, 5,685 personas, en su mayoría estudiantes. Alrededor de 0.2 es pequeño y 0.5 es moderado. El resultado de “solo los pasos” se apoya en apenas cinco efectos y no fue estadísticamente fiable.",sourceId:"identity-cole"},technique:{name:"Ensayo matutino del nuevo yo",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Siéntate en una postura cómoda, cierra los ojos y dedica un par de minutos a llevar tu atención de los pensamientos al cuerpo y al momento presente.","Recuerda el yo anterior que estás dejando atrás y, con tus propias palabras, suéltalo por hoy.","Pregúntate cómo pensaría, hablaría y actuaría hoy la mejor versión de ti.","Imagina a esa persona moviéndose por dos o tres escenas reales de tu día, con detalle.","Déjate sentir un poco de la emoción que sentiría ese nuevo yo, como calma, gratitud o confianza, como si ya fuera cierto.","Antes de abrir los ojos, elige una acción concreta que lo demuestre hoy."],evidence:"Ensayar mentalmente acciones específicas tiene un respaldo de pequeño a moderado en la investigación, sobre todo cuando le sigue práctica real. Las afirmaciones de los libros sobre un campo cuántico, la expresión de los genes, la curación de enfermedades y los estados místicos no tienen respaldo científico; no uses esta práctica en lugar de la atención médica.",sourceId:"identity-dispenza-habit"},photo:{id:"1600618528240-fb9fc964b853",alt:"Una mujer meditando en una terraza de madera al atardecer"}},{id:"identity-6",title:"Señales y entorno",minutes:9,goal:"Preparar tu entorno y tres planes «si… entonces…» para que tu nuevo yo se convierta en la opción más fácil.",reading:["El contexto activa los hábitos: lugares, horas, personas, el móvil sobre la mesa. Eso funciona en ambos sentidos. El mismo mecanismo que mantiene tus patrones anteriores puede ayudarte a practicar los nuevos. James Clear llama encadenamiento de hábitos a una versión de esto, a partir de una idea de BJ Fogg: une un hábito nuevo a uno que ya haces todos los días. “Después de encender el hervidor, voy a escribir una línea en mi diario.” Clear también sugiere diseñar tu espacio para que la nueva elección sea visible y fácil, y la vieja requiera un paso extra.","La investigación sobre los planes «si… entonces…», que los psicólogos llaman intenciones de implementación, respalda esto. Peter Gollwitzer y Paschal Sheeran reunieron 94 pruebas y encontraron que los planes con la forma “si ocurre la situación X, entonces haré Y” mejoraron el logro de metas con un efecto promedio entre moderado y grande. El plan funciona en parte porque la situación se vuelve más fácil de notar y la respuesta más automática. Para el cambio de identidad, escribe planes «si… entonces…» para los momentos exactos en que tu yo anterior suele ganar."],deeper:[{heading:"Escribe planes para los momentos que importan",paragraphs:["Vuelve a tu inventario del yo anterior de la lección 1. La columna del entorno muestra los momentos en que suele aparecer el patrón. Cada uno puede convertirse en el “si” de un plan, y el voto más pequeño de tu nuevo yo puede convertirse en el “entonces”."],visual:{kind:"table",title:"Momentos del yo anterior, planes del nuevo yo",columns:["Si…","entonces voy a…"],rows:[["me siento en mi escritorio después de comer,","abrir primero el archivo más difícil, durante cinco minutos."],["siento la irritación de siempre al estacionarme en casa,","respirar lento tres veces antes de entrar."],["estiro la mano hacia el móvil en la cama,","ponerlo a cargar al otro lado del cuarto y leer una página."]],note:"Mantén el “si” concreto y observable, y el “entonces” lo bastante pequeño como para hacerlo incluso en un mal día."}},{heading:"Qué dice la investigación",paragraphs:["Los investigadores de hábitos Wendy Wood y Dennis Rünger señalan que los hábitos pueden persistir aunque cambien las intenciones, porque el contexto sigue activándolos. Por eso cambiar el contexto, o planificar de antemano cómo responder en él, suele funcionar mejor que esforzarte más.","Los estudios del equipo de Phillippa Lally también sugieren mantener la nueva acción a una hora y en un lugar constantes mientras se forma. Una señal estable ayuda a vincular la nueva acción con ese momento."],visual:{kind:"bars",title:"Efecto promedio de los planes «si… entonces…» en el logro de metas",bars:[{label:"Plan «si… entonces…» frente a solo la meta",value:.65,display:"d = 0.65"}],note:"De Gollwitzer y Sheeran (2006), 94 pruebas independientes. Alrededor de 0.5 es moderado y 0.8 es grande. Las metas y los contextos variaban mucho, y los estudios publicados pueden exagerar los efectos.",sourceId:"identity-gollwitzer"}},{heading:"Errores comunes",paragraphs:["Una señal vaga. “Por la mañana” no es un momento que vayas a notar; “después de encender el hervidor” sí. Clear también aconseja igualar las frecuencias: un hábito diario necesita un ancla que ocurra a diario.","Confiar en la fuerza de voluntad en un espacio tentador. Si la señal del yo anterior está siempre a la vista, practicar el nuevo patrón te cuesta más. Mueve la señal, añade un paso o cambia la habitación."]}],example:{title:"Jonás, 31 años, desarrollador de software",text:"El yo anterior de Jonás se pasaba casi todas las noches jugando a videojuegos hasta la una de la madrugada. Su nuevo yo era alguien que lee y duerme bien. El domingo desconectó el control de la consola y lo guardó en un cajón del pasillo, y dejó una novela sobre su almohada. Escribió un plan en una nota junto a la cocina: si cierro el portátil después de cenar, entonces pongo el hervidor y leo diez páginas. Algunas noches todavía jugaba, pero solo después de leer, y para entonces solía tener demasiado sueño para empezar. En la primera semana se durmió antes de la medianoche cuatro noches de siete, cuatro más que la semana anterior."},practice:["Elige un hábito diario que ya cumplas con constancia y vincula con él la acción de tu nuevo yo: “Después de…, voy a…”.","Cambia una cosa en tu espacio esta noche para que la nueva acción sea visible y la vieja requiera un paso extra.","Escribe tres planes «si… entonces…» para los momentos en que tu yo anterior suele ganar, y guárdalos donde los veas."],reflection:"¿Qué lugar u objeto de tu vida está votando en silencio por tu yo anterior?",question:"¿Cuál de estos planes tiene más probabilidades de ayudar?",options:["Voy a intentar ser más paciente esta semana.","Voy a ser una persona completamente nueva a partir del lunes.","Si mi hijo derrama algo en la cena, entonces voy a exhalar una vez antes de hablar."],correct:2,feedback:"Un plan «si… entonces…» concreto nombra el momento exacto y la respuesta exacta, lo que te ayuda a reconocer el momento y dar la respuesta prevista. Las intenciones generales y las grandes promesas no te dicen cuándo actuar.",takeaway:"Facilita la acción de tu nuevo yo y prepara un plan para los momentos en que suele imponerse el anterior.",sources:["identity-clear-stacking","identity-clear-environment","identity-gollwitzer","identity-wood-runger","identity-gardner"],visual:{kind:"steps",title:"Construye una señal para tu nuevo yo",steps:[{label:"Elige un ancla",text:"Un hábito que ya haces a diario, a la hora y en el lugar adecuados."},{label:"Vincula la nueva acción",text:"“Después de…, voy a…”, pequeña y concreta."},{label:"Hazla visible",text:"Pon lo que necesita la nueva acción donde lo veas."},{label:"Dificulta la acción anterior",text:"Saca la vieja señal de tu vista o añade un paso extra."},{label:"Prueba y ajusta",text:"Después de una semana, conserva lo que funciona y cambia el ancla si hace falta."}],note:"Basado en el encadenamiento de hábitos y el diseño del entorno de James Clear, y en la investigación sobre señales del contexto."},technique:{name:"Encadenamiento de hábitos",origin:"James Clear · Atomic Habits (2018), a partir de Tiny Habits de BJ Fogg",steps:["Haz una lista de hábitos que ya cumples todos los días sin falta, como preparar el café o cepillarte los dientes.","Elige uno que ocurra a la hora y en el lugar adecuados para tu nueva acción.","Escribe la fórmula: después de [hábito actual], voy a [hábito nuevo].","Mantén la nueva acción pequeña y concreta para que quepa en ese momento.","Prepara tu espacio para que todo lo que necesita el nuevo hábito ya esté ahí.","Pruébalo durante una semana y cambia el ancla si no encaja."],evidence:"Vincular una acción nueva con una señal diaria estable coincide con la investigación sobre formación de hábitos y planes «si… entonces…», que muestra beneficios de moderados a grandes en promedio. El encadenamiento de hábitos como tal no se ha probado como método con nombre propio.",sourceId:"identity-clear-stacking"},photo:{id:"1675762647949-1b25f669a687",alt:"Un par de zapatos blancos sobre un piso de madera"}},{id:"identity-7",title:"El camino de los 66 días",minutes:10,goal:"Planear cómo seguir a largo plazo, incluyendo qué harás cuando tropieces.",reading:["¿Cuánto tarda el nuevo yo en sentirse natural? Quizá hayas oído que son 21 días. El estudio más conocido sobre hábitos en la vida real apunta a algo más lento y más variable. Phillippa Lally y sus colegas del University College London pidieron a voluntarios que repitieran una conducta diaria de salud en el mismo contexto. El tiempo hasta que se sintió casi totalmente automática osciló entre 18 y 254 días, con una mediana de unos 66. Las acciones simples, como beber un vaso de agua, se volvieron automáticas más rápido que las exigentes, como una serie de abdominales.","Dos hallazgos pueden darte tranquilidad. Perder un solo día no perjudicó de manera significativa la formación del hábito, y el cambio siguió una curva: mayores avances al principio y luego una estabilización gradual. Así que planea los tropiezos en lugar de fingir que no ocurrirán. La regla práctica de James Clear es evitar fallar dos veces seguidas. Y sé amable contigo cuando tropieces: en experimentos de Juliana Breines y Serena Chen, las personas a quienes se animó a mirar un fracaso con autocompasión se sintieron más motivadas a mejorar; por ejemplo, estudiaron más tiempo después de reprobar un examen."],deeper:[{heading:"Una revisión semanal",paragraphs:["Llevar un registro del progreso ayuda. Un metaanálisis de 138 estudios con casi 20,000 personas encontró que las intervenciones que ayudaban a las personas a seguir su progreso con más frecuencia mejoraban el logro de metas, con un efecto promedio moderado. Los efectos fueron mayores cuando el progreso se anotaba o se compartía con alguien.","Una revisión semanal es una forma sencilla de hacerlo. Quince minutos, el mismo día y a la misma hora cada semana, con tu conteo de la lección 4 delante."],visual:{kind:"table",title:"Tu revisión semanal de 15 minutos",columns:["Pregunta","Por qué ayuda"],rows:[["¿Cuántos votos emití esta semana?","Contar hace visible el progreso."],["¿Cuándo ganó el yo anterior y cuál fue la señal?","Convierte los tropiezos en información."],["¿Qué voy a ajustar: la señal, el tamaño o el plan?","Te ayuda a seguir ajustando el plan."],["¿Qué hizo mi nuevo yo que me alegra?","Aporta pruebas de la persona en la que te estás convirtiendo."]],note:"Escribir tus respuestas, o compartirlas con un amigo, puede reforzar el efecto."}},{heading:"Cuando tropiezas",paragraphs:["Los tropiezos forman parte de todo cambio real. Lo que importa es lo que te dices después. Una espiral de vergüenza dice que todo el proyecto ha fracasado; volver a empezar con amabilidad implica aceptar el tropiezo como algo humano y preguntarte qué te frenó.","El consejo de Clear es centrarte en volver, no en compensar el día perdido. La siguiente acción solo tiene que ser pequeña."],visual:{kind:"compare",title:"Dos formas de responder a un tropiezo",left:{label:"Espiral de vergüenza",items:["Lo eché a perder; volví al punto de partida.","Ya está arruinado, ¿para qué molestarme hoy?","Dejar de llevar el registro para no tener que verlo."]},right:{label:"Reinicio amable",items:["Esto pasó, y es humano.","¿Qué se interpuso esta vez?","Hacer hoy la versión más pequeña."]},note:"Si un tropiezo te deja sin esperanza durante días, o el ánimo bajo no mejora, por favor busca a un profesional de la salud. En una crisis, llama al número de emergencias de tu país."}},{heading:"Mantén a la vista a tu yo futuro",paragraphs:["La investigación sobre la continuidad con el yo futuro sugiere que las personas toman decisiones más favorables para el futuro cuando imaginan a su yo futuro con claridad y lo sienten parecido y conectado con quienes son ahora. Una breve nota de ti mismo dentro de un año, agradeciéndote algo concreto que seguiste haciendo, es una forma de mantener cerca a esa persona en el largo camino."]}],example:{title:"Rosa, 52 años, dueña de una tienda",text:"El día 23 de convertirse en alguien que camina todas las mañanas, Rosa tuvo gripe y faltó cuatro días seguidos. Su yo anterior tenía lista una frase conocida: típico, nunca soy constante con nada. En la revisión del domingo prefirió contar lo que había hecho. Diecisiete caminatas en veintitrés días. Cada día perdido se debió a la enfermedad o a la única semana en que había abierto la tienda temprano. El lunes reinició con una caminata de cinco minutos alrededor de la cuadra, que era todo lo que le daban las fuerzas. Hacia el día sesenta el hábito todavía no era automático en las mañanas de lluvia, pero en las mañanas sin lluvia ya no discutía consigo misma sobre salir. Eso también lo anotó."},practice:["Pon una revisión semanal de 15 minutos en tu calendario, el mismo día y a la misma hora cada semana.","Escribe ahora tu plan de reinicio: “Si falto un día, entonces al día siguiente haré la versión más pequeña de mi hábito.”","Escribe una breve nota de tu yo futuro, dentro de un año, agradeciéndote una cosa concreta que seguiste haciendo."],reflection:"¿Qué te gustaría decirte el día que tropieces, para volver a empezar al día siguiente?",question:"Has faltado dos días a tu nuevo hábito. ¿Qué sugiere la investigación?",options:["Demuestra que no eres el tipo de persona que puede cambiar.","Retoma hoy una versión pequeña; en los estudios, saltarse algún día no impidió que se formara el hábito.","Espera a sentirte motivado otra vez, aunque tarde un mes."],correct:1,feedback:"En la investigación sobre hábitos, perder una oportunidad no perjudicó de forma importante la formación del hábito. Reiniciar rápido y con amabilidad, con un paso pequeño, evita que un tropiezo se convierta en un patrón nuevo.",takeaway:"Construyes tu nuevo yo cada vez que retomas el hábito, aunque algún día te lo hayas saltado.",sources:["identity-lally","identity-gardner","identity-clear-second-mistake","identity-breines","identity-harkin","identity-hershfield"],visual:{kind:"bars",title:"Días hasta que un hábito diario se sintió casi automático",bars:[{label:"Más rápido",value:18,display:"18 días"},{label:"Mediana",value:66,display:"66 días"},{label:"Más lento",value:254,display:"254 días"}],note:"De Lally et al. (2010): 96 voluntarios, 12 semanas, una conducta diaria elegida por cada uno; la curva pudo estimarse para 39 personas. La automaticidad fue autoinformada, y los tiempos superiores a los 84 días observados son extrapolaciones.",sourceId:"identity-lally"},technique:{name:"Nunca faltes dos veces",origin:"James Clear · Avoid the Second Mistake (2014)",steps:["Acepta de antemano que vas a faltar algunos días.","Cuando falles uno, céntrate solo en volver al día siguiente, no en compensarlo.","Haz fácil el reinicio con la versión más pequeña del hábito.","Pon el hábito en un horario fijo para que no dependa de tu estado de ánimo.","Mira qué causó la falta y elimina ese obstáculo si puedes."],evidence:"Es una regla práctica, no un método probado. Es coherente con la investigación sobre hábitos que muestra que un día perdido ocasional no frenó seriamente la formación del hábito, y con experimentos en los que la autocompasión tras un fracaso aumentó la motivación para mejorar.",sourceId:"identity-clear-second-mistake"},photo:{id:"1760715160644-7f5939675b68",alt:"Excursionistas caminando por un sendero a través de un prado dorado"}}]},h=Object.freeze(Object.defineProperty({__proto__:null,COURSE:q,SOURCES:v},Symbol.toStringTag,{value:"Module"})),f=[{id:"meaning-frankl",title:"Viktor E. Frankl · El hombre en busca de sentido (1946) y el Instituto Viktor Frankl de Viena (descripción de la logoterapia)",url:"https://www.viktorfrankl.org/logotherapy.html",type:"technique",finding:"El Instituto Viktor Frankl describe la logoterapia y el análisis existencial como un enfoque psicoterapéutico centrado en el sentido, que Frankl desarrolló a partir de la década de 1930. Se apoya en tres supuestos: la libertad de la voluntad (las personas pueden elegir su postura ante las circunstancias, incluso en la enfermedad o la adversidad), la voluntad de sentido (buscar sentido es una motivación humana primaria y, cuando se frustra, la persona puede sentir un vacío interior) y el sentido de la vida (el sentido es propio de cada persona y de cada situación, y se descubre en lugar de imponerse). En su libro, Frankl describe tres grandes fuentes de sentido: crear una obra o realizar un acto, vivir una experiencia o amar a alguien, y la actitud que adoptas ante un sufrimiento que no puedes evitar.",limitation:"Se consultó la página del instituto. Las tres fuentes de sentido proceden de resúmenes habituales del libro de Frankl y no se comprobaron de nuevo en una página consultada. La logoterapia es un enfoque clínico con una base de investigación más reducida que la de muchas otras terapias; las reflexiones de este curso son ejercicios de reflexión personal, no logoterapia."},{id:"meaning-act-values",title:"Association for Contextual Behavioral Science · Los seis procesos centrales de la ACT (valores y acción comprometida)",url:"https://contextualscience.org/the_six_core_processes_of_act",type:"technique",finding:"La terapia de aceptación y compromiso (ACT, por sus siglas en inglés) busca desarrollar flexibilidad psicológica mediante seis procesos conectados entre sí. Los valores son cualidades que eliges para orientar tus acciones. No se adquieren como un objeto: los pones en práctica en cada momento, en ámbitos como la familia o el trabajo. La ACT ayuda a elegir valores propios, sin dejarse llevar por la evitación, la presión social o pensamientos del tipo “debería”. La acción comprometida consiste en construir patrones cada vez más amplios de conducta basada en valores, vinculando metas concretas y alcanzables con los valores y trabajando con las barreras internas que aparecen en el camino.",limitation:"Es una descripción de la asociación profesional dedicada a la ACT, no un estudio. Explica el modelo; no muestra cuánto ayuda un ejercicio de valores hecho por tu cuenta. La imagen de la brújula que usa este curso es una forma habitual de enseñar los valores en la ACT, no un término de esta página."},{id:"meaning-carrillo",title:"Carrillo et al. · 2019 · Effects of the Best Possible Self intervention: a systematic review and meta-analysis (PLOS One)",url:"https://doi.org/10.1371/journal.pone.0222386",type:"research",finding:"Al reunir 29 estudios con 2,909 participantes, el metaanálisis encontró que el ejercicio del mejor yo posible mejoró el optimismo (d = 0.334), el afecto positivo (d = 0.511) y el bienestar (d = 0.325), y redujo el afecto negativo (d = 0.192) y los síntomas depresivos (d = 0.115), en comparación con las condiciones de control.",limitation:"Los efectos fueron de pequeños a medianos, y el efecto sobre los síntomas depresivos fue pequeño. La frecuencia y el tiempo dedicado a escribir variaban entre los estudios, y la mayoría midió resultados a corto plazo. El análisis evalúa el ejercicio del mejor yo posible, no el sentido de la vida de forma directa ni este curso."},{id:"meaning-best-possible-self",title:"Laura A. King · Escritura del mejor yo posible (2001), según la revisión de Carrillo et al. (2019)",url:"https://doi.org/10.1371/journal.pone.0222386",type:"technique",finding:"En el ejercicio del mejor yo posible, las personas imaginan un futuro en el que las cosas han salido tan bien como razonablemente podrían, después de trabajar duro por lo que les importa, y escriben sobre ese futuro durante varios minutos, a veces en varias ocasiones. Carrillo et al. reunieron 29 estudios de este ejercicio.",limitation:"No se consultó el artículo original de King de 2001; el procedimiento se describe tal como se usa habitualmente en los estudios revisados. La duración de las sesiones y su número varían entre estudios. Vincular el ejercicio con los valores personales es un añadido propio de este curso."}],j={id:"meaning",title:"¿Vives sin saber para qué? Cómo dar a tu vida un rumbo que sea tuyo",subtitle:"6 lecciones de 8 a 10 minutos. Pon nombre a tus valores y actúa hoy en uno de ellos.",description:"¿Y si el sentido no fuera tanto una gran respuesta que se encuentra una sola vez, sino una dirección que eliges de nuevo cada día? Este curso reúne las ideas de Viktor Frankl sobre el sentido y el trabajo con valores de la terapia de aceptación y compromiso, y las convierte en pequeñas decisiones diarias.",scope:"Para adultos que se sienten ocupados pero sin rumbo, que están en una encrucijada o que quieren que sus días reflejen lo que les importa. Es un curso educativo y de reflexión personal. No es terapia ni tratamiento. Es normal tener dudas sobre el sentido de la vida de vez en cuando, pero si la vida te ha parecido vacía o sin sentido durante semanas, habla con un médico o con un profesional de la salud mental. Si tienes pensamientos de hacerte daño, llama ahora al número de emergencias de tu zona.",outcome:"Un mapa de lo que ya da sentido a tu vida, una lista corta de valores en tus propias palabras, una forma de comprobar cuáles son de verdad tuyos, una manera de afrontar las situaciones difíciles que no puedes cambiar, una imagen escrita de tu mejor futuro posible y una pequeña decisión basada en tus valores que puedes tomar cada día.",photo:{id:"1500530855697-b586d89ba3ee",alt:"Un camino que serpentea entre colinas despejadas hacia el horizonte"},lessons:[{id:"meaning-1",title:"De dónde viene el sentido",minutes:8,goal:"Conoce las tres grandes fuentes de sentido de Frankl y observa dónde aparece ya cada una en tu vida.",reading:["Viktor Frankl fue un psiquiatra vienés que desarrolló un enfoque al que llamó logoterapia, una terapia centrada en el sentido. Su libro más conocido nació de los años que pasó prisionero en campos de concentración nazis. Una de sus ideas centrales es que la búsqueda de sentido es un impulso humano básico, no un lujo para quienes ya tienen resueltos sus otros problemas. Cuando esa búsqueda se bloquea durante mucho tiempo, sostenía, las personas pueden sentir un vacío interior. Frankl no creía que nadie pudiera decirte cuál es el sentido de tu vida. Según él, depende de cada persona y de su situación, y se descubre en lugar de inventarse.","Frankl describió tres grandes fuentes de sentido. La primera es crear o hacer: un trabajo, un proyecto, un acto, algo que le das al mundo. La segunda es vivir o amar: la belleza, la naturaleza, la verdad y, sobre todo, conocer y querer a otra persona tal como es. La tercera es la actitud que adoptas ante un sufrimiento que no puedes evitar. La mayoría de las personas encuentra sentido en las tres, en momentos distintos. La pregunta útil no es cuál es el sentido de la vida en general, sino qué te pide este momento, esta relación o esta tarea."],deeper:[{heading:"Responder a la vida, sin esperar una gran respuesta",paragraphs:["Muchas personas esperan a que llegue un gran propósito para sentir que su vida tiene valor. Frankl le dio la vuelta a la pregunta. En lugar de preguntar qué te debe la vida, puedes preguntar qué te pide la vida a ti, aquí y hoy. Así, el sentido se vuelve más concreto y cercano: una conversación en la que participar, un trabajo que hacer bien, una persona a quien cuidar.","El Instituto Viktor Frankl describe esto como libertad de la voluntad: aun cuando las circunstancias no cambien, conservas cierta libertad para elegir cómo responder. Esa libertad no hace que lo difícil deje de serlo. Te da algo en lo que apoyarte."],visual:{kind:"compare",title:"Dos formas de preguntar por el sentido",left:{label:"Esperar una gran respuesta",items:["¿Cuál es el sentido de mi vida?","Lo sentiré cuando todo esté resuelto.","El sentido está en otra parte."]},right:{label:"Responder a este momento",items:["¿Qué me pide este momento?","Puedo actuar hoy según lo que me importa.","El sentido suele estar cerca."]},note:"Ilustración propia del cambio de mirada que describe Viktor Frankl."}},{heading:"Lo que dice la investigación y lo que no",paragraphs:["La logoterapia es un enfoque clínico con una base de investigación más reducida que la de muchas otras terapias, así que este curso trata las ideas de Frankl como una forma útil de pensar y no como un tratamiento comprobado. Aun así, algunas de sus ideas sí tienen relación con lo que se ha investigado. Un metaanálisis de 27 estudios con 4,045 personas encontró que realizar actos de bondad tenía un efecto positivo, de pequeño a mediano, en el bienestar de quien los hacía.","Ese resultado mide una pequeña parte de la primera fuente de sentido: hacer algo por otra persona. No demuestra que Frankl tuviera razón en todo, ni es un motivo para obligarte a hacer buenas acciones. Es una pista de que las acciones cotidianas suelen dar sentido a la vida."]}],example:{title:"Tomás, 41 años, supervisor de almacén",text:"Tomás había empezado a sentir que su vida se reducía a trabajo, sueño y cuentas. Un domingo por la tarde dibujó tres columnas en el reverso de un sobre: hacer, vivir y afrontar. En “hacer” anotó que ese mes había formado a dos personas nuevas y que las dos ya tenían confianza. En “vivir” escribió los paseos de los sábados con su hija y el olor de la panadería en su camino al trabajo. En “afrontar” escribió la enfermedad de su padre, que no podía curar. Pero sí podía seguir visitándolo. Nada en su vida había cambiado. Pero el lunes notó que prestaba más atención cuando el compañero que acababa de llegar al equipo le hacía una pregunta, porque ahora sabía que esa parte del trabajo le importaba."},practice:["Dibuja tres columnas tituladas hacer, vivir y afrontar, y escribe al menos una cosa del último mes bajo cada una.","Encierra en un círculo la anotación que más te sorprendió, la que no esperabas que tuviera sentido para ti.","Elige un momento de hoy en el que te preguntarás qué te pide ese momento, y anota cuándo será."],reflection:"¿Cuál de las tres fuentes de sentido sueles pasar por alto en tu propia vida?",question:"¿Qué opción describe las tres grandes fuentes de sentido de Frankl?",options:["Dinero, estatus y reconocimiento.","Crear o hacer, vivir o amar, y la actitud ante el sufrimiento inevitable.","Pensamiento positivo, visualización y afirmaciones."],correct:1,feedback:"Frankl señaló lo que das (trabajo y actos), lo que recibes (experiencias y amor) y la postura que adoptas ante un sufrimiento que no puedes evitar.",takeaway:"El sentido se encuentra al responder a lo que te pide cada día, sin esperar una respuesta definitiva.",sources:["meaning-frankl","faith-kindness"],visual:{kind:"table",title:"Tres fuentes de sentido",columns:["Fuente","En qué consiste","Un ejemplo cotidiano"],rows:[["Crear o hacer","Dar algo a través de un trabajo, un proyecto o un acto","Ayudar a un compañero nuevo a orientarse"],["Vivir o amar","Disfrutar de la belleza, la verdad y la naturaleza, o del vínculo con otra persona","Un paseo tranquilo con alguien a quien quieres"],["Actitud","La postura que adoptas ante un sufrimiento que no puedes evitar","Mantener tu dignidad y tu amabilidad durante una enfermedad"]],note:"Fuentes de Viktor Frankl; los ejemplos son propios."},technique:{name:"Repaso de las tres fuentes de sentido",origin:"Viktor E. Frankl · Man’s Search for Meaning (1946)",steps:["Reserva diez minutos tranquilos con papel y lápiz.","Bajo “hacer”, anota lo que has creado, dado o logrado últimamente, por pequeño que sea.","Bajo “vivir”, anota los momentos de belleza, conexión o amor que has recibido.","Bajo “afrontar”, anota cualquier dificultad que no puedas cambiar y cómo has decidido afrontarla.","Relee las listas y pregúntate a cuál te gustaría dedicar un poco más de atención esta semana."],evidence:"Este repaso es una forma estructurada propia de reflexionar sobre las tres fuentes de sentido de Frankl; no se ha probado como ejercicio. Las ideas de Frankl provienen de la experiencia clínica y la filosofía más que de ensayos controlados.",sourceId:"meaning-frankl"},photo:{id:"1469474968028-56623f02e42e",alt:"Una figura solitaria sobre una roca por encima de un valle con niebla"}},{id:"meaning-2",title:"Los valores son una dirección, no una meta",minutes:9,goal:"Comprende la diferencia entre valores y metas, y nombra algunos valores con tus propias palabras.",reading:["La terapia de aceptación y compromiso, conocida como ACT, es un enfoque psicológico moderno que da un lugar central a los valores. En la ACT, los valores son cualidades que eliges para guiar tu forma de actuar: ser cariñoso, ser curioso, ser honesto, ser valiente. Son distintos de las metas. Una meta se puede terminar y tachar de la lista, como correr una carrera, conseguir un empleo o terminar de pagar un préstamo. Un valor nunca se completa. Ser cariñoso no tiene un punto final. Solo puedes actuar con cariño, o no, en este momento concreto.","Una imagen útil es la de una brújula. Si quieres viajar hacia el oeste, puedes caminar hacia el oeste durante años y nunca llegar a un lugar llamado Oeste. En el camino pasas por destinos reales, y esos destinos son tus metas. Los valores te dicen hacia dónde ir; las metas marcan las paradas del camino. Esto importa porque las metas van y vienen. Cuando alcanzas una puedes sentir un extraño vacío, y cuando no lo logras puedes sentirte perdido. Un valor te acompaña en ambos casos y te señala el siguiente paso."],deeper:[{heading:"Valores en distintas áreas de la vida",paragraphs:["La ACT describe los valores como direcciones continuas en distintas áreas de la vida, como la familia, el trabajo, la amistad, la salud y la comunidad. Puede ayudar mirar algunas áreas de una en una, porque el valor que más importa en el trabajo puede ser distinto del que más importa en casa.","Usa palabras cortas y activas. “Estar presente como padre” es más fácil de llevar a la acción que “familia”. Si un valor suena a algo que solo dirías para impresionar a otros, déjalo de lado por ahora."],visual:{kind:"table",title:"La misma área, vista como valor y como meta",columns:["Área de la vida","Un valor (una dirección)","Una meta (un destino)"],rows:[["Familia","Ser cálido y estar presente","Cenar juntos tres noches esta semana"],["Trabajo","Hacer un trabajo cuidadoso y útil","Terminar el informe para el viernes"],["Salud","Cuidar mi cuerpo","Caminar 20 minutos después de comer"],["Amistad","Ser leal y mantener el contacto","Llamar a Sam este fin de semana"]],note:"Ejemplos propios de la distinción entre valores y metas que describe la ACT."}},{heading:"Errores comunes",paragraphs:["El primer error es escribir sentimientos como si fueran valores, por ejemplo “ser feliz” o “sentirme en calma”. Los sentimientos van y vienen y no los controlas del todo. Los valores tienen que ver con lo que haces, y por eso siguen siendo útiles en los días difíciles.","El segundo error es convertir los valores en reglas: “siempre debo ser productivo”. Un valor es una dirección elegida libremente, no una obligación con la que castigarte. El tercero es elegir demasiados a la vez. Tres o cuatro valores que te importan de verdad son más útiles que una lista de veinte."]}],example:{title:"Priya, 33 años, diseñadora gráfica",text:"Priya se había puesto la meta de conseguir un puesto senior antes de que terminara el año. Cuando el ascenso se lo dieron a otra persona, sintió que todo el año había sido en vano. Esa noche probó el ejercicio de la brújula. Bajo trabajo escribió el valor “hacer cosas claras y agradables de usar”. Al repasar el año, vio decenas de momentos en los que había vivido ese valor: los arreglos de accesibilidad que nadie le pidió, la diseñadora junior a la que había orientado. La meta se había esfumado, pero la dirección seguía ahí. A la mañana siguiente dedicó veinte minutos a esbozar un trabajo para su portafolio basado en ese valor, en vez de mirar ofertas de empleo."},practice:["Elige tres áreas de tu vida y escribe un valor para cada una, como una frase corta que empiece con “ser” o con un verbo.","Junto a cada valor, escribe una meta que te permitiría avanzar en esa dirección durante el próximo mes.","Revisa cada valor: ¿podrías actuar según él incluso en un mal día? Si no, reescríbelo como algo que haces y no como algo que sientes."],reflection:"Si nadie fuera a enterarse nunca de lo que haces, ¿qué rumbo seguirías queriendo para tu vida?",question:"Según la ACT, ¿cuál es la diferencia clave entre un valor y una meta?",options:["Los valores son más importantes que las metas, así que deberías abandonar tus metas.","Los valores son sentimientos y las metas son acciones.","Una meta se puede completar, mientras que un valor es una dirección que sigues al actuar en cada momento."],correct:2,feedback:"Las metas son destinos que puedes alcanzar y tachar. Los valores son direcciones elegidas que nunca se completan, solo se viven en cada momento. Necesitas metas y valores.",takeaway:"Las metas son las paradas del camino; los valores te orientan.",sources:["meaning-act-values","motivation-sdt"],visual:{kind:"compare",title:"Valores y metas",left:{label:"Valores",items:["Una dirección que eliges","Nunca terminan","Disponibles en cada momento","Ejemplo: ser cariñoso"]},right:{label:"Metas",items:["Un destino al que llegas","Se pueden tachar","Se alcanzan en un momento del futuro","Ejemplo: visitar a mamá el domingo"]},note:"Resumen propio de la distinción que describe la Association for Contextual Behavioral Science."},technique:{name:"Brújula de valores",origin:"Terapia de aceptación y compromiso · trabajo con valores, según la descripción de la Association for Contextual Behavioral Science",steps:["Dibuja una brújula sencilla y escribe en cada uno de sus cuatro puntos un área de tu vida, como relaciones, trabajo, salud y crecimiento personal.","Para cada área, escribe en pocas palabras cómo quieres actuar allí, como una cualidad y no como un resultado.","Puntúa de 0 a 10 cuánto se parecieron tus acciones de la última semana a cada valor.","Elige el área que más te importe entre aquellas donde tus acciones más se alejan de tus valores.","Escribe una pequeña acción que podrías realizar esta semana en esa dirección."],evidence:"Aclarar los valores es una parte central de la ACT, que se describe como un conjunto de procesos y no como un único ejercicio. Esta versión de la brújula no se ha probado por sí sola, y se desconoce su efecto cuando se hace en solitario, fuera de terapia.",sourceId:"meaning-act-values"},photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Nubes que pasan sobre acantilados verdes y un valle"}},{id:"meaning-3",title:"¿De quién son estos valores?",minutes:9,goal:"Distingue los valores que has elegido de verdad de los que nacen de la presión, la culpa o el miedo.",reading:["Algunos de los valores que tenemos son prestados. Vienen de los padres, de una cultura, de un trabajo o de las redes sociales, y muchas veces llegan con la palabra “debería”. Debería querer una casa más grande. Debería ser más ambicioso. La ACT anima a elegir valores que sean realmente propios, y a no escogerlos para evitar una incomodidad, para complacer a otros o porque un pensamiento lo exige. Un valor prestado no siempre está mal. Muchos valores que aprendimos de otros terminan siendo realmente nuestros. La pregunta es si lo sigues eligiendo al examinarlo con calma.","La investigación sobre la teoría de la autodeterminación hace una distinción parecida. Separa la motivación autónoma, que nace del interés y de los valores personales, de la motivación controlada, que nace de recompensas, presiones o expectativas ajenas. La motivación que nace de una elección propia tiende a ser de mejor calidad y más fácil de mantener. Una comprobación sencilla es imaginar que nadie vería ni elogiaría nunca lo que haces. Si el valor sigue importando, probablemente es tuyo. Si se desinfla de inmediato, quizá responda a lo que otra persona espera de tu vida."],deeper:[{heading:"Preguntar “por qué”, con honestidad",paragraphs:["Coaches populares, entre ellos Tony Robbins, uno de los más conocidos, suelen animar a las personas a encontrar su “porqué”: la razón más profunda detrás de lo que quieren. La idea tiene cierto fundamento. Preguntarte varias veces seguidas por qué quieres algo puede llevarte de una meta superficial al valor que hay debajo.","Pero las grandes promesas que a veces la acompañan, como que el “porqué” correcto te volverá imparable, no se han puesto a prueba. Una explicación más prudente sería esta. Preguntar por qué te ayuda a ver lo que te importa. No reemplaza la planificación, el descanso ni el apoyo, y tu respuesta puede cambiar con los años."],visual:{kind:"compare",title:"¿Lo eliges o sientes que deberías?",left:{label:"Se siente como un “debería”",items:["Viene con culpa o miedo","Importa sobre todo si otros lo ven","Suena a la voz de otra persona"]},right:{label:"Se siente elegido",items:["Sigue importando cuando nadie mira","Te da energía o sientes que encaja contigo","Lo volverías a elegir hoy"]},note:"Lista de comprobación propia, basada en el énfasis de la ACT en los valores elegidos libremente y en la teoría de la autodeterminación."}},{heading:"Lo que dice la investigación",paragraphs:["Un metaanálisis de 73 estudios de intervención en salud encontró que los programas basados en la teoría de la autodeterminación producían aumentos de pequeños a medianos en la motivación autónoma y cambios positivos pequeños en la salud física y psicológica. Las personas cuya motivación autónoma crecía también tendían a mejorar sus hábitos de salud.","Esos estudios trataban de hábitos de salud, no de valores de vida en general, y los efectos en la salud fueron modestos. Aun así, encajan con la idea de esta lección: hacer algo por razones que sientes tuyas tiende a sostenerse mejor que hacerlo bajo presión."]}],example:{title:"Marcus, 26 años, contador junior",text:"Marcus había puesto el “éxito económico” entre sus valores principales. Cuando imaginó que nadie se enteraría, ese valor perdió importancia casi al instante. Lo que sentía en realidad era miedo a decepcionar a sus padres, que habían pasado apuros de dinero. Se preguntó por qué quería el éxito económico, tres veces seguidas. Las respuestas fueron pasando de “para tener un buen sueldo” a “para que mi familia se sienta segura” y a “ser alguien con quien se puede contar”. Esa última frase sí le importaba. Siguió esforzándose en su trabajo, pero también empezó a llamar cada semana a su hermano menor para ayudarlo con sus solicitudes a la universidad. No costaba nada, y se reconocía más en eso que en la meta salarial."},practice:["Toma los valores que escribiste en la lección anterior y lee cada uno imaginando que nadie te vería ni te elogiaría nunca por vivirlo.","Marca cada valor como elegido, debería o dudoso, y observa cualquier sensación corporal mientras lo haces.","Con un valor marcado como debería o dudoso, pregúntate tres veces “¿por qué me importa esto?” y anota adónde llegas."],reflection:"¿Cuáles de tus valores conservarías aunque las personas a quienes quieres impresionar nunca se enteraran?",question:"¿Qué dice la teoría de la autodeterminación sobre la motivación que nace de los valores personales?",options:["Es una forma de motivación autónoma, que tiende a ser de mejor calidad que la motivación impulsada por la presión o las recompensas.","Es más débil que la motivación impulsada por recompensas y presión.","Solo importa para las personas que ya tienen una autoestima alta."],correct:0,feedback:"La teoría de la autodeterminación separa la motivación autónoma, basada en el interés y los valores, de la motivación controlada, impulsada por recompensas, presión o expectativas ajenas. La primera tiende a durar más y a sentirse mejor.",takeaway:"Un valor es tuyo si sigue importando cuando nadie mira.",sources:["meaning-act-values","motivation-sdt","motivation-sdt-meta"],visual:{kind:"steps",title:"De una meta superficial a un valor",steps:[{label:"Nómbrala",text:"Escribe algo que quieres, como un ascenso o mudarte a otra ciudad."},{label:"Pregunta por qué",text:"¿Por qué me importa eso? Escribe la respuesta en una línea."},{label:"Pregunta otra vez",text:"Repite dos veces más, profundizando un poco más cada vez."},{label:"Compruébalo",text:"¿Seguiría importando si nadie se enterara? Si es así, quizá hayas encontrado un valor."}],note:"Versión propia de un ejercicio habitual de “porqué”; no se ha probado como técnica independiente."},technique:{name:"¿Lo eliges o sientes que deberías?",origin:"Terapia de aceptación y compromiso · trabajo con valores, según la descripción de la Association for Contextual Behavioral Science",steps:["Escribe un valor que tengas, en una frase corta y activa.","Pregúntate si lo sostienes para evitar un sentimiento como la culpa, la vergüenza o el miedo.","Pregúntate si lo sostienes sobre todo para complacer a alguien o para quedar bien ante los demás.","Pregúntate si nace de un pensamiento que dice que deberías valorarlo, y no de que realmente te importe.","Si casi todas las respuestas son no, consérvalo; si casi todas son sí, busca el valor que hay debajo o reescríbelo con tus propias palabras."],evidence:"Estas preguntas siguen la descripción que hace la ACT de elegir valores que no estén impulsados por la evitación, la presión social o los pensamientos de “debería”. La comprobación en sí no se ha probado como ejercicio independiente.",sourceId:"meaning-act-values"},photo:{id:"1447752875215-b2761acb3c5d",alt:"Un puente peatonal de madera en un bosque verde"}},{id:"meaning-4",title:"El sentido cuando las cosas son difíciles",minutes:10,goal:"Aprende a encontrar la parte que aún puedes elegir cuando enfrentas una situación que no puedes cambiar.",reading:["La tercera fuente de sentido de Frankl es la más exigente: la actitud que adoptas ante un sufrimiento que no puedes evitar. Es fácil malinterpretarla. Frankl no dijo que el sufrimiento sea bueno ni que debas buscarlo. Si el sufrimiento se puede eliminar, lo significativo es eliminarlo, ya sea cambiando de trabajo, saliendo de una situación dañina o buscando ayuda médica. Se refería a lo que queda cuando algo de verdad no se puede cambiar: una pérdida, una enfermedad, un hecho del pasado. Incluso entonces, sostenía, conservas cierta libertad para decidir cómo afrontarlo.","Esa libertad suele ser pequeña y práctica. Puede ser la decisión de seguir siendo amable mientras sientes dolor, de mantener una rutina que te hace sentir tú mismo, o de dejar que una pérdida te impulse a cuidar más a las personas que siguen aquí. Esto no es lo mismo que fingir que estás bien. Puedes sentir la pena, el enojo y el miedo por completo y aun así preguntarte qué quieres que represente tu respuesta. La ACT plantea algo parecido: los valores pueden guiar lo que haces mientras los sentimientos difíciles siguen presentes."],deeper:[{heading:"Lo que esta idea no es",paragraphs:["Esta lección no afirma que todo suceda por una razón, ni exige que encuentres un lado positivo. Algunas cosas son simplemente dolorosas e injustas. Buscar sentido demasiado pronto, sobre todo cuando otra persona te presiona para hacerlo, puede hacerte sentir que no tienes derecho a estar mal.","Tampoco reemplaza la ayuda. Elegir tu actitud funciona junto con los pasos prácticos y el apoyo de otras personas, nunca en lugar de ellos."]},{heading:"Cuándo buscar más apoyo",paragraphs:["Las etapas difíciles forman parte de la vida, y muchas personas las superan con tiempo, descanso y la compañía de quienes las rodean. Pero si te has sentido vacío, sin esperanza o has sentido que la vida no tiene sentido durante varias semanas, o si la vida diaria se te está haciendo difícil de manejar, habla con un médico o con un profesional de la salud mental. Este curso no sustituye un tratamiento.","Si alguna vez tienes pensamientos de hacerte daño, llama de inmediato al número de emergencias de tu zona o a una línea de ayuda en crisis. Pedir ayuda no significa haber fracasado en la búsqueda de sentido. Es una de las cosas más significativas que puede hacer una persona."],visual:{kind:"steps",title:"Si una etapa difícil no se alivia",steps:[{label:"Observa",text:"¿Llevas semanas sintiendo vacío o desesperanza, o esas sensaciones van en aumento?"},{label:"Cuéntalo",text:"Comparte cómo te sientes con una persona de confianza."},{label:"Busca ayuda",text:"Habla con un médico o con un profesional de la salud mental."},{label:"En una crisis",text:"Si piensas en hacerte daño, llama ahora al número de emergencias de tu zona."}],note:"Orientación general de seguridad, no consejo médico."}}],example:{title:"Elena, 52 años, maestra de primaria",text:"La madre de Elena se había mudado a una residencia con una demencia que iba avanzando, y las visitas dejaban a Elena agotada y al borde del llanto. Había intentado todo lo que se le ocurrió para frenar el deterioro, y nada funcionó. Una noche escribió dos listas: lo que aún podía cambiar y lo que no. La enfermedad fue a la segunda lista. En la primera escribió la manera de pasar las visitas. En lugar de poner a prueba la memoria de su madre, algo que las angustiaba a las dos, empezó a llevar canciones antiguas para tararear juntas y una crema de manos que a su madre le gustaba. Las visitas seguían siendo tristes. Pero Elena empezó a salir de ellas con la sensación de haber sido la hija que quería ser."},practice:["Elige una dificultad actual y divídela en dos listas: lo que aún puedes cambiar y lo que de verdad no puedes.","De la primera lista, elige un paso práctico y decide cuándo lo darás.","Para la segunda lista, escribe una frase sobre cómo quieres afrontarlo, que empiece con “Aun así, puedo…”."],reflection:"En una situación que no puedes cambiar, ¿qué te gustaría que representara tu respuesta?",question:"¿Qué quiso decir Frankl con encontrar sentido en el sufrimiento inevitable?",options:["Que el sufrimiento es bueno para ti y debe buscarse.","Que debes esconder tu dolor y actuar como si estuvieras bien.","Que cuando algo de verdad no se puede cambiar, aún puedes elegir la actitud con la que lo enfrentas."],correct:2,feedback:"Frankl fue claro en que el sufrimiento evitable debe eliminarse. La actitud que adoptas importa para lo que queda cuando no es posible cambiar, y puede convivir con la pena y el miedo.",takeaway:"Cambia lo que puedas y elige cómo afrontar lo que no puedes cambiar.",sources:["meaning-frankl","meaning-act-values"],visual:{kind:"compare",title:"Dos listas para una situación difícil",left:{label:"Lo que puedo cambiar",items:["Pedir ayuda o información","Pasos prácticos, por pequeños que sean","Alejarme de lo dañino, si puedo"]},right:{label:"Lo que no puedo cambiar",items:["La pérdida, el diagnóstico o el hecho del pasado","Las decisiones de otras personas","Mi postura ante ello sigue siendo mía"]},note:"Ilustración propia, basada en la idea de Frankl sobre la actitud ante el sufrimiento inevitable."},technique:{name:"La pregunta de la actitud",origin:"Viktor E. Frankl · Man’s Search for Meaning (1946)",steps:["Nombra la situación en una frase sencilla, sin suavizarla.","Escribe lo que sientes al respecto y deja que esos sentimientos estén ahí.","Comprueba con honestidad si alguna parte aún puede cambiarse, y planea primero un paso para esa parte.","Para la parte que no puede cambiar, pregúntate qué clase de persona quieres ser mientras la afrontas.","Elige una pequeña acción para hoy que encaje con esa respuesta."],evidence:"Esta secuencia es una forma propia de aplicar la idea de Frankl sobre la actitud ante el sufrimiento inevitable. Proviene de su experiencia clínica y personal y no se ha probado como ejercicio. No es un tratamiento para el duelo, el trauma ni la depresión.",sourceId:"meaning-frankl"},photo:{id:"1519681393784-d120267933ba",alt:"Estrellas sobre montañas nevadas de noche"}},{id:"meaning-5",title:"Imagina la vida a la que apuntas",minutes:10,goal:"Usa el ejercicio del mejor yo posible para imaginar un futuro guiado por tus valores y conviértelo en un primer paso.",reading:["El ejercicio del mejor yo posible fue desarrollado por la psicóloga Laura King. Te imaginas en algún momento del futuro, después de que las cosas han salido tan bien como razonablemente podrían porque trabajaste duro por lo que te importa. Luego escribes sobre ese futuro durante varios minutos, con tanto detalle concreto como puedas. El objetivo no es predecir el futuro ni hacer que exista a fuerza de desearlo. Es imaginar cómo sería vivir según tus valores. Cuando puedes ver cómo podría ser una vida vivida en cierta dirección, se hace más fácil dar el primer paso hacia ella.","Este es uno de los ejercicios de psicología positiva mejor estudiados. Un metaanálisis de 2019 reunió 29 estudios con 2,909 participantes. En comparación con las condiciones de control, el ejercicio mejoró el optimismo, las emociones positivas y el bienestar, y redujo las emociones negativas y los síntomas depresivos. Los efectos fueron de pequeños a medianos, y el efecto sobre la depresión fue pequeño. Es un resultado útil, sin exageraciones: un breve ejercicio de escritura puede cambiar un poco cómo te sientes ante el futuro. No hace que ese futuro ocurra por sí solo. Eso sigue dependiendo de lo que hagas después."],deeper:[{heading:"Cómo hacer útil la imagen",paragraphs:["Imaginar el futuro con detalle ayuda más cuando se conecta con el presente. Después de escribir, conviene nombrar el valor que pone en práctica tu mejor yo posible, el principal obstáculo que podría interponerse y un plan para ese obstáculo.","Esa segunda mitad tiene su propia evidencia. Un metaanálisis de 21 estudios con 15,907 participantes encontró que contrastar una meta con el obstáculo real y hacer un plan del tipo “si… entonces…” tenía un efecto medio de pequeño a mediano para alcanzar las metas."],visual:{kind:"table",title:"De la imagen al plan",columns:["Paso","Pregunta","Ejemplo"],rows:[["Imagen","¿Cómo es mi mejor futuro posible?","Dirijo un estudio de diseño pequeño y tranquilo."],["Valor","¿Qué valor pongo en práctica?","Hacer cosas claras y agradables de usar."],["Obstáculo","¿Qué hay en mí que podría interponerse?","Evito mostrar mi trabajo."],["Plan","Si eso pasa, ¿qué haré entonces?","Si dudo, entonces envío una pieza a una persona."]],note:"Ejemplo propio que combina el ejercicio del mejor yo posible con la reflexión sobre la meta, el obstáculo y el plan."}},{heading:"Lo que dice la investigación",paragraphs:["El mayor efecto del metaanálisis fue sobre las emociones positivas, y el menor, sobre los síntomas depresivos. La frecuencia y el tiempo dedicado a escribir variaban entre los estudios, y la mayoría midió cambios a lo largo de días o semanas, no de años.","Así que una conclusión prudente es esta: el ejercicio eleva de forma fiable el ánimo y la esperanza un poco a corto plazo. Vincularlo con tus valores y con un primer paso es un añadido propio de este curso, pensado para convertir ese impulso en acción."]}],example:{title:"Jonah, 38 años, enfermero",text:"Jonah llevaba años sintiéndose estancado en los turnos de noche. En un día libre puso un temporizador de quince minutos y escribió sobre sí mismo dentro de cinco años, con las cosas saliendo tan bien como razonablemente podían. Para su sorpresa, la imagen no giraba en torno al dinero. Giraba en torno a enseñar: dirigir sesiones de formación para enfermeros nuevos, con calma y preparado. Al releerla, nombró el valor, “ayudar a otros a ganar confianza”, y el obstáculo, su miedo a hablar frente a grupos. Escribió un plan de “si… entonces…”: si surge la oportunidad de presentar, entonces diré que sí antes de poder convencerme de lo contrario. A la semana siguiente se ofreció a dirigir una sesión de diez minutos en la reunión del servicio."},practice:["Pon un temporizador de 15 minutos y escribe sobre tu vida dentro de unos años, después de que las cosas hayan salido tan bien como razonablemente podrían porque trabajaste por ellas.","Subraya el valor que pone en práctica tu mejor yo posible y nombra un obstáculo interno que podría interponerse.","Escribe un plan de “si… entonces…” para ese obstáculo y un pequeño paso que puedas dar esta semana."],reflection:"¿Qué valor ocupa el centro del futuro que imaginaste?",question:"¿Qué encontró el metaanálisis de 2019 sobre el ejercicio del mejor yo posible?",options:["Que garantiza que el futuro imaginado ocurrirá.","Mejoras de pequeñas a medianas en optimismo, emociones positivas y bienestar, con un efecto pequeño sobre los síntomas depresivos.","Que no tiene efecto en nada de lo medido."],correct:1,feedback:"En 29 estudios, el ejercicio produjo mejoras de pequeñas a medianas, mayores en las emociones positivas y menores en los síntomas depresivos. Cambia cómo te sientes ante el futuro, no el futuro en sí.",takeaway:"Imagina adónde podrían llevarte tus valores y luego da el primer paso.",sources:["meaning-carrillo","meaning-best-possible-self","mcii"],visual:{kind:"bars",title:"Ejercicio del mejor yo posible frente a condiciones de control",bars:[{label:"Emociones positivas",value:.511,display:"d = 0.511"},{label:"Optimismo",value:.334,display:"d = 0.334"},{label:"Bienestar",value:.325,display:"d = 0.325"},{label:"Menos emociones negativas",value:.192,display:"d = 0.192"},{label:"Menos síntomas depresivos",value:.115,display:"d = 0.115"}],note:"Tamaños del efecto estandarizados de un metaanálisis de 29 estudios con 2,909 participantes (Carrillo et al., 2019). Resultados sobre todo a corto plazo; no es una prueba de este curso.",sourceId:"meaning-carrillo"},technique:{name:"Mejor yo posible",origin:"Laura A. King · Best Possible Self writing (2001)",steps:["Elige un punto del futuro, como dentro de cinco años.","Imagina que todo ha salido tan bien como razonablemente podría, porque trabajaste duro y te mantuviste fiel a lo que te importa.","Escribe sobre ese futuro de forma continua durante unos 15 minutos, con detalles concretos: dónde estás, qué haces, quién está contigo.","No te preocupes por la ortografía ni por el estilo; sigue escribiendo.","Si quieres, repite el ejercicio en otros días y observa qué se mantiene igual."],evidence:"Un metaanálisis de 29 estudios encontró mejoras de pequeñas a medianas a corto plazo en optimismo, emociones positivas y bienestar, con un efecto pequeño sobre los síntomas depresivos. La duración y la frecuencia con que las personas escribían variaron entre estudios.",sourceId:"meaning-best-possible-self"},photo:{id:"1501785888041-af3ef285b470",alt:"Un lago en calma rodeado de montañas"}},{id:"meaning-6",title:"Una decisión al día basada en tus valores",minutes:8,goal:"Convierte tus valores en una pequeña decisión concreta cada día y mantenla en el tiempo.",reading:["Los valores solo cambian una vida cuando se reflejan en lo que haces. La ACT lo llama acción comprometida: construir formas cada vez más constantes de actuar según tus valores, empezando por pasos que de verdad puedas dar. Los pasos pueden ser diminutos. Ser cariñoso puede significar enviar un mensaje. Ser curioso puede significar leer cinco páginas. Cuidar la salud puede significar acostarte veinte minutos antes. Lo que los convierte en acción comprometida es que los eliges a propósito, por la dirección hacia la que apuntan, y que vuelves a ellos cuando te desvías.","Esta es la idea detrás de tomar una decisión al día. Cada mañana, o la noche anterior, te haces una pregunta: ¿qué pequeña cosa puedo hacer hoy que me acerque a un valor que me importa? Luego decides cuándo y dónde la harás. Los planes de “si… entonces…” ayudan aquí: un metaanálisis de 94 pruebas encontró que decidir de antemano cuándo, dónde y cómo actuar tenía un efecto de mediano a grande para alcanzar las metas. Algunos días fallarás. La investigación sobre los hábitos sugiere que un día sin practicar no deshace el proceso."],deeper:[{heading:"Por qué funciona lo pequeño",paragraphs:["Los grandes compromisos hechos en un arranque de inspiración suelen derrumbarse el primer día difícil. Los pasos pequeños y específicos son más fáciles de empezar y de repetir, y la repetición en el mismo contexto es como las acciones se vuelven automáticas poco a poco. Un estudio que siguió a 96 personas durante 12 semanas encontró que el tiempo que esto tomaba variaba mucho de una persona a otra, así que no hay un número mágico de días.","Llevar un registro sencillo también ayuda. Un metaanálisis de 138 estudios encontró que seguir tu progreso mejoraba las probabilidades de alcanzar las metas, especialmente cuando el progreso se anotaba por escrito."],visual:{kind:"table",title:"Del valor a la decisión de hoy",columns:["Valor","La decisión de hoy","Plan de si… entonces…"],rows:[["Estar presente como padre","El teléfono en un cajón durante la cena","Si me siento a comer, entonces el teléfono va al cajón."],["Cuidar mi cuerpo","Una caminata de 15 minutos","Si termino de almorzar, entonces doy una vuelta a la manzana."],["Ser un amigo leal","Escribirle a un amigo","Si subo al autobús de regreso a casa, entonces le escribo a Ana."],["Aprender y crecer","Leer cinco páginas","Si me meto en la cama, entonces leo antes de cualquier pantalla."]],note:"Ejemplos propios de cómo vincular valores con planes de si… entonces…."}},{heading:"Errores comunes",paragraphs:["El primer error es elegir una decisión que en realidad es una meta disfrazada, como “ponerme en forma”. Elige algo que puedas terminar hoy. El segundo es tratar un día fallido como prueba de que en realidad no tienes ese valor. Un valor es una dirección; puedes volver a girar hacia él en cualquier momento.","El tercero es elegir solo decisiones que resultan cómodas. La acción comprometida a veces significa hacer algo que despierta nerviosismo o dudas, porque importa. Puedes actuar aunque esos sentimientos sigan ahí."]}],example:{title:"Sofía, 45 años, administradora de oficina",text:"Sofía terminó este curso con tres valores: tratar con cariño a su familia, cuidar su cuerpo y hacer un trabajo honesto. Cada noche escribía una decisión para el día siguiente en una nota adhesiva junto a la tetera. El lunes fue “preguntarle a Leo por su partido y escucharlo”. El martes fue “caminar hasta la estación en vez de tomar el autobús”. El miércoles se olvidó por completo, sintió que la vieja voz la llamaba inútil, y aun así escribió la nota del jueves. Al final del mes había cumplido más o menos tres de cada cuatro. Su vida no había cambiado de forma radical, pero se sentía más parecida a la persona que había descrito en sus valores."},practice:["Elige un valor de tu lista y escribe una decisión que puedas terminar hoy y que apunte en esa dirección.","Conviértela en un plan de “si… entonces…” diciendo exactamente cuándo y dónde la harás.","Esta noche, marca si la cumpliste y escribe la decisión de mañana antes de dormir."],reflection:"¿Qué pequeña cosa podrías hacer hoy que haría la persona que quieres ser?",question:"¿Qué decisión diaria encaja mejor con la idea de acción comprometida?",options:["Prometerte que serás una persona completamente distinta a partir del lunes.","Caminar 15 minutos después de comer hoy, porque valoras cuidar tu cuerpo.","Esperar a sentirte motivado antes de hacer nada."],correct:1,feedback:"La acción comprometida es un paso concreto y posible, elegido por un valor. No requiere una gran transformación ni esperar el sentimiento adecuado.",takeaway:"Una pequeña decisión al día en la dirección que eliges va dando forma a tu vida.",sources:["meaning-act-values","if-then-plans","habits","monitoring"],visual:{kind:"cycle",title:"El ciclo diario de los valores",center:"Tu dirección",nodes:[{label:"Valor",text:"Elige un valor que te importe hoy."},{label:"Decide",text:"Elige una pequeña acción y cuándo la harás."},{label:"Actúa",text:"Hazla, aunque sientas dudas o cansancio."},{label:"Observa",text:"Anota lo que pasó, sin juzgarte."},{label:"Ajusta",text:"Haz el paso de mañana más fácil, más difícil o distinto."}],note:"Ciclo propio, basado en la acción comprometida de la ACT, los planes de si… entonces… y el seguimiento del progreso."},technique:{name:"Paso de acción comprometida",origin:"Terapia de aceptación y compromiso · acción comprometida, según la descripción de la Association for Contextual Behavioral Science",steps:["Elige un valor y un área de la vida donde quieras actuar según él.","Fija una meta pequeña y concreta que sirva a ese valor y se pueda cumplir hoy o esta semana.","Nombra las barreras internas que esperas, como la duda, el aburrimiento o el miedo.","Decide cómo actuarás mientras esos sentimientos estén presentes, en lugar de esperar a que se vayan.","Da el paso y luego elige el siguiente, haciendo que tus valores se reflejen cada vez más en lo que haces."],evidence:"La acción comprometida es uno de los seis procesos centrales de la ACT, y la parte de planificación se apoya en herramientas bien estudiadas, como los planes de si… entonces…. Esta secuencia simplificada no se ha probado por sí sola.",sourceId:"meaning-act-values"},photo:{id:"1472214103451-9374bd1c798e",alt:"Un prado verde con árboles bajo una luz suave"}}]},E=Object.freeze(Object.defineProperty({__proto__:null,COURSE:j,SOURCES:f},Symbol.toStringTag,{value:"Module"})),z=[{id:"optimism-maier-seligman",title:"Maier y Seligman · 2016 · La indefensión aprendida a los cincuenta años: aportes de la neurociencia (Psychological Review)",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"La revisión concluye que la teoría original de 1967 entendió el mecanismo al revés. La pasividad tras una descarga prolongada e incontrolable es una respuesta espontánea, no aprendida (mediada por el núcleo dorsal del rafe). Lo que los animales aprenden es el control: la corteza prefrontal medial detecta el control y entonces inhibe esa respuesta espontánea. Los autores especulan que esto tiene implicaciones para el tratamiento de la depresión.",limitation:"Se basa sobre todo en investigación con animales; cómo se aplica a personas que enfrentan contratiempos cotidianos es una especulación de los autores, no algo que esta revisión haya probado. Se leyó el resumen (vía Europe PMC)."},{id:"optimism-sweeney",title:"Sweeney, Anderson y Bailey · 1986 · Estilo atribucional en la depresión: una revisión metaanalítica (Journal of Personality and Social Psychology)",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"En 104 estudios con casi 15,000 participantes, explicar los sucesos negativos con causas internas, estables y globales se asoció de forma fiable con las puntuaciones de depresión. Explicar los sucesos positivos con causas externas, inestables y específicas también se asoció con la depresión, pero más débilmente. Los patrones se mantuvieron en muestras de estudiantes y psiquiátricas y con sucesos reales e hipotéticos.",limitation:"Es correlacional: muestra una asociación, no que el estilo explicativo cause la depresión. Es una revisión antigua. Se leyó el resumen (vía Europe PMC)."},{id:"optimism-malouff",title:"Malouff y Schutte · 2017 · ¿Pueden las intervenciones psicológicas aumentar el optimismo? Un metaanálisis (Journal of Positive Psychology)",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"29 ensayos controlados aleatorizados con 3,319 participantes: las intervenciones aumentaron el optimismo con un efecto promedio de g = 0.41. Los efectos fueron mayores con el ejercicio del mejor yo posible, la aplicación presencial, los grupos de control activos, la evaluación dentro del primer día tras la intervención y los análisis de quienes completaron el programa (en lugar de por intención de tratar).",limitation:"Los efectos mayores en las medidas de corto plazo y en los análisis de quienes completaron el programa sugieren que el cambio duradero es menos seguro. Se leyó el resumen (repositorio de la Universidad de Nueva Inglaterra)."},{id:"optimism-rozanski",title:"Rozanski et al. · 2019 · Asociación del optimismo con los eventos cardiovasculares y la mortalidad por todas las causas (JAMA Network Open)",url:"https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2752100",type:"research",finding:"Metaanálisis de 15 estudios con 229,391 participantes y un seguimiento medio de 13.8 años. Un mayor optimismo se asoció con un menor riesgo de eventos cardiovasculares (riesgo relativo combinado 0.65, IC del 95% 0.51–0.78; 10 estudios) y de muerte por cualquier causa (0.86, 0.80–0.92; 9 estudios).",limitation:"Todos los estudios incluidos eran observacionales, con mucha variación entre ellos, distintas medidas del optimismo y distintos ajustes en los análisis. Muestra una asociación, no que el optimismo cause una mejor salud ni que aumentarlo reduzca el riesgo. Se leyeron los resultados clave y las limitaciones."},{id:"optimism-prp-meta",title:"Brunwasser, Gillham y Kim · 2009 · Una revisión metaanalítica del efecto del Programa de Resiliencia de Penn sobre los síntomas depresivos (Journal of Consulting and Clinical Psychology)",url:"https://ppc.sas.upenn.edu/sites/default/files/prpmetaanalyticreview.pdf",type:"research",finding:"17 evaluaciones controladas con 2,498 jóvenes de 8 a 18 años. En comparación con ninguna intervención, los participantes informaron menos síntomas depresivos después del programa (d = 0.11), a los 6–8 meses (d = 0.21) y a los 12 meses (d = 0.20). En comparación con condiciones de control activas no hubo diferencia significativa, y el efecto sobre los diagnósticos de depresión no fue significativo.",limitation:"Efectos pequeños en jóvenes que siguen un programa grupal estructurado; no evalúa a adultos que usan por su cuenta las habilidades ABC. Se leyó el PDF alojado por los autores (resumen y secciones de síntesis)."},{id:"optimism-penn-prp",title:"Centro de Psicología Positiva, Universidad de Pensilvania · Resiliencia en niños (Programa de Resiliencia de Penn)",url:"https://ppc.sas.upenn.edu/research/resilience-children",type:"guidance",finding:"El Programa de Resiliencia de Penn se basa en el modelo ABC de Ellis: los estudiantes aprenden a detectar pensamientos inexactos, comprobar si se ajustan a los hechos y cuestionar las creencias negativas considerando otras interpretaciones, y también trabajan la asertividad, la resolución de problemas y la relajación. Se imparte en 12 sesiones de noventa minutos o en 18–24 sesiones de sesenta minutos. La página cita unos 20 estudios controlados y reconoce resultados que no siempre coinciden.",limitation:"Escrito por los desarrolladores del programa. El metaanálisis independiente encontró efectos pequeños y ninguna ventaja sobre otros programas activos."},{id:"optimism-hofmann",title:"Hofmann et al. · 2012 · La eficacia de la terapia cognitivo-conductual: una revisión de metaanálisis (Cognitive Therapy and Research)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3584580/",type:"research",finding:"La revisión abarcó 269 metaanálisis de TCC. El respaldo más sólido fue para la TCC en los trastornos de ansiedad, los trastornos somatomorfos, la bulimia, los problemas de control de la ira y el estrés general. De 11 revisiones que comparaban tasas de respuesta, la TCC tuvo tasas de respuesta más altas que las condiciones de comparación en 7 y más bajas en 1.",limitation:"Trata de la TCC impartida como terapia, no de autoayuda en una aplicación. Los autores señalan que hay pocos estudios de alta calidad para algunas afecciones y que no hay metaanálisis para grupos como las minorías étnicas o las personas con bajos ingresos. Se leyó un resumen del texto completo."},{id:"optimism-smernoff",title:"Smernoff, Mitnik, Kolodner y Lev-ari · 2015 · Los efectos de la meditación “The Work” (Byron Katie) sobre los síntomas psicológicos y la calidad de vida: un estudio clínico piloto (EXPLORE)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1550830714002067",type:"research",finding:"197 personas de una muestra no clínica siguieron un curso de nueve días de The Work. Las puntuaciones de depresión, ansiedad, felicidad y calidad de vida mejoraron de forma significativa (todas p < .001) después del curso y a los seis meses. 164 completaron las medidas posteriores al curso y 102 el seguimiento de seis meses.",limitation:"Es un estudio piloto de un solo grupo, sin grupo de control y con muchos abandonos; los autores piden ensayos aleatorizados. Se leyó el resumen."},{id:"optimism-seligman-exercises",title:"Seligman, Steen, Park y Peterson · 2005 · Avances de la psicología positiva: validación empírica de intervenciones (American Psychologist)",url:"https://greatergood.berkeley.edu/images/uploads/Seligman-PosPsychProgress.pdf",type:"research",finding:"Estudio en línea, aleatorizado y con placebo: 577 adultos asignados al azar, 411 completaron todos los seguimientos. Todos los grupos, incluido el placebo, se sintieron mejor justo después del ejercicio de una semana. Quienes escribieron tres cosas que salieron bien cada día y por qué, durante una semana, fueron más felices y estuvieron menos deprimidos que al inicio a partir del mes, y se mantuvieron así a los tres y seis meses; usar las fortalezas personales de una manera nueva mostró un patrón similar. Quienes siguieron practicando más allá de la semana fueron quienes siguieron beneficiándose.",limitation:"Voluntarios que se ofrecieron por iniciativa propia, en su mayoría con estudios superiores, blancos y con depresión leve, que querían ser más felices. Réplicas posteriores encontraron efectos menores o menos específicos. Se leyó el texto completo (copia alojada por el Greater Good Science Center)."},{id:"optimism-mongrain",title:"Mongrain y Anselmo-Matthews · 2012 · ¿Funcionan los ejercicios de psicología positiva? Una réplica de Seligman et al. (2005) (Journal of Clinical Psychology)",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"Con el método original, un control mejorado y un “placebo positivo” añadido, tres cosas buenas y usar las fortalezas personales produjeron aumentos duraderos de la felicidad, pero también lo hizo el placebo positivo. Los ejercicios no superaron a la condición de control en los cambios de la depresión.",limitation:"Solo se leyó el resumen (vía Europe PMC); no se revisaron los detalles de la muestra. Los autores sugieren que el beneficio puede venir de un efecto general de pensar en información positiva y relevante para uno mismo."},{id:"optimism-bolier",title:"Bolier et al. · 2013 · Intervenciones de psicología positiva: un metaanálisis de estudios controlados aleatorizados (BMC Public Health)",url:"https://link.springer.com/article/10.1186/1471-2458-13-119",type:"research",finding:"39 estudios con 6,139 participantes. Justo después de los programas: bienestar subjetivo d = 0.34, bienestar psicológico d = 0.20, depresión d = 0.23. A los 3–6 meses: 0.22, 0.16 y 0.17, y el efecto sobre la depresión ya no era significativo.",limitation:"Ninguno de los estudios cumplió todos los criterios de calidad (20 se calificaron como de baja calidad) y hubo indicios de sesgo de publicación. Combina muchos ejercicios distintos, no solo tres cosas buenas. Se leyeron el resumen y los resultados."},{id:"optimism-wood",title:"Wood, Perunovic y Lee · 2009 · Autoafirmaciones positivas: poder para unos, peligro para otros (Psychological Science)",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Una encuesta mostró que las personas suelen usar las afirmaciones positivas sobre uno mismo y confiar en ellas. En dos experimentos, las personas con baja autoestima que repitieron una afirmación sobre ser una persona digna de cariño acabaron con peor ánimo que los controles, mientras que las de alta autoestima se sintieron solo un poco mejor.",limitation:"Experimentos breves que miden el estado de ánimo en el momento; solo se leyó el resumen. No demuestra que toda forma de pensamiento positivo sea dañina."},{id:"optimism-nhs-cbt",title:"NHS · Terapia cognitivo-conductual (TCC)",url:"https://www.nhs.uk/mental-health/talking-therapies-medicine-treatments/talking-therapies-and-counselling/cognitive-behavioural-therapy-cbt/overview/",type:"guidance",finding:"El NHS describe la TCC como una terapia psicológica en la que un terapeuta te ayuda a cambiar cómo piensas y actúas. Se usa para la depresión, los trastornos de ansiedad, el TEPT y otras afecciones, por lo general a lo largo de 5 a 15 sesiones; si los síntomas no mejoran, pueden hacer falta más sesiones u otros tratamientos. La página enlaza con ayuda urgente en salud mental.",limitation:"Los detalles de acceso se refieren a Inglaterra. Los ejercicios de autoayuda de este curso no sustituyen la TCC con un terapeuta cualificado; en una emergencia, llama al número de emergencias de tu zona."},{id:"optimism-distortions",title:"Psychology Tools · Distorsiones cognitivas: estilos de pensamiento poco útiles (versión ampliada)",url:"https://www.psychologytools.com/resource/cognitive-distortions-unhelpful-thinking-styles-extended",type:"guidance",finding:"Describe 20 estilos de pensamiento poco útiles, entre ellos el pensamiento de todo o nada, la catastrofización, descartar lo positivo, el filtro mental, la lectura de la mente, la generalización excesiva, la personalización y los enunciados con “debería”, y remonta la idea al trabajo de Aaron Beck en los años sesenta, popularizado después por David Burns.",limitation:"Es un recurso para profesionales de la salud que resume categorías comunes; las categorías se superponen y no son un diagnóstico."},{id:"optimism-seligman-book",title:"Martin E. P. Seligman · Learned Optimism: How to Change Your Mind and Your Life (1990; edición Vintage, 2006)",url:"https://www.penguinrandomhouse.com/books/163862/learned-optimism-by-martin-e-p-seligman-phd/",type:"technique",finding:"Seligman describe el estilo explicativo (cuán permanentes, generalizadas y personales son tus explicaciones de los contratiempos) y enseña a sustituir los hábitos de rendirse por explicaciones más constructivas. Su método ABCDE amplía el modelo ABC de Albert Ellis con el cuestionamiento de creencias y la recuperación de energía.",limitation:"Se leyó la página de la editorial; los pasos del ABCDE y de las tres dimensiones se cuentan aquí a partir de descripciones secundarias y de las habilidades muy afines de los programas de resiliencia de Penn, no del texto del libro. Los programas basados en estas ideas muestran efectos pequeños; el libro no se ha probado como tratamiento y no reemplaza uno."},{id:"optimism-ellis",title:"Albert Ellis · Emotional disturbance and its treatment in a nutshell (Albert Ellis Institute)",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"technique",finding:"Ellis explica el modelo ABC que presentó por primera vez en 1956: los sucesos activadores (A) llevan a consecuencias emocionales y conductuales (C) a través de las creencias (B). Las exigencias rígidas (“debo” y “debería”) y las conclusiones catastróficas alimentan el malestar; cuestionarlas (D) mediante el pensamiento, las emociones y la conducta lleva a creencias nuevas, más flexibles y basadas en preferencias (E).",limitation:"Es una descripción de la terapia racional emotiva conductual hecha por su fundador, no una revisión de investigación; para este curso no se revisó la investigación sobre resultados de la TREC."},{id:"optimism-beck-thought-record",title:"Judith S. Beck · Hoja de registro de pensamientos, de Cognitive Behavior Therapy: Basics and Beyond, 3.ª edición (Beck Institute, 2020)",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"technique",finding:"La hoja tiene columnas para la fecha y la hora, la situación, los pensamientos automáticos con una valoración de cuánto se creen (0–100%), las emociones con su intensidad, la distorsión cognitiva, la respuesta adaptativa y el resultado. Sus preguntas ayudan a examinar las pruebas a favor y en contra del pensamiento, otras explicaciones, los peores, mejores y más realistas desenlaces, lo que le dirías a un amigo y el efecto de mantener o cambiar el pensamiento.",limitation:"Es una hoja de trabajo clínico diseñada para usarse en TCC. Usada por sí sola es autoayuda, y su uso sin acompañamiento está menos estudiado que la TCC dirigida por un terapeuta."},{id:"optimism-the-work",title:"Byron Katie · Do The Work: instrucciones (thework.com)",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Las instrucciones de Katie: escribe juicios estresantes sobre una persona o situación en frases cortas y sencillas; luego hazle cuatro preguntas a cada uno (si es verdad, si puedes estar absolutamente seguro, cómo reaccionas cuando lo crees, quién serías sin él); después da la vuelta al pensamiento (hacia ti, hacia la otra persona, hacia lo opuesto) y encuentra al menos tres ejemplos reales de cada inversión.",limitation:"Son las instrucciones de la propia autora; la base de investigación se limita a estudios iniciales y sin control."},{id:"optimism-mrt",title:"Reivich, Seligman y McBride · 2011 · Formación de instructores en resiliencia en el Ejército de EE. UU. (American Psychologist)",url:"https://ppc.sas.upenn.edu/sites/default/files/mrtinarmyjan2011.pdf",type:"technique",finding:"Describe un curso de resiliencia para sargentos del Ejército adaptado del Programa de Resiliencia de Penn: el modelo ABC y el estilo explicativo, las trampas del pensamiento (como generalizar en exceso, sacar conclusiones precipitadas y un estilo centrado en “yo soy el culpable”), las creencias más profundas tipo “iceberg”, ponerlo en perspectiva (peor, mejor y más probable desenlace, y luego un plan) y buscar lo bueno, un registro diario de cosas buenas.",limitation:"Es la descripción de un programa. En el momento de la publicación solo se informó la opinión inmediata de los participantes y las evaluaciones controladas seguían en curso. Se leyó el PDF alojado por los autores."},{id:"optimism-ggia-three-good-things",title:"Greater Good in Action (UC Berkeley) · Tres cosas buenas",url:"https://ggia.berkeley.edu/practice/three-good-things",type:"technique",finding:"Instrucciones: dedica unos diez minutos al día, durante al menos una semana, a escribir tres cosas que salieron bien, con detalles, cómo te hicieron sentir y qué las causó. La página cita el estudio de Seligman de 2005 y estudios posteriores en varios países que informan de mejor bienestar y menos pesimismo, depresión o ansiedad.",limitation:"Es una guía de práctica universitaria que resume estudios favorables y dice que hace falta más investigación entre culturas. Las réplicas sugieren que los efectos son pequeños y no siempre específicos de este ejercicio."}],x={id:"optimism",title:"¿Siempre esperas lo peor? Cómo recuperar la esperanza tras un revés",subtitle:"6 lecciones de 8 a 11 minutos. Revisa un contratiempo y busca otras formas de interpretarlo.",description:"Los contratiempos duelen, y la historia que te cuentas sobre ellos influye en cuánto dura ese dolor. Aprende a reconocer esa historia, ponerla a prueba y sustituirla por otra más amable y más ajustada a los hechos.",scope:"Para adultos que tienden a rendirse, culparse o esperar lo peor después de los contratiempos. El curso se apoya en el optimismo aprendido de Martin Seligman, la terapia cognitivo-conductual (TCC) y The Work de Byron Katie. Es autoayuda, no un tratamiento para la depresión, la ansiedad ni ninguna otra afección, y no reemplaza la terapia ni la medicación. Si la desesperanza dura semanas, si el día a día se vuelve difícil de sobrellevar o si tienes pensamientos de hacerte daño, habla con un médico o un profesional de salud mental. En una emergencia, llama al número de emergencias de tu zona.",outcome:"Una idea clara de tu estilo explicativo, una rutina ABCDE breve que puedas usar en cualquier momento, un registro de pensamientos que sabes cómo completar, cuatro preguntas para los pensamientos estresantes, una revisión del peor desenlace, el mejor y el más probable y un hábito nocturno de tres cosas buenas, además de una idea clara de lo que cada herramienta puede y no puede hacer.",photo:{id:"1465188162913-8fb5709d6d57",alt:"Una mujer caminando por un sendero en lo alto de una colina bajo la luz dorada del atardecer"},lessons:[{id:"optimism-1",title:"Indefensión aprendida, esperanza aprendida",minutes:8,goal:"Entiende por qué rendirse después de un contratiempo puede ser una reacción espontánea y normal. Practica cómo encontrar una parte de la situación en la que aún puedes influir.",reading:["En los años sesenta, Martin Seligman y Steven Maier realizaron experimentos en los que animales recibían descargas de las que no podían escapar. Más tarde, cuando escapar se volvió fácil, muchos simplemente dejaron de intentarlo. Los investigadores lo llamaron indefensión aprendida: la idea de que la experiencia había enseñado a los animales que nada de lo que hicieran importaba. Se convirtió en uno de los hallazgos más conocidos de la psicología, y Seligman dedicó décadas a preguntarse cómo se manifestaba esto en las personas. ¿Por qué algunas personas se rinden después de un contratiempo mientras otras siguen adelante?","Cincuenta años después, Maier y Seligman revisaron el trabajo con las herramientas de la neurociencia y concluyeron que la teoría original explicaba el mecanismo al revés. La pasividad tras un estrés prolongado que no se puede controlar parece ser la reacción espontánea, no aprendida, del cerebro. Lo que se aprende es el control: cuando una región de la parte frontal del cerebro detecta que lo que haces puede cambiar algo, atenúa esa respuesta espontánea. Es investigación con animales, así que hay que tener cuidado al aplicarla directamente a las personas. Aun así, ofrece un marco esperanzador para este curso. Quedarte paralizado tras un golpe no es un defecto de carácter, y notar en qué puedes influir es una habilidad que puedes practicar."],deeper:[{heading:"Lo que dice la investigación sobre el optimismo",paragraphs:["El optimismo, entendido en sentido amplio como la expectativa de que las cosas saldrán razonablemente bien, se asocia con una mejor salud. Un metaanálisis de 2019 reunió 15 estudios a largo plazo con unas 229,000 personas. Las personas más optimistas tuvieron un menor riesgo de problemas del corazón y de la circulación y de muerte por cualquier causa que las menos optimistas. Eran estudios observacionales: quizá los optimistas también hacen más ejercicio, fuman menos o tienen más recursos. Así que es una asociación, no una prueba de que el optimismo por sí mismo proteja tu salud.","¿Se puede aprender el optimismo? Un metaanálisis de 29 ensayos aleatorizados con 3,319 personas encontró que los ejercicios psicológicos aumentaron el optimismo en una cantidad moderada de media. Los efectos fueron mayores cuando se midieron justo después del ejercicio, así que no está tan claro cuánto dura el cambio."]},{heading:"En la vida diaria",paragraphs:["La indefensión no siempre es evidente. Puede aparecer como un “¿para qué?”, como el gesto de cerrar el ordenador o como una sensación de pesadez. El paso que propone este curso es pequeño: antes de decidir que no se puede hacer nada, encuentra una parte de la situación que responda a tu acción. Un mensaje que puedes enviar, una pregunta que puedes hacer, diez minutos que puedes dedicar."],visual:{kind:"steps",title:"Del bloqueo al primer paso",steps:[{label:"Observa",text:"Reconoce el momento en que vas a rendirte: estoy a punto de dejar de intentarlo."},{label:"Separa",text:"Separa lo que escapa a tu control de aquello en lo que puedes influir, aunque sea un poco."},{label:"Elige",text:"Elige una acción pequeña que dependa de ti."},{label:"Registra",text:"Después, anota qué cambió tu acción, por poco que sea."}]}},{heading:"Errores comunes",paragraphs:["El optimismo aprendido no es fingir que un contratiempo no importa, ni culparte por sentirte decaído. Algunas situaciones de verdad escapan a tu control, y verlo con exactitud forma parte del pensamiento realista. La meta es la flexibilidad: ver qué partes puedes cambiar sin negar las que no."]}],example:{title:"Daniel, 34 años, supervisor de almacén",text:"Daniel se postuló a un ascenso interno y se enteró de que se lo dieron a otra persona. Para la hora del almuerzo ya había decidido que no tenía sentido volver a intentarlo, y en silencio planeaba dejar de ofrecerse para proyectos extra. De camino a casa notó el impulso conocido de rendirse y probó el ejercicio. Fuera de su control: la decisión, que ya estaba tomada. Dentro de su control: preguntarle a su jefa cómo podía prepararse mejor la próxima vez. Esa tarde envió un correo de dos líneas. La respuesta señaló una habilidad, el software de programación de turnos, que podía aprender en más o menos un mes. Esa semana todavía se sintió decepcionado. Pero el ascenso ya no le parecía un veredicto sobre todo su futuro, y reservó la primera sesión de formación."},practice:["Recuerda un contratiempo reciente y escribe una frase neutral que describa lo que pasó.","Dibuja dos columnas y anota qué estaba fuera de tu control y qué estaba, aunque fuera un poco, dentro de él.","Elige una acción pequeña de la segunda columna y hazla, o ponla en tu calendario, dentro de las próximas 24 horas."],reflection:"¿En qué parte de tu vida has dejado de intentarlo porque alguna vez pareció inútil, y sigue siendo cierto hoy?",question:"Según la actualización de 2016 de Maier y Seligman, ¿qué es lo que realmente se aprende en los experimentos de indefensión?",options:["Que nada de lo que hagas importa: las malas experiencias enseñan indefensión.","Control: el cerebro aprende a detectar cuándo lo que haces puede cambiar algo, lo que atenúa una respuesta pasiva espontánea.","Optimismo: algunos animales nacen esperanzados y otros no."],correct:1,feedback:"En la visión actualizada, la pasividad bajo un estrés prolongado que no se puede controlar es la reacción espontánea. Lo que enseña la experiencia es que las acciones pueden importar. Por eso vale la pena practicar cómo encontrar y usar pequeñas oportunidades de influir.",takeaway:"La parálisis puede surgir de forma espontánea. Reconocer en qué puedes influir se aprende.",sources:["optimism-maier-seligman","optimism-rozanski","optimism-malouff","optimism-seligman-book"],visual:{kind:"compare",title:"Indefensión aprendida: la explicación antigua y la nueva",left:{label:"Teoría original (1967)",items:["Las descargas inevitables enseñan que nada de lo que hagas importa","La pasividad se aprende de la experiencia","La indefensión es la lección"]},right:{label:"Actualización de la neurociencia (2016)",items:["La pasividad es la respuesta espontánea ante un estrés prolongado que no se puede controlar","Detectar el control atenúa esa respuesta espontánea","El control es la lección"]},note:"Basado en estudios con animales revisados por Maier y Seligman (2016); cómo se traslada exactamente esto a las personas aún se está estudiando."},photo:{id:"1527580094867-0e719f119120",alt:"Un excursionista cruzando rocas grises a primera hora de la mañana, esperando el amanecer"}},{id:"optimism-2",title:"Tu estilo explicativo",minutes:9,goal:"Conoce las tres dimensiones con las que explicas lo que sale mal y reconoce tu estilo en un ejemplo real.",reading:["Poco después de los estudios con animales, los investigadores notaron que las personas se diferencian en cómo explican lo que sale mal. Seligman llamó a este hábito tu estilo explicativo, y tiene tres dimensiones. Permanencia: ¿esto durará para siempre (siempre lo arruino) o es temporal (esta semana estaba agotado)? Generalización: ¿lo estropea todo (no sirvo para nada) o solo un área (todavía no se me da bien la estadística)? Personalización: ¿tiene que ver solo contigo (soy tonto) o las circunstancias influyeron (las instrucciones no estaban claras y me apuré)? Un estilo pesimista recurre a explicaciones permanentes, generalizadas y personales.","Esto importa porque las explicaciones moldean lo que haces después. Si una causa es permanente y afecta a todo, volver a intentarlo parece inútil. Una revisión de 104 estudios con casi 15,000 personas encontró que explicar lo que sale mal con causas internas, estables y globales se vinculaba de forma fiable con más síntomas depresivos. Eso es una correlación, no una prueba de causa, y no significa que nunca debas asumir responsabilidad. La alternativa optimista no es “nunca es mi culpa”. Es una historia más precisa: qué pasó exactamente, qué parte fue temporal y qué parte puedes cambiar."],deeper:[{heading:"Cuando algo sale bien, el patrón se invierte",paragraphs:["El estilo explicativo también aparece cuando algo sale bien, pero de forma inversa. Las personas con un estilo pesimista suelen explicar lo que sale bien como algo temporal, limitado y debido a la suerte: el cliente simplemente estaba de buen humor. La misma revisión encontró que este patrón también se vinculaba con síntomas depresivos, aunque más débilmente que el patrón de lo que sale mal. Así que parte de la práctica consiste en dar valor a las buenas noticias, notando cuándo un éxito vino de tu esfuerzo o de una fortaleza que puedes volver a usar."],visual:{kind:"compare",title:"Un solo estilo pesimista, dos tipos de sucesos",left:{label:"Después de un suceso malo",items:["Esto siempre va a pasar (permanente)","Esto lo arruina todo (generalizado)","Todo es por mi culpa (personal)"]},right:{label:"Después de un suceso bueno",items:["Eso fue algo aislado (temporal)","Solo cuenta aquí (específico)","Tuve suerte, nada más (externo)"]},note:"El patrón pesimista se invierte según el tipo de suceso. Conocer ambas formas te ayuda a reconocerlo."}},{heading:"Errores comunes",paragraphs:["Cambiar la culpa por excusas. Pasar de “todo es culpa mía” a “todo es culpa de ellos” no es optimismo; es otra historia inexacta. Busca un reparto justo de las causas.","Tratar tu estilo como un defecto permanente más. El estilo explicativo es un hábito de pensamiento, no un veredicto fijo, y la investigación sobre el entrenamiento del optimismo sugiere que puede cambiar, al menos a corto plazo."]}],example:{title:"Aylin, 27 años, diseñadora gráfica",text:"La clienta de Aylin rechazó su primer borrador de logotipo en un correo corto. Su primer pensamiento fue que no era lo bastante creativa para esta profesión. Se detuvo y revisó las tres dimensiones. ¿Permanente? Era un borrador para una clienta, el primero que fallaba este año. ¿Generalizado? Su portafolio y dos clientes contentos decían lo contrario. ¿Personal? En parte: no había preguntado por las preferencias de color de la clienta. En parte no: el encargo tenía solo dos frases. Su nueva explicación fue que había pasado demasiado rápido por las preguntas iniciales ante un encargo poco claro. Eso le dijo qué hacer después. Reservó una llamada de quince minutos y hizo seis preguntas. El segundo borrador no fue perfecto, pero entró a la llamada como una diseñadora que corrige un borrador, no como una impostora esperando a que la descubran."},practice:["Anota una decepción reciente y tu primera explicación de ella, tal como pasó por tu cabeza.","Marca si esa explicación era permanente o temporal, generalizada o específica, y si te atribuyes toda la responsabilidad o reconoces también el papel de las circunstancias.","Reescríbela como una explicación precisa que sea temporal, específica y justa respecto a lo que te correspondía cambiar."],reflection:"Cuando algo te sale bien, ¿cómo lo explicas normalmente, y esa explicación te permite reconocer el éxito?",question:"¿Cuál de estas reescrituras de “reprobé el examen porque soy tonto” refleja un estilo explicativo más optimista?",options:["El profesor me tiene manía, así que nada de lo que haga importará nunca.","No pasa nada, los exámenes no importan de todos modos.","Empecé a estudiar demasiado tarde para este examen; la próxima vez voy a empezar dos semanas antes."],correct:2,feedback:"La tercera opción es temporal (este examen), específica (el momento de estudiar) y honesta sobre la parte que puedes cambiar. La primera cambia la culpa de sitio pero la mantiene permanente; la segunda descarta un problema real.",takeaway:"Haz tus explicaciones temporales, específicas y justas, y te darás algo que hacer después.",sources:["optimism-sweeney","optimism-seligman-book","optimism-malouff"],visual:{kind:"table",title:"Las tres dimensiones del estilo explicativo",columns:["Dimensión","Historia pesimista","Historia optimista"],rows:[["Permanencia","Siempre va a ser así.","Esta es una mala racha."],["Generalización","Esto lo arruina todo.","Esto afecta un área de mi vida."],["Personalización","Es totalmente culpa mía; yo soy el problema.","Yo tuve parte de responsabilidad, y las circunstancias también influyeron."]],note:"Según la descripción de Martin Seligman del estilo explicativo. La columna pesimista se vincula con síntomas depresivos en investigación correlacional."},technique:{name:"Revisión de las tres dimensiones",origin:"Martin Seligman · Learned Optimism (1990; Vintage edition 2006)",steps:["Anota la explicación exacta que pasó por tu cabeza después del contratiempo.","Pregúntate si la estás tratando como permanente y busca pruebas de que es temporal.","Pregúntate si estás dejando que se extienda a todo, y nombra la única área a la que de verdad afecta.","Pregúntate si te estás echando toda la culpa, o ninguna, y reparte las causas de forma justa.","Escribe una explicación nueva que sea temporal, específica y justa, y nombra un siguiente paso que sugiera."],evidence:"Un estilo explicativo pesimista se asocia de forma consistente con síntomas depresivos, y los ejercicios para desarrollar el optimismo muestran un efecto moderado de corto plazo sobre el optimismo. Esta revisión personal concreta no se ha probado por sí sola.",sourceId:"optimism-seligman-book"},photo:{id:"1509029032154-54ba8b3216d4",alt:"Un hombre con gafas mirando pensativo por una ventana"}},{id:"optimism-3",title:"ABCDE: cuestiona tus creencias con justicia",minutes:10,goal:"Analiza un contratiempo real: adversidad, creencia, consecuencia, cuestionamiento y energía recuperada.",reading:["La herramienta principal de Seligman para el optimismo aprendido se apoya en el modelo ABC que el psicólogo Albert Ellis presentó en los años cincuenta. A es la adversidad: lo que pasó, descrito como lo registraría una cámara. B es tu creencia: la historia que te contaste sobre ello. C es la consecuencia: lo que sentiste y lo que hiciste. La mayoría suponemos que A causa C directamente: el correo grosero me puso furioso. Ellis señaló que B está en medio. El mismo correo puede llevar a la furia, a la preocupación o a restarle importancia, según lo que creas que significa.","Seligman añadió dos pasos. D es el cuestionamiento: examinar la creencia como discutirías con un desconocido que dijera algo injusto sobre ti. Busca pruebas en su contra, otras causas posibles, una visión menos catastrófica de lo que significa, y pregunta si la creencia es útil aunque una parte sea cierta. E es la energía recuperada: observa cómo cambian tus emociones y tus acciones cuando la creencia pierde fuerza. La meta no es una creencia alegre sino una que se ajuste a los hechos. Cuando las pruebas sí respaldan una creencia dolorosa, la pregunta útil pasa a ser qué puedes hacer al respecto."],deeper:[{heading:"De dónde vino el ABC",paragraphs:["Albert Ellis presentó por primera vez su idea del ABC en 1956 y construyó en torno a ella la terapia racional emotiva conductual (TREC). Prestó especial atención a las exigencias rígidas, como la creencia de que debes tener éxito o de que los demás siempre deberían tratarte con justicia, y a las conclusiones catastróficas que siguen cuando no ocurre. Su alternativa era tener preferencias claras en lugar de exigencias absolutas: te gustaría mucho tener éxito, y puedes soportarlo si no lo tienes. El ABCDE de Seligman y la terapia cognitiva de Aaron Beck comparten esta idea central: las emociones siguen a las interpretaciones, y las interpretaciones se pueden examinar."]},{heading:"Cuatro formas de cuestionar una creencia",paragraphs:["Cuestionar una creencia funciona mejor si lo haces de forma concreta. Decirte que todo va a salir bien rara vez te convence cuando estás preocupado. Las pruebas y las alternativas concretas sí."],visual:{kind:"steps",title:"Cuatro formas de discutir con una creencia",steps:[{label:"Pruebas",text:"¿Qué hechos respaldan la creencia y qué hechos la contradicen?"},{label:"Alternativas",text:"¿Qué más pudo contribuir? Busca causas temporales, específicas y modificables."},{label:"Implicaciones",text:"Aunque la creencia sea en parte cierta, ¿qué significa de forma realista? ¿Es tan grave como se siente?"},{label:"Utilidad",text:"¿Te ayuda ahora aferrarte a esta creencia, o te serviría más centrarte en el siguiente paso?"}],note:"Nuestra propia redacción del paso de cuestionamiento tal como se describe comúnmente."}},{heading:"Qué dice la investigación",paragraphs:["El Programa de Resiliencia de Penn enseña a los jóvenes el modelo ABC, el cuestionamiento de creencias y la resolución de problemas a lo largo de doce o más sesiones grupales. Un metaanálisis de 17 estudios controlados con 2,498 jóvenes encontró reducciones pequeñas de los síntomas depresivos en comparación con ninguna intervención, que se mantuvieron al menos un año. En comparación con otros programas activos, sin embargo, no mostró una ventaja clara, y no redujo de forma significativa los diagnósticos reales de depresión. Incluso los desarrolladores del programa reconocen que los resultados varían entre estudios."],visual:{kind:"bars",title:"Programa de Resiliencia de Penn frente a ninguna intervención: síntomas depresivos",bars:[{label:"Justo después del programa",value:.11,display:"d = 0.11"},{label:"6–8 meses después",value:.21,display:"d = 0.21"},{label:"12 meses después",value:.2,display:"d = 0.20"}],note:"Tamaños del efecto estandarizados (d) de 17 estudios con 2,498 jóvenes de 8 a 18 años: efectos pequeños. Frente a programas de control activos no hubo diferencia significativa. No se estudió a adultos que usan el ABCDE por su cuenta.",sourceId:"optimism-prp-meta"}}],example:{title:"Priya, 41 años, enfermera",text:"La jefa de Priya la pasó a turnos de noche durante un mes sin preguntarle. A: se publicó el nuevo horario, con cuatro semanas de noches. B: no me valora, y me quedaré en las noches para siempre. C: rabia, una tarde sin dormir y una respuesta cortante redactada en el teléfono. Antes de enviarla, Priya abrió su cuaderno para la D. Pruebas: otras dos compañeras también habían sido cambiadas, y el horario decía cuatro semanas, no para siempre. Alternativas: la unidad tenía poco personal tras dos renuncias. Implicaciones: un mes duro, no una condena profesional. Utilidad: la rabia la empujaba hacia un correo del que se arrepentiría. E: su rabia bajó de nueve a cinco. Borró el borrador y pidió en cambio conservar su domingo libre de siempre. Su jefa aceptó."},practice:["Elige un contratiempo de esta semana y escribe la A como la registraría una cámara, sin interpretarlo.","Escribe la B exactamente como la pensaste y luego la C: lo que sentiste (con una intensidad de 0 a 10) y lo que hiciste o quisiste hacer.","Cuestiona la creencia con pruebas, alternativas, implicaciones y utilidad, y luego escribe la E: cómo cambiaron tu emoción y tu plan."],reflection:"¿Qué creencia aparece una y otra vez en tus ABC, y a quién te recuerda esa voz?",question:"En el modelo ABC, ¿qué se interpone entre un suceso y tu reacción emocional?",options:["Tu creencia sobre lo que significa el suceso.","El tamaño del propio suceso.","Tu personalidad, que no puede cambiar."],correct:0,feedback:"Ellis y Seligman sitúan la creencia (B) entre la adversidad (A) y la consecuencia (C). Los sucesos importan, pero el mismo suceso puede llevar a reacciones muy distintas según la historia que te cuentes sobre él.",takeaway:"Entre lo que pasó y cómo te sientes hay una historia, y las historias se pueden comprobar.",sources:["optimism-seligman-book","optimism-ellis","optimism-prp-meta","optimism-penn-prp"],visual:{kind:"cycle",title:"El ciclo ABC",nodes:[{label:"Adversidad",text:"Algo pasa: un rechazo, un error, un retraso."},{label:"Creencia",text:"Te lo explicas a ti mismo, a menudo en una fracción de segundo."},{label:"Consecuencia",text:"Las emociones y las acciones siguen a la creencia, no solo al suceso."},{label:"Siguiente situación",text:"Lo que haces moldea lo que pasa después, y el ciclo vuelve a empezar."}],center:"Interviene en la B",note:"Según el modelo ABC de Albert Ellis, que Martin Seligman amplió con el cuestionamiento de creencias y la recuperación de energía."},technique:{name:"ABCDE",origin:"Martin Seligman · Learned Optimism (1990; Vintage edition 2006)",steps:["Adversidad: describe el suceso con palabras neutrales y centradas en los hechos.","Creencia: anota los pensamientos que tuviste sobre él, palabra por palabra.","Consecuencia: anota tus emociones, su intensidad y lo que hiciste.","Cuestionamiento: examina la creencia usando pruebas, causas alternativas, implicaciones realistas y utilidad.","Energía recuperada: registra cómo cambiaron tus emociones, tu energía y tus planes después de cuestionar la creencia."],evidence:"Las habilidades basadas en el ABC forman parte del Programa de Resiliencia de Penn, que redujo ligeramente los síntomas depresivos en jóvenes en comparación con ninguna intervención, pero no en comparación con otros programas activos. El ABCDE usado por adultos por su cuenta tiene poca investigación directa.",sourceId:"optimism-seligman-book"},photo:{id:"1643148636630-0b0fb138fc74",alt:"Una persona escribiendo en un cuaderno con un bolígrafo"}},{id:"optimism-4",title:"Trampas del pensamiento y cómo registrarlas",minutes:11,goal:"Reconoce las trampas habituales del pensamiento y completa un registro de pensamientos, desde la situación hasta una respuesta equilibrada.",reading:["En los años sesenta, el psiquiatra Aaron Beck notó que sus pacientes con depresión tenían pensamientos rápidos y automáticos, sesgados de maneras predecibles. Llamó a estos patrones distorsiones cognitivas; hoy mucha gente los llama trampas del pensamiento. Entre las más comunes están el pensamiento de todo o nada (un error significa un fracaso total), la catastrofización (saltar al peor desenlace), la lectura de la mente (suponer que sabes lo que piensan los demás), la generalización excesiva (un suceso se convierte en regla) y el filtro mental (notar solo lo negativo). Todos caemos en estas trampas a veces. Son atajos mentales, no señales de que algo ande mal contigo.","El enfoque de Beck se convirtió en la terapia cognitivo-conductual (TCC), una de las terapias psicológicas más investigadas. Una revisión de 269 metaanálisis encontró el respaldo más sólido para la TCC en los trastornos de ansiedad, el estrés, los problemas de ira y varias otras afecciones. Una herramienta central de la TCC es el registro de pensamientos: una hoja estructurada en la que anotas la situación, el pensamiento automático y cuánto lo crees, tus emociones, la trampa que aparece, una respuesta equilibrada y el resultado. Ponerlo por escrito importa. Los pensamientos que dentro de tu cabeza se sienten como hechos suelen verse distintos en el papel."],deeper:[{heading:"Cómo escribir una respuesta equilibrada",paragraphs:["Una respuesta equilibrada no es un pensamiento positivo. Conserva las partes ciertas de la preocupación y añade lo que la preocupación dejó fuera. “Mi presentación fue un desastre” podría convertirse en: perdí el hilo dos veces, también respondí todas las preguntas, y dos personas me pidieron mis diapositivas.","Algunas preguntas útiles de la hoja del Beck Institute son: ¿qué pruebas hay a favor y en contra de este pensamiento?, ¿hay otra explicación?, ¿cuáles son el peor, el mejor y el más realista de los desenlaces?, y ¿qué le dirías a un amigo en la misma situación?"],visual:{kind:"steps",title:"Un registro de pensamientos, columna por columna",steps:[{label:"Situación",text:"Dónde estabas, qué pasó, cuándo."},{label:"Pensamiento automático",text:"El pensamiento, palabra por palabra, con cuánto lo crees (0–100%)."},{label:"Emoción",text:"Nombra cada emoción y valora su intensidad (0–100)."},{label:"Respuesta equilibrada",text:"Sopesa las pruebas y escribe una versión más justa y más completa."},{label:"Resultado",text:"Vuelve a valorar tu creencia y tus emociones, y anota lo que vas a hacer."}]}},{heading:"Cuando cuesta completar un registro de pensamientos",paragraphs:["Algunos días completar un registro de pensamientos parece discutir con una pared: la respuesta equilibrada tiene sentido, pero aún te cuesta creerla. Es algo común. Aun así, vuelve a valorar tu creencia; pasar del 90% al 70% es un avance real.","Si escribir sobre una situación te deja sintiéndote mucho peor, o si los mismos pensamientos dolorosos dominan la mayoría de tus días, es un buen momento para trabajar con un terapeuta de TCC cualificado en lugar de hacerlo solo. Las hojas de autoayuda son útiles, pero no sustituyen un tratamiento."]}],example:{title:"Marcus, 38 años, gerente de ventas",text:"Marcus notó que su jefa llevaba dos días sin responder a su informe semanal. Para el miércoles estaba convencido de que su empleo corría peligro. En su escritorio abrió una página en blanco y trazó columnas. Situación: sin respuesta al informe. Pensamiento automático: cree que mis números son malos y está planeando despedirme, lo creía al 80%. Emoción: ansiedad, siete sobre diez. Trampas: lectura de la mente y catastrofización. Pruebas en contra: la evaluación del mes pasado fue positiva, y ella había estado de viaje toda la semana. Respuesta equilibrada: no sé por qué no ha respondido; lo más probable es su viaje, y puedo preguntarle en la reunión del viernes. Resultado: la creencia bajó al 30%, la ansiedad a cuatro. El viernes ella comentó que casi no había abierto el correo en toda la semana."},practice:["Lee la tabla de trampas del pensamiento y elige las dos en las que caes con más frecuencia.","Toma un pensamiento que te alteró en los últimos días y escribe la situación, el pensamiento con un porcentaje de creencia, la emoción con una puntuación de intensidad y la trampa.","Anota qué pruebas hay a favor y en contra, y qué le dirías a un amigo. Escribe una respuesta equilibrada y vuelve a valorar tu creencia y tu emoción."],reflection:"¿En qué trampa del pensamiento dirían las personas que mejor te conocen que caes con más frecuencia?",question:"¿Cuál de estas es una respuesta equilibrada en el sentido de la TCC?",options:["Todo saldrá perfecto si simplemente lo creo.","Cometí un error en el informe, mi jefe también ha elogiado la mayor parte de mi trabajo este año, y puedo corregir este error.","Siempre lo arruino todo, así que no tiene sentido intentarlo."],correct:1,feedback:"Una respuesta equilibrada conserva lo que es cierto (hubo un error) y añade lo que el pensamiento ansioso dejó fuera (los elogios, la corrección). La primera opción ignora la realidad; la tercera es generalización excesiva.",takeaway:"No tienes que creer todos tus pensamientos; puedes ponerlos en papel y sopesarlos.",sources:["optimism-hofmann","optimism-beck-thought-record","optimism-distortions","optimism-mrt","optimism-ellis","optimism-nhs-cbt"],visual:{kind:"table",title:"Trampas comunes del pensamiento",columns:["Trampa","Cómo suena","Una pregunta para ponerla a prueba"],rows:[["Todo o nada","Si no es perfecto, es un fracaso.","¿Hay algún punto medio entre perfecto y fracaso?"],["Catastrofización","Esto va a ser un desastre.","¿Cuál es el desenlace más probable, no solo el peor?"],["Lectura de la mente","Piensan que no sirvo.","¿Qué sé realmente sobre lo que piensan?"],["Generalización excesiva","Esto siempre me pasa a mí.","¿De verdad siempre? ¿Cuándo no pasó?"],["Filtro mental","Todo el día fue malo.","¿Qué fue neutral o salió bien y estoy pasando por alto?"],["Personalización","Todo es por mi culpa.","¿Qué otras personas o circunstancias influyeron?"]],note:"Una selección de las distorsiones cognitivas descritas por primera vez por Aaron Beck y popularizadas después por David Burns; las preguntas de prueba son de redacción propia."},technique:{name:"Registro de pensamientos",origin:"Judith S. Beck · Cognitive Behavior Therapy: Basics and Beyond (3rd edition, 2020)",steps:["Escribe la situación: dónde estabas, qué pasó y cuándo.","Escribe el pensamiento automático y valora cuánto lo crees, de 0 a 100%.","Nombra tus emociones y valora cada una de 0 a 100.","Identifica la trampa del pensamiento, si encaja alguna.","Responde las preguntas: pruebas a favor y en contra, otras explicaciones, peor, mejor y más realista desenlace, y qué le dirías a un amigo.","Escribe una respuesta equilibrada y luego vuelve a valorar tu creencia y tus emociones."],evidence:"Los registros de pensamientos son una parte central de la TCC, que cuenta con un respaldo de investigación muy amplio, en especial para la ansiedad y los problemas relacionados con el estrés. Los registros autoguiados fuera de la terapia están menos estudiados, y usarlos por tu cuenta no sustituye un tratamiento.",sourceId:"optimism-beck-thought-record"},photo:{id:"1681396059172-7532b1ef8b47",alt:"Un diario abierto sobre una mesa bajo la suave luz de la mañana"}},{id:"optimism-5",title:"Cuatro preguntas para un pensamiento estresante",minutes:9,goal:"Prueba las cuatro preguntas y la inversión de Byron Katie con un pensamiento que sigue haciéndote daño.",reading:["Byron Katie, conferenciante y autora estadounidense, desarrolló un método al que llama The Work. En lugar de discutir con un pensamiento usando pruebas, te quedas con él y le haces cuatro preguntas. Primero, pregunta si el pensamiento es verdad. Segundo, pregunta si puedes estar absolutamente seguro de que es verdad. Tercero, nota cómo reaccionas, en tu cuerpo, tus emociones y tu conducta, cuando lo crees. Cuarto, imagina quién serías en la misma situación sin ese pensamiento. Escribes tus respuestas y le das tiempo a cada pregunta, sin apresurarte a dar la respuesta que crees correcta.","Luego viene la inversión: das la vuelta al pensamiento original y buscas ejemplos reales de la versión invertida. “Mi hermano debería escucharme” puede convertirse en “Yo debería escuchar a mi hermano”, “Yo debería escucharme a mí mismo” o “Mi hermano no debería escucharme”, quizá porque él nunca te pidió consejo. Para cada inversión buscas al menos tres ejemplos reales. The Work coincide en parte con la TCC, ya que ambas tratan los pensamientos como algo que se examina y no que se obedece, pero se apoya más en la curiosidad que en construir un contraargumento. Se ha investigado mucho menos, como verás más abajo."],deeper:[{heading:"En qué se diferencia de un registro de pensamientos",paragraphs:["Un registro de pensamientos reúne argumentos; The Work deja por un momento los argumentos a un lado. La tercera pregunta te pide notar lo que te cuesta el pensamiento, y la cuarta te invita a imaginar el momento sin él. Algunas personas descubren que un pensamiento pierde fuerza así incluso cuando todavía no pueden refutarlo. Otras prefieren la estructura de sopesar las pruebas. Puedes usar la herramienta que encaje con el pensamiento que tienes delante."],visual:{kind:"compare",title:"Registro de pensamientos y The Work: comparación",left:{label:"Registro de pensamientos de la TCC",items:["Sopesa las pruebas a favor y en contra","Nombra la trampa del pensamiento","Termina con una respuesta equilibrada","Respaldado por una amplia base de investigación"]},right:{label:"The Work",items:["Pregunta si puedes estar seguro","Nota cómo te afecta el pensamiento","Termina con inversiones y ejemplos","Respaldado por investigación inicial y limitada"]}}},{heading:"Qué dice la investigación",paragraphs:["El principal estudio publicado siguió a 197 personas en Israel durante un curso de nueve días de The Work. Las puntuaciones de depresión, ansiedad y calidad de vida mejoraron y seguían siendo mejores seis meses después. Pero no había grupo de control, los participantes no eran una muestra clínica y solo 102 de los 197 completaron el seguimiento de seis meses, así que quienes se beneficiaron pueden haber sido quienes se quedaron. Los propios autores calificaron los resultados de prometedores y pidieron ensayos aleatorizados. Trata The Work como una herramienta reflexiva interesante, no como un tratamiento basado en la evidencia."],visual:{kind:"bars",title:"Cuántas personas permanecieron en el principal estudio de The Work",bars:[{label:"Inicio del curso",value:197,display:"197"},{label:"Después del curso",value:164,display:"164"},{label:"Seis meses después",value:102,display:"102"}],note:"Participantes que completaron las evaluaciones en un estudio piloto sin control (Smernoff et al., 2015). Perder a cerca de la mitad de la muestra hace difícil interpretar las mejoras duraderas.",sourceId:"optimism-smernoff"}},{heading:"Úsalo con cuidado",paragraphs:["Las inversiones están pensadas para ampliar tu visión, no para hacerte responsable de la conducta dañina de otra persona. Si un pensamiento trata de que te maltratan, te amenazan o no estás a salvo, la prioridad es tu seguridad y el apoyo de personas de confianza o de profesionales, no un ejercicio para reformular pensamientos."]}],example:{title:"Elena, 52 años, maestra",text:"Durante semanas Elena había estado repitiendo un pensamiento: mi hija debería llamarme más. Un domingo se sentó con las cuatro preguntas. ¿Era verdad? Le parecía que sí. ¿Podía estar absolutamente segura? No; su hija tenía dos trabajos. ¿Cómo reaccionaba cuando lo creía? Miraba el teléfono todo el tiempo, se sentía herida y empezaba sus llamadas con quejas. ¿Quién sería sin el pensamiento? Probablemente más tranquila, y simplemente contenta cuando el teléfono sonara. Al invertirlo, probó con “yo debería llamar más a mi hija” y encontró tres semanas recientes en las que había esperado en lugar de llamar. Esa tarde envió un mensaje corto y cálido, sin rastro de reproche. Su hija respondió con una nota de voz, y acordaron una llamada regular los domingos."},practice:["Anota un pensamiento corto y específico sobre una persona o situación que te ha estado molestando.","Responde por escrito las cuatro preguntas, dedicando al menos un minuto de silencio a cada una.","Da la vuelta al pensamiento de dos o tres maneras y encuentra tres ejemplos reales para una de las inversiones."],reflection:"¿Qué pensamiento, si pudieras aferrarte menos a él, cambiaría más cosas en tu vida diaria?",question:"¿Cuál es un resumen honesto de la evidencia sobre The Work de Byron Katie?",options:["Está tan bien investigado como la TCC.","Se ha demostrado que no funciona.","Los estudios iniciales y sin control son alentadores, pero no se ha probado en ensayos aleatorizados sólidos."],correct:2,feedback:"El estudio principal mostró mejoras pero no tenía grupo de control y perdió a cerca de la mitad de sus participantes en el seguimiento. Eso hace de The Work una herramienta interesante para probar, no un tratamiento basado en la evidencia.",takeaway:"Antes de discutir con un pensamiento, pregúntate si puedes estar seguro de él y quién serías sin él.",sources:["optimism-the-work","optimism-smernoff","optimism-hofmann"],visual:{kind:"steps",title:"The Work en cinco pasos",steps:[{label:"¿Verdad?",text:"Pregunta si el pensamiento es verdad. Basta un simple sí o no."},{label:"¿Seguro?",text:"Pregunta si puedes estar absolutamente seguro. Mira otra vez la situación."},{label:"Reacción",text:"Nota qué pasa en tu cuerpo, tus emociones y tus acciones cuando lo crees."},{label:"Sin él",text:"Imagínate en la misma situación sin el pensamiento."},{label:"Inviértelo",text:"Da la vuelta al pensamiento y encuentra tres ejemplos reales de la inversión."}],note:"Contado con nuestras propias palabras a partir de las instrucciones del sitio web de Byron Katie."},technique:{name:"The Work",origin:"Byron Katie · The Work (instructions at thework.com)",steps:["Escribe en papel un pensamiento estresante, corto y específico, de preferencia sobre una persona.","Pregunta si es verdad y responde solo sí o no.","Pregunta si puedes estar absolutamente seguro de que es verdad.","Nota cómo reaccionas cuando crees el pensamiento: cuerpo, emociones, acciones, y cómo te tratas a ti y a los demás.","Imagínate en la misma situación sin el pensamiento y nota qué cambia.","Da la vuelta al pensamiento (hacia ti, hacia la otra persona, hacia lo opuesto) y encuentra tres ejemplos reales para cada uno."],evidence:"Un estudio piloto sin control encontró mejoras en la depresión, la ansiedad y la calidad de vida tras un curso de nueve días, pero no tenía grupo de control y perdió a cerca de la mitad de sus participantes en el seguimiento. La eficacia no se ha establecido en ensayos aleatorizados.",sourceId:"optimism-the-work"},photo:{id:"1503541517233-120571491cf3",alt:"Un hombre sentado en un banco del parque con los ojos cerrados, rodeado de árboles"}},{id:"optimism-6",title:"Optimismo realista y tres cosas buenas",minutes:10,goal:"Distingue el optimismo realista de la positividad forzada y empieza un hábito nocturno de tres cosas buenas.",reading:["El optimismo aprendido no es lo mismo que el pensamiento positivo. Forzar frases alegres incluso puede tener el efecto contrario: en una serie de experimentos, las personas con baja autoestima que repitieron que eran una persona digna de cariño acabaron con peor ánimo que quienes no lo hicieron. La positividad tóxica, la presión de mirar el lado bueno pase lo que pase, puede hacer que las personas sientan que no tienen derecho a estar mal. El optimismo realista ve el problema con claridad, te deja sentir lo que sientes y aun así espera que el esfuerzo, el tiempo o la ayuda puedan mejorar un poco las cosas. Pregunta qué es lo más probable, no qué es lo más agradable.","Una práctica sencilla entrena tu atención hacia lo que salió bien sin negar lo que no. En un estudio en línea de 2005 de Seligman y sus colegas, las personas anotaron cada día tres cosas que salieron bien, y por qué salieron bien, durante una semana. En comparación con una tarea de escritura de placebo, fueron más felices y estuvieron menos deprimidas a partir del mes, y la diferencia duró hasta los seis meses, sobre todo en quienes siguieron haciéndolo. Estudios posteriores encontraron efectos menores y menos específicos, así que piénsalo como un hábito sencillo que puede levantar un poco tu ánimo, no como una cura."],deeper:[{heading:"Optimismo realista frente a positividad tóxica",paragraphs:["La diferencia se nota en cómo tratas una emoción desagradable. La positividad tóxica la aparta; el optimismo realista deja que esté ahí y luego busca el siguiente paso útil. Puedes decir “esto es muy difícil” y “puedo dar un paso hoy” a la vez."],visual:{kind:"compare",title:"Dos formas de responder a un contratiempo",left:{label:"Positividad tóxica",items:["¡Solo mantente positivo!","Esconde la tristeza, la preocupación o la rabia","Ignora los riesgos reales","Repite consignas que no crees"]},right:{label:"Optimismo realista",items:["Esto es difícil, y aun así puedo actuar.","Permite las emociones y luego mira hacia adelante","Planea para el desenlace más probable","Usa explicaciones que puedes creer"]},note:"Las afirmaciones positivas sobre uno mismo elevaron un poco el ánimo de las personas con alta autoestima pero lo bajaron en las de baja autoestima (Wood y colegas, 2009)."}},{heading:"Ponlo en perspectiva",paragraphs:["Cuando una preocupación empieza a crecer y a repetirse, una herramienta del entrenamiento en resiliencia que el equipo de Seligman desarrolló para el Ejército de EE. UU. puede ayudar. Escribe el peor desenlace que imaginas, luego escribe deliberadamente el mejor desenlace, igual de improbable, luego el desenlace más probable. Por último, haz un plan para el más probable. Imaginar el mejor desenlace sirve para que el peor pierda fuerza, no para reemplazarlo."],visual:{kind:"steps",title:"Peor, mejor, más probable",steps:[{label:"Peor",text:"Escribe la versión catastrófica que ya imaginas."},{label:"Mejor",text:"Escribe el mejor desenlace, igual de improbable."},{label:"Más probable",text:"Escribe lo que probablemente pasará, según las pruebas que tienes."},{label:"Plan",text:"Decide un paso para manejar el desenlace más probable."}]}},{heading:"Qué dice la investigación",paragraphs:["Una réplica del estudio de 2005 encontró que el ejercicio de tres cosas buenas aumentaron la felicidad con el tiempo, pero también lo hizo una tarea de placebo positivo, y el ejercicio no superó a la condición de control en la depresión. Un metaanálisis más amplio de ejercicios de psicología positiva encontró efectos pequeños sobre el bienestar y la depresión que se reducían en el seguimiento, y muchos de los estudios eran de baja calidad.","La investigación en salud añade otro matiz: el optimismo se asocia con un menor riesgo de enfermedad cardíaca y de muerte temprana, pero esos estudios son observacionales y no permiten demostrar una relación de causa y efecto. Mantén el hábito porque te ayuda a fijarte en más aspectos de tu vida, no porque garantice ningún resultado."]}],example:{title:"Sam, 45 años, conductor de autobús",text:"Sam era escéptico con las listas de gratitud, pero tras un mes duro de horas extra y preocupación por la salud de su padre, aceptó probar tres cosas buenas durante una semana. La primera noche escribió: un pasajero habitual le agradeció que esperara, la sopa del almuerzo estaba caliente y su hermana llamó. ¿Por qué? Él había elegido esperar, había preparado el almuerzo la noche anterior y su hermana lo quiere. Algunas noches costaba encontrar tres, así que anotaba cosas pequeñas: una racha de semáforos en verde, una parada tranquila. Aun así llamó a la clínica por los análisis de su padre; la lista no sustituía eso. Pero al final de la semana se dio cuenta de que durante el turno se fijaba en cosas que podría anotar, y el camino a casa se le hizo un poco más llevadero."},practice:["Esta noche, escribe tres cosas que salieron bien hoy, por pequeñas que sean, y una línea sobre por qué ocurrió cada una.","Elige una preocupación actual y escribe el peor desenlace, uno ideal igual de improbable y el más probable. Añade un paso para afrontar este último.","Mañana, cuando sientas el impulso de forzar la positividad, nombra la dificultad en voz alta o en papel y añade un siguiente paso realista."],reflection:"¿Cuál es, para ti, la diferencia entre esperar que algo salga bien y fingir que ya está todo bien?",question:"¿Qué afirmación describe mejor el optimismo realista?",options:["Reconocer un problema con honestidad y esperar que el esfuerzo, el tiempo o la ayuda puedan mejorar las cosas.","Repetir afirmaciones positivas hasta que desaparezcan las emociones negativas.","Esperar lo peor para no decepcionarte nunca."],correct:0,feedback:"El optimismo realista mantiene los dos ojos abiertos: nombra la dificultad y aun así busca el siguiente paso útil. Las afirmaciones positivas forzadas pueden tener el efecto contrario, y esperar siempre lo peor agota las ganas de actuar.",takeaway:"Mira el problema con claridad, y busca con la misma claridad lo que todavía puede salir bien.",sources:["optimism-wood","optimism-seligman-exercises","optimism-mongrain","optimism-bolier","optimism-mrt","optimism-ggia-three-good-things","optimism-rozanski"],visual:{kind:"bars",title:"Ejercicios de psicología positiva: efecto promedio justo después del programa",bars:[{label:"Bienestar subjetivo",value:.34,display:"d = 0.34"},{label:"Bienestar psicológico",value:.2,display:"d = 0.20"},{label:"Depresión (reducción)",value:.23,display:"d = 0.23"}],note:"39 estudios aleatorizados con 6,139 personas (Bolier y colegas, 2013): efectos de pequeños a moderados. A los 3–6 meses los efectos fueron menores y el efecto sobre la depresión ya no era significativo. Muchos estudios eran de baja calidad, y el análisis abarca muchos ejercicios, no solo tres cosas buenas.",sourceId:"optimism-bolier"},technique:{name:"Tres cosas buenas",origin:"Martin Seligman and colleagues · Positive Psychology Progress, American Psychologist (2005)",steps:["Reserva unos diez minutos antes de dormir, con un cuaderno en lugar del teléfono si puedes.","Anota tres cosas que salieron bien hoy; las cosas pequeñas cuentan.","Para cada una, añade algunos detalles sobre lo que pasó y cómo te hizo sentir.","Para cada una, escribe por qué crees que ocurrió, incluida tu contribución, si la hubo.","Repite cada noche durante al menos una semana y luego decide si sigues."],evidence:"En el estudio original, los beneficios frente a un placebo aparecieron a partir del mes y duraron seis meses, sobre todo en quienes siguieron practicando. Una réplica encontró aumentos de felicidad similares con un placebo positivo y ningún beneficio específico para la depresión, así que espera efectos pequeños y generales.",sourceId:"optimism-ggia-three-good-things"},photo:{id:"1750885847789-f5748b585e3a",alt:"Una mujer en un balcón mirando hacia una ciudad"}}]},L=Object.freeze(Object.defineProperty({__proto__:null,COURSE:x,SOURCES:z},Symbol.toStringTag,{value:"Module"})),S=[{id:"state-emotion-decisions",title:"Lerner, Li, Valdesolo y Kassam · 2015 · Emoción y toma de decisiones (Annual Review of Psychology)",url:"https://escholarship.org/uc/item/8552m415",type:"research",finding:"Una revisión de unos 35 años de investigación concluye que las emociones influyen mucho y de forma generalizada en nuestras decisiones, a veces para bien y otras para mal. Lo hacen de formas predecibles que se pueden identificar. Describe cómo las emociones de una situación suelen pasar a decisiones que no tienen relación con ella sin que nos demos cuenta. Por ejemplo, leer noticias tristes hizo que las personas estimaran como mayores otros riesgos sin relación con esas noticias.",limitation:"Es una revisión narrativa, no un metaanálisis, así que no ofrece un único tamaño del efecto. Describe cómo las emociones moldean las decisiones en general; no prueba ninguna de las herramientas rápidas de cambio de estado de este curso. Se leyeron el resumen y la copia del autor del texto completo."},{id:"state-reappraisal-gross",title:"Gross · 2002 · Regulación emocional: consecuencias afectivas, cognitivas y sociales (Psychophysiology)",url:"https://www.cambridge.org/core/journals/psychophysiology/article/abs/emotion-regulation-affective-cognitive-and-social-consequences/552536BD5988D0D2079A7E0CC82E1ED8",type:"research",finding:"James Gross compara dos estrategias. La reevaluación, que consiste en cambiar la manera de interpretar una situación para reducir su impacto emocional, redujo tanto la experiencia emocional como su expresión externa sin perjudicar la memoria. La supresión, que consiste en ocultar las señales externas de una emoción, no redujo la emoción en sí, deterioró la memoria y elevó las respuestas fisiológicas de estrés en la persona y en sus interlocutores.",limitation:"Es una revisión de hallazgos de laboratorio, sobre todo experimentos breves con películas y conversaciones que despertaban emociones. Explica el modelo de proceso de la regulación emocional pero no da un tamaño del efecto combinado. Se leyó el resumen."},{id:"state-regulation-meta",title:"Webb, Miles y Sheeran · 2012 · Metaanálisis de estrategias de regulación emocional (Psychological Bulletin)",url:"https://www.academia.edu/13555860/Dealing_With_Feeling_A_Meta_Analysis_of_the_Effectiveness_of_Strategies_Derived_From_the_Process_Model_of_Emotion_Regulation",type:"research",finding:"190 estudios con 306 comparaciones experimentales. Efectos promedio sobre los resultados emocionales: cambio cognitivo (reevaluación) d+ = 0.36, modulación de la respuesta d+ = 0.16, orientación de la atención d+ = 0.00. Dentro de estos grupos: tomar perspectiva 0.45, reevaluar la situación emocional 0.36, reevaluar la respuesta emocional 0.23; distracción 0.27, concentración en la situación emocional −0.26; suprimir la expresión de la emoción 0.32, suprimir la experiencia −0.04, suprimir los pensamientos sobre el suceso −0.12.",limitation:"La mayoría de los estudios fueron experimentos breves de laboratorio con películas, imágenes o tareas emocionales; los efectos en la vida diaria y a lo largo de semanas pueden ser distintos. El artículo se leyó a través de una copia en línea de la versión publicada."},{id:"state-acute-exercise",title:"Reed y Ones · 2006 · Ejercicio aeróbico agudo y afecto positivo activado: un metaanálisis",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 estudios (1979–2005), 450 tamaños del efecto, 13,101 participantes. Una sola sesión de ejercicio aeróbico aumentó el afecto positivo activado (sentirse enérgico, entusiasmado, alerta) con un efecto promedio corregido de 0.47. La baja intensidad, las sesiones de hasta unos 35 minutos y las dosis de bajas a moderadas funcionaron bien; la mejora duró al menos unos 30 minutos antes de volver al nivel inicial. Los grupos de control mostraron una pequeña caída (−0.17).",limitation:"Sensaciones comunicadas por los propios participantes, en su mayoría voluntarios sanos; las diferencias individuales fueron grandes. Los efectos de corto plazo sobre el ánimo no son evidencia de que una caminata trate la depresión o la ansiedad. Se leyó el resumen."},{id:"state-exercise-mental-health",title:"Singh et al. · 2023 · Actividad física para la depresión, la ansiedad y el malestar psicológico: revisión paraguas (BJSM)",url:"https://bjsm.bmj.com/content/57/18/1203",type:"research",finding:"97 revisiones sistemáticas que abarcan 1,039 ensayos aleatorizados y 128,119 participantes. La actividad física redujo los síntomas de depresión (efecto mediano −0.43), ansiedad (−0.42) y malestar psicológico (−0.60). Una mayor intensidad se vinculó con mejoras más grandes, y las intervenciones de 12 semanas o menos mostraron los mayores efectos.",limitation:"77 de las 97 revisiones se valoraron con una calidad críticamente baja, así que las cifras exactas requieren cautela. Son programas de varias semanas, no una sola sesión de movimiento, y no reemplazan el tratamiento profesional. Se leyó el resumen."},{id:"state-facial-feedback",title:"Coles, Larsen y Lench · 2019 · Metaanálisis de la literatura sobre retroalimentación facial",url:"https://trace.tennessee.edu/utk_gradthes/5003/",type:"research",finding:"286 tamaños del efecto de 136 estudios: las expresiones faciales tuvieron un efecto pequeño pero fiable sobre la experiencia emocional (d = 0.20). Cerca del 70% de la variación entre estudios reflejaba diferencias reales de contexto; los efectos fueron mayores con escenarios imaginados y cuando no había un estímulo emocional. La evidencia de que los rostros cambian cómo las personas valoran la calidad emocional de las imágenes se debilitó tras corregir el sesgo de publicación.",limitation:"Los efectos son pequeños y variables. Se leyó el resumen de la versión de la Universidad de Tennessee de este trabajo (publicado en Psychological Bulletin en 2019)."},{id:"state-many-smiles",title:"Coles et al. (Colaboración Many Smiles) · 2022 · Una prueba multilaboratorio de la hipótesis de la retroalimentación facial",url:"https://www.nature.com/articles/s41562-022-01458-9",type:"research",finding:"Un estudio preinscrito con 3,878 participantes en 19 países. Imitar sonrisas de forma deliberada y adoptar voluntariamente una sonrisa amplificaron e iniciaron sentimientos de felicidad. Cuando la retroalimentación facial se manipuló de forma encubierta con un bolígrafo sostenido en la boca, los resultados no fueron concluyentes.",limitation:"El resumen no da tamaños del efecto; los autores concluyen que las condiciones en que funciona la retroalimentación facial son más limitadas de lo que sugieren las teorías amplias de la cognición corporeizada. Solo se evaluó la felicidad. Se leyó el resumen."},{id:"state-power-pose-replication",title:"Ranehill et al. · 2015 · Solidez de las poses de poder: sin efecto sobre las hormonas ni la tolerancia al riesgo",url:"https://faculty.haas.berkeley.edu/dana_carney/ranehill.pdf",type:"research",finding:"Con 200 participantes (102 hombres, 98 mujeres), un experimentador ciego a las condiciones y poses más largas, la pose de poder no cambió la testosterona (p = .162), el cortisol (p = .272) ni la toma de riesgos financieros (p = .215). Las sensaciones autoinformadas de poder sí aumentaron (p = .017).",limitation:"Es una réplica conceptual en un entorno de laboratorio; no evalúa todos los resultados posibles de la postura. Se leyó el artículo completo."},{id:"state-music-stress",title:"de Witte et al. · 2020 · Intervenciones musicales y resultados relacionados con el estrés: dos metaanálisis (Health Psychology Review)",url:"https://pure.uva.nl/ws/files/58927620/Effects_of_music_interventions_on_stress_related_outcomes_a_systematic_review_and_two_meta_analyses.pdf",type:"research",finding:"104 ensayos aleatorizados, 9,617 participantes, 327 tamaños del efecto. Las intervenciones musicales redujeron el estrés fisiológico (d = 0.380) y el estrés psicológico (d = 0.545). Entre los resultados fisiológicos, los efectos fueron mayores sobre la frecuencia cardíaca (d = 0.456) que sobre la presión arterial (d = 0.343) o los niveles hormonales (d = 0.349). La música más lenta (60–80 pulsos por minuto) mostró una tendencia a efectos psicológicos mayores; la música elegida por la persona frente a la elegida por los investigadores no marcó una diferencia significativa.",limitation:"Muchos ensayos se hicieron en entornos sanitarios y algunas categorías tenían pocos tamaños del efecto. Los análisis se centran en reducir el estrés, no en usar música para subir la energía. Se leyeron el resumen y la síntesis."},{id:"state-cyclic-sighing",title:"Balban et al. · 2023 · Prácticas breves y estructuradas de respiración y estado de ánimo (Cell Reports Medicine)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/",type:"research",finding:"En un ensayo aleatorizado a distancia, 108 participantes practicaron 5 minutos al día durante 28 días: suspiro cíclico (n = 30), respiración en caja (n = 21), hiperventilación cíclica con retención (n = 33) o meditación de atención plena (n = 24). Aumento diario promedio del afecto positivo: ejercicios de respiración combinados 1.91 frente a atención plena 1.22; suspiro cíclico 1.89, respiración en caja 1.84, hiperventilación cíclica 1.97. La respiración redujo la frecuencia respiratoria en reposo más que la atención plena; la ansiedad de estado bajó de forma similar en todos los grupos.",limitation:"Grupos pequeños, aplicación a distancia con adherencia autoinformada, solo cuatro semanas y sin seguimiento. Los participantes eran voluntarios sanos, así que los resultados no dicen nada sobre los trastornos de ansiedad o de pánico. Se leyó el artículo completo en PubMed Central."},{id:"state-affect-labeling",title:"Lieberman et al. · 2007 · Poner los sentimientos en palabras: etiquetado emocional y amígdala (Psychological Science)",url:"https://sanlab.psych.ucla.edu/wp-content/uploads/sites/31/2015/05/Lieberman_AL-2007.pdf",type:"research",finding:"En un estudio de resonancia magnética funcional con 30 adultos que miraban rostros emocionales, elegir una palabra para la emoción (etiquetado emocional) produjo menos actividad en la amígdala que elegir una etiqueta de género o emparejar rostros. La corteza prefrontal ventrolateral derecha estuvo más activa durante el etiquetado emocional, y su actividad se relacionó de forma inversa con la de la amígdala.",limitation:"Una sola sesión de neuroimagen con una muestra pequeña; en este estudio no se midió el malestar subjetivo, y la actividad cerebral no es lo mismo que cómo se siente alguien. Se leyó el artículo completo."},{id:"state-labeling-review",title:"Torre y Lieberman · 2018 · El etiquetado emocional como regulación emocional implícita (Emotion Review)",url:"https://journals.sagepub.com/doi/10.1177/1754073917742706",type:"research",finding:"Una revisión que sostiene que poner los sentimientos en palabras puede reducir la intensidad emocional en el autoinforme, las respuestas fisiológicas, la actividad cerebral y la conducta, con efectos comparables a los de estrategias explícitas como la reevaluación, aunque rara vez se siente como regulación. Las personas tienden a predecir que etiquetar intensificará sus sentimientos.",limitation:"Es una revisión narrativa, no un metaanálisis; no da un tamaño del efecto combinado y señala muchas preguntas abiertas sobre cuándo y para quién funciona el etiquetado. Se leyó el resumen."},{id:"state-gratitude-meta",title:"Cregg y Cheavens · 2021 · Intervenciones de gratitud para la depresión y la ansiedad: un metaanálisis",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 estudios, 3,675 participantes. Las intervenciones de gratitud tuvieron un efecto pequeño sobre los síntomas de depresión y ansiedad tras la intervención (g = −0.29) y en el seguimiento (g = −0.23). Los efectos fueron mayores frente a controles en lista de espera que frente a condiciones de control activas.",limitation:"Los autores recomiendan que quienes buscan reducir la depresión o la ansiedad usen intervenciones con evidencia más sólida; parte del beneficio puede reflejar efectos de expectativa. Se leyó el resumen."},{id:"state-gratitude-expressed",title:"Kirca, Malouff y Meynadier · 2023 · Intervenciones de gratitud expresada y bienestar: un metaanálisis",url:"https://link.springer.com/article/10.1007/s41042-023-00086-6",type:"research",finding:"25 muestras aleatorizadas, 6,745 participantes. Expresar gratitud mejoró el bienestar en comparación con condiciones neutras (g = 0.22), incluida la felicidad (g = 0.16), la satisfacción con la vida (g = 0.22) y el afecto positivo (g = 0.21). Los beneficios aparecieron incluso cuando no se comunicaba la gratitud a la otra persona, y la duración de la intervención no cambió significativamente el efecto.",limitation:"Efectos promedio pequeños; los estudios evaluaron escribir o expresar gratitud a otras personas, no la rutina matutina exacta de este curso. Se leyó el resumen."},{id:"state-positive-self-statements",title:"Wood, Perunovic y Lee · 2009 · Autoafirmaciones positivas: poder para unos, peligro para otros (Psychological Science)",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"En una encuesta (249 estudiantes), las personas informaron que usaban autoafirmaciones positivas y creían que ayudaban. En un experimento (68 estudiantes), repetir 16 veces “Soy una persona digna de cariño” hizo que los participantes con baja autoestima se sintieran peor que quienes no la repitieron, mientras que los de alta autoestima se sintieron algo mejor. En un tercer estudio (116 estudiantes), los participantes con baja autoestima mejoraron cuando se les permitió considerar en qué sentidos la afirmación era cierta y en cuáles no.",limitation:"Estudiantes universitarios canadienses, una sola afirmación, estado de ánimo a corto plazo; no demuestra que toda autoafirmación positiva sea dañina. Se leyeron el resumen y el artículo completo."},{id:"state-mental-contrasting",title:"Wang, Wang y Gai · 2021 · Contraste mental con intenciones de implementación: un metaanálisis",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 estudios con 24 tamaños del efecto y 15,907 participantes. Imaginar un futuro deseado y luego los obstáculos en el camino, combinado con planes «si… entonces…», tuvo un efecto promedio de pequeño a medio sobre el logro de metas (g = 0.336). La aplicación presencial (g = 0.465) funcionó mejor que los materiales escritos (g = 0.277).",limitation:"Un número reducido de estudios; los dos estudios más grandes reunían a la mayoría de los participantes y se excluyeron de los análisis de moderadores. Evalúa el contraste mental, no el proceso Dickens en sí. Se leyó el artículo."},{id:"state-self-compassion-motivation",title:"Breines y Chen · 2012 · La autocompasión aumenta la motivación para mejorar",url:"https://hqinstitute.org/wp-content/uploads/sites/5/2022/09/Breines_Chen_SelfCompMotivation.2012.pdf",type:"research",finding:"Cuatro experimentos. Adoptar una mirada autocompasiva ante una debilidad, una transgresión moral o un examen suspendido aumentó la creencia de que la debilidad podía cambiar, la motivación para reparar el daño y no repetir el error, y el tiempo de estudio tras un examen suspendido, en comparación con el refuerzo de la autoestima o con condiciones de control.",limitation:"Sobre todo estudiantes universitarios más una muestra de adultos en línea; motivación y conducta a corto plazo en el laboratorio, no cambio a largo plazo. Se leyó el artículo."},{id:"state-power-pose-review",title:"The Psychologist (Sociedad Británica de Psicología) · Una década de poses de poder: ¿dónde estamos?",url:"https://www.bps.org.uk/psychologist/decade-power-posing-where-do-we-stand",type:"guidance",finding:"Resume el debate: la afirmación original de que las poses expansivas elevan la testosterona y reducen el cortisol en gran medida no se replicó, y un número especial de 2017 encontró un efecto hormonal prácticamente nulo. La postura expansiva sí cambia de forma fiable cuánto poder sienten las personas, posiblemente en parte porque evita posturas encorvadas y contraídas.",limitation:"Es una revisión de revista sobre una literatura en disputa, no un estudio nuevo; el tamaño exacto del efecto sobre la sensación de poder sigue en debate."},{id:"state-nhs-breathing-tips",title:"NHS inform (Escocia) · Consejos para hacer ejercicios de respiración y relajación",url:"https://www.nhsinform.scot/healthy-living/mental-wellbeing/breathing-and-relaxation-exercises/tips-for-doing-breathing-and-relaxation-exercises/",type:"guidance",finding:"Aconseja detenerte si sientes cualquier molestia o dolor durante los ejercicios de respiración, permanecer sentado o acostado un momento después para evitar mareos, y hablar primero con tu médico de cabecera si tienes una afección médica, como problemas respiratorios.",limitation:"Orientación pública general del sistema de salud de Escocia; no es específica del suspiro cíclico ni de la respiración energizante."},{id:"state-nhs-panic",title:"NHS · Trastorno de pánico",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"El trastorno de pánico consiste en tener con regularidad ataques repentinos de pánico o miedo. Los ataques asustan, pero no son peligrosos. El NHS recomienda acudir al médico de cabecera; los tratamientos principales son la terapia psicológica, como la terapia cognitivo-conductual, y, para algunas personas, la medicación. Respirar lenta y profundamente es una de las medidas de autoayuda durante un ataque.",limitation:"Orientación del servicio de salud del Reino Unido; los servicios y los números de móvil difieren según el país. En una emergencia, llama al número de emergencias de tu país."},{id:"state-robbins-triad",title:"Tony Robbins · Discover your peak state (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/discover-your-peak-state",type:"technique",finding:"Robbins presenta tres fuerzas que, según dice, controlan las emociones: la fisiología, el lenguaje y el enfoque. Enseña que, si las cambias de forma deliberada, puedes cambiar cómo te sientes a diario y alcanzar un estado en el que te resulte más fácil actuar.",limitation:"Es un modelo de coaching publicado en la web del autor, no una teoría científica; la tríada en su conjunto no se ha probado. En este curso, cada elemento se contrasta con estudios por separado."},{id:"state-robbins-questions",title:"Tony Robbins · How to ask questions and better yourself every day (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/ask-better-questions",type:"technique",finding:"Robbins sostiene que las preguntas que te haces habitualmente funcionan como filtros que dirigen el enfoque y la interpretación, y recomienda sustituir las preguntas que te restan fuerza por otras que te la dan, como práctica diaria.",limitation:"Es un consejo de coaching; ningún estudio ha probado directamente los conjuntos de preguntas de Robbins. La investigación relacionada sobre la atención se cita aparte."},{id:"state-robbins-words",title:"Tony Robbins · Harness the power of words: transform your words in 4 steps (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/transform-your-words-in-4-steps",type:"technique",finding:"Describe el vocabulario transformacional: notar las palabras habituales que asocias con las emociones difíciles y cambiar las etiquetas intensas por otras más suaves (por ejemplo, “decaído” en lugar de “deprimente”, “frustrado” en lugar de “furioso”), practicado como un reto de 10 días.",limitation:"Es un consejo de coaching; el reto de vocabulario en sí no se ha estudiado. La investigación relacionada sobre el etiquetado emocional y la reevaluación se cita aparte."},{id:"state-robbins-rituals",title:"Tony Robbins · Morning rituals that can change your life (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/whats-your-morning-ritual",type:"technique",finding:"Distingue las afirmaciones (palabras de ánimo que simplemente se dicen) de las declaraciones con cuerpo y voz (frases que acompañas con la voz, la postura y el movimiento), y sostiene que las afirmaciones por sí solas pueden fallar como técnica transformadora.",limitation:"Es un consejo de coaching; las declaraciones con cuerpo y voz no se han probado en investigaciones. La investigación sobre las autoafirmaciones positivas (Wood et al., 2009) sugiere que importa poder creer lo que dices."},{id:"state-robbins-priming",title:"Tony Robbins · Train your brain in minutes (tonyrobbins.com)",url:"https://www.tonyrobbins.com/health-vitality/train-your-brain-in-minutes-4/",type:"technique",finding:"Describe el priming como una práctica diaria de unos 10 minutos de respiración y movimiento dirigidos, gratitud y visualización, pensada para ajustar los pensamientos y las emociones hacia un estado óptimo.",limitation:"Es el propio sitio del autor; la página da pocos detalles de los pasos y la rutina de priming completa no se ha estudiado."},{id:"state-priming-cnbc",title:"CNBC · 2019 · La rutina matutina de 10 minutos de Tony Robbins (Grogan)",url:"https://www.cnbc.com/2019/04/09/tony-robbins-10-minute-morning-routine-to-get-in-a-peak-state.html",type:"technique",finding:"Un resumen escrito de la rutina de priming de Robbins en menos de 10 minutos: rondas de respiración enérgica con movimientos de brazos, reflexión sobre tres cosas por las que estás agradecido, una visualización de luz que llena el cuerpo y concentración en tres metas como si ya estuvieran logradas.",limitation:"Es el resumen de un periodista, no un estudio; la visualización sanadora no es evidencia de ningún efecto sobre las enfermedades, y respirar rápido puede causar mareos."},{id:"state-robbins-dickens",title:"Tony Robbins · Unlocking potential: the Dickens process (tonyrobbins.com)",url:"https://www.tonyrobbins.com/personal-growth/unlocking-potential",type:"technique",finding:"Describe el proceso Dickens, llamado así por los fantasmas de las Navidades pasada, presente y futura: identificar una creencia limitante y luego examinar lo que te ha costado en el pasado, lo que te cuesta a ti y a tus seres queridos ahora y lo que costará dentro de uno, tres, cinco y diez años, antes de sustituirla por una creencia nueva.",limitation:"Es un consejo de coaching; el proceso Dickens no se ha estudiado. En su forma intensa puede resultar angustiante, por eso este curso usa una versión más suave y más breve."},{id:"state-robbins-standards",title:"Tony Robbins · How to raise your standards and upgrade your life (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/how-to-raise-your-standards",type:"technique",finding:"Robbins sostiene que el cambio duradero viene de elevar tus estándares: convertir “debería” vagos en “debo” innegociables, actualizar las creencias que los sostienen y centrarte en áreas clave como las relaciones, la carrera y la salud.",limitation:"Es un consejo de coaching sin investigación que lo pruebe; este curso lo acompaña con evidencia sobre el contraste mental y la autocompasión."},{id:"state-stanford-sighing",title:"Stanford Medicine · 2023 · El suspiro cíclico puede ayudarte a exhalar la ansiedad",url:"https://med.stanford.edu/news/insights/2023/02/cyclic-sighing-can-help-breathe-away-anxiety.html",type:"technique",finding:"Describe el suspiro cíclico tal como lo estudiaron David Spiegel, Andrew Huberman y Melis Yilmaz Balban: inhalar por la nariz, hacer una segunda inhalación más profunda para expandir por completo los pulmones y luego exhalar despacio por la boca, repetido durante unos cinco minutos al día. En su ensayo de un mes mejoró el ánimo positivo más que la meditación de atención plena.",limitation:"Es un resumen publicado por la institución. El ensayo excluyó a personas con trastornos psiquiátricos de moderados a graves; el método no se ha probado como tratamiento de los trastornos de ansiedad."}],C={id:"state",title:"¿Tus emociones te arrastran? Cómo recuperar el mando y pasar a la acción",subtitle:"7 lecciones de 7 a 11 minutos. Prueba pequeños cambios en respiración, postura y diálogo interior.",description:"Aprende ejercicios breves para pasar de la tensión o el desánimo a sentirte tranquilo y preparado. Usa tu cuerpo, tu enfoque y tus palabras. Contrastamos las herramientas del coach Tony Robbins con la investigación, incluidas las ideas que no se confirmaron.",scope:"Para adultos que buscan herramientas cotidianas para cambiar el ánimo y la energía. Este curso es educativo: no ofrece diagnóstico ni tratamiento. No trata los trastornos de ansiedad, el trastorno de pánico ni la depresión, ni sustituye la terapia o la medicación. Si sientes mareo, aturdimiento, hormigueo o falta de aire durante un ejercicio de respiración, detente de inmediato. Vuelve a respirar con normalidad y siéntate. Si tienes una afección del corazón o de los pulmones o estás embarazada, consulta con un profesional de la salud antes de probar ejercicios de respiración para activarte. Nunca los practiques mientras conduces o estás en el agua. Si estás en crisis o tienes pensamientos de hacerte daño, llama al número de emergencias de tu país (911 en EE. UU., 112 en Turquía y gran parte de Europa).",outcome:"Siete herramientas que habrás probado para cambiar cómo te sientes: revisar la tríada, activar el cuerpo en dos minutos, practicar el suspiro cíclico, hacerte preguntas más útiles, nombrar y reformular lo que sientes, prepararte por la mañana durante diez minutos con una declaración que puedas creer y fijar un nuevo estándar con una acción diaria. Sabrás qué puedes esperar de cada una y cuáles son sus límites.",photo:{id:"1500080628126-901233e80205",alt:"Una mujer de pie sobre un muelle de madera en la hora dorada, alzando una mano hacia la luz"},lessons:[{id:"state-1",title:"El estado lo tiñe todo",minutes:7,goal:"Reconoce cómo te sientes ahora y los tres elementos que influyen en tu estado: cuerpo, enfoque y palabras.",reading:["Tu estado combina tu ánimo, tu energía y la tensión que sientes en el cuerpo ahora mismo. Un tren retrasado, un correo seco o un vaso de zumo derramado te afectan de forma distinta si estás descansado y tranquilo o agotado y tenso. Jennifer Lerner y sus colegas revisaron unos 35 años de investigación. Concluyeron que las emociones influyen mucho en nuestras decisiones y de formas predecibles, a veces para bien y otras para mal. Tu estado importa: influye en lo que notas, en lo que decides y en cómo tratas a quienes te rodean.","El coach y autor Tony Robbins enseña que puedes influir en tu estado. Su modelo propone tres elementos: la fisiología (cómo respiras, te colocas y te mueves), el enfoque (a qué prestas atención) y el lenguaje (las palabras y el significado que das a lo que ocurre). Cuando cambias uno, suele cambiar cómo te sientes. Este curso recoge su tríada y contrasta cada elemento con la investigación. Algunos tienen bastante respaldo, otros solo parcial, y una idea popular no se confirmó al repetir el estudio. Aprenderás ejercicios breves y sabrás qué puedes esperar de ellos."],deeper:[{heading:"Por qué importan unos pocos minutos",paragraphs:["Las emociones de una situación suelen contagiar la siguiente. La irritación de una mañana tensa puede influir en cómo lees el mensaje neutro de un compañero una hora después. La investigación sobre la toma de decisiones llama a esto emociones incidentales y encuentra que a menudo se trasladan sin que nos demos cuenta. Esa es una razón por la que una breve pausa para cambiar cómo te sientes antes de una conversación importante puede valer la pena.","El momento también importa. En la investigación de James Gross sobre regulación emocional, cambiar cómo interpretas una situación redujo tanto la emoción como su expresión externa. Ocultar la emoción, en cambio, no la redujo y aumentó el estrés fisiológico. Actuar pronto, antes de que ese estado se instale, te deja más margen para cambiarlo."],visual:{kind:"table",title:"Un momento, dos estados",columns:["Momento","Agotado y tenso","Tranquilo y preparado"],rows:[["El tren lleva 20 minutos de retraso","Este día está arruinado.","Qué fastidio. Voy a avisar y a aprovechar el tiempo."],["Un correo seco de tu jefe","Piensan que no sirvo.","Correo corto. Voy a preguntar qué necesita."],["Tu hijo hace un berrinche en la cena","No puedo con esto.","Está cansado. Primero bajo el tono y luego veo qué necesita."]],note:"Ejemplos ilustrativos. El hecho sigue siendo el mismo; el estado cambia lo que notas y cómo respondes."}},{heading:"Qué es la tríada y qué no es",paragraphs:["La tríada es un modelo de enseñanza, no una teoría científica probada. Aun así, cada palanca coincide con un campo real de investigación: el movimiento, la postura y la respiración; la atención; y la forma en que etiquetamos e interpretamos los hechos. Las próximas lecciones examinan cada elemento y los resultados de los estudios.","La meta no es sentirte genial todo el tiempo. La tristeza, la rabia y la preocupación pueden darte información útil. La meta es poder elegir: notar cuándo un estado no te está sirviendo y contar con unas cuantas formas fiables de cambiarlo."]}],example:{title:"Dana, 34 años, enfermera de urgencias",text:"Dana termina un turno de noche difícil y tiene que llamar a su casero por una gotera. Se da cuenta de que está encorvada sobre el volante, repasando un comentario grosero de un paciente y murmurando que todos están en su contra. Antes de marcar, hace una revisión rápida de la tríada. Cuerpo: se endereza, relaja los hombros y respira lento. Enfoque: se pregunta qué necesita realmente de esta llamada, que es un fontanero para el jueves. Palabras: cambia “todos están en mi contra” por “fue un turno duro”. La llamada sigue siendo un poco tensa, pero ella explica bien lo que necesita y consigue una fecha. No pasó nada mágico; simplemente dejó de permitir que el último paciente decidiera cómo le hablaba a la siguiente persona."},practice:["Haz una pausa ahora y valora tu energía de 0 a 10 y tu tensión de 0 a 10.","Revisa la tríada: nota cómo estás sentado y cómo respiras, en qué te estás centrando y qué palabras te repites.","Cambia una palanca durante 60 segundos, como ponerte de pie y estirarte o reformular una frase, y luego valora otra vez energía y tensión."],reflection:"¿A cuál de las tres palancas recurres normalmente y cuál sueles olvidar?",question:"En la tríada de Robbins, ¿cuál de estas es una manera de cambiar tu estado?",options:["Esperar a que tus circunstancias cambien solas.","Apartar la emoción y actuar como si no estuviera.","Cambiar tu cuerpo, tu enfoque, o las palabras y el significado que le das a un hecho."],correct:2,feedback:"Correcto. La tríada señala tres palancas que puedes mover: la fisiología, el enfoque y el lenguaje. Ocultar una emoción no suele reducirla. Si esperas a que cambien las circunstancias, dejas cómo te sientes en manos del azar.",takeaway:"Tu estado moldea tu día, y tienes tres palancas para cambiarlo: cuerpo, enfoque y palabras.",sources:["state-emotion-decisions","state-reappraisal-gross","state-robbins-triad"],visual:{kind:"cycle",title:"Cómo se mantiene tu estado",nodes:[{label:"Cuerpo",text:"Respiración, postura, movimiento y tensión muscular."},{label:"Enfoque",text:"Lo que notas, repasas y buscas."},{label:"Palabras y significado",text:"Cómo nombras e interpretas lo que ocurre."},{label:"Emoción",text:"El estado que realmente experimentas."},{label:"Acción",text:"Lo que haces después vuelve a influir en tu cuerpo y en tu enfoque."}],center:"Tu estado",note:"Basado en la tríada de Tony Robbins, un modelo de coaching y no una teoría probada. Cada palanca se contrasta con la investigación en las lecciones siguientes."},technique:{name:"Revisa tu estado con la tríada",origin:"Tony Robbins · Discover your peak state, tonyrobbins.com",steps:["Detente un momento y nombra con una palabra el estado en el que estás.","Cuerpo: nota tu postura, tu respiración y dónde acumulas tensión.","Enfoque: nota a qué le estás prestando atención o qué estás repasando.","Palabras: nota las frases que usas en tu cabeza sobre la situación.","Elige la palanca más fácil de mover y cámbiala a propósito durante aproximadamente un minuto.","Vuelve a nombrar tu estado y nota cualquier diferencia, por pequeña que sea."],evidence:"La tríada es un modelo de coaching y no se ha probado en su conjunto. Sus partes coinciden con la investigación sobre movimiento, atención y reevaluación, que muestra en los estudios efectos de corto plazo de pequeños a moderados sobre las emociones. Es una forma de organizar tus opciones, no una garantía de cambio inmediato.",sourceId:"state-robbins-triad"},photo:{id:"1758192139097-1e7f30c2498e",alt:"Un hombre cruzando una calle tranquila de la ciudad bajo árboles iluminados por el sol"}},{id:"state-2",title:"El cuerpo va primero",minutes:8,goal:"Prueba el movimiento, la postura y la música para cambiar tu energía en unos dos minutos. Distingue qué afirmaciones sobre el cuerpo tienen respaldo.",reading:["Robbins suele plantear la palanca de la fisiología de forma simple: la manera en que te mueves cambia la manera en que te sientes. La investigación respalda bastante esta idea. Un metaanálisis de Jennifer Reed y Deniz Ones reunió 158 estudios con más de 13,000 participantes y encontró que una sola sesión de ejercicio aeróbico ayudó a sentir más energía y emociones positivas con un efecto promedio moderado. Las sesiones de baja intensidad de hasta unos 35 minutos funcionaron bien, y la mejora duró al menos media hora. Mientras tanto, las personas de los grupos de control que se quedaron quietas tendieron a sentirse algo peor.","Tu rostro y tu postura también importan, pero menos de lo que sugieren las afirmaciones populares. Una revisión de 136 estudios encontró que las expresiones faciales influyen poco en las emociones y su efecto varía. Una prueba a gran escala en 19 países encontró que sonreír deliberadamente aumentó un poco la sensación de felicidad. Las llamadas poses de poder invitan a ser prudentes: una réplica con 200 personas no encontró efecto sobre la testosterona, el cortisol ni la toma de riesgos, aunque las personas sí se sintieron más poderosas. Así que ponte erguido si eso te ayuda a sentirte más capaz, pero no esperes que cambie tus hormonas."],deeper:[{heading:"Qué se confirmó y qué no",paragraphs:["El estudio original de 2010 sobre las poses de poder afirmaba que dos minutos de postura expansiva elevaban la testosterona y reducían el cortisol. Estudios posteriores en gran medida no encontraron esos cambios hormonales. Lo que sí se replica es un cambio en cuánto poder sienten las personas, posiblemente en parte porque las posturas encorvadas y contraídas hacen que las personas se sientan peor.","Eso deja un mensaje modesto pero útil: la postura y una sonrisa auténtica pueden ayudar un poco. El movimiento que aumenta tu frecuencia cardíaca suele ayudar más."],visual:{kind:"compare",title:"Cuerpo y estado: la versión honesta",left:{label:"Con respaldo (de pequeño a moderado)",items:["Una caminata a paso rápido o una breve sesión aeróbica aumenta la energía durante un rato.","Sonreír deliberadamente aumenta un poco la sensación de felicidad.","Una postura abierta y erguida puede hacer que te sientas más poderoso."]},right:{label:"Sin respaldo",items:["Dos minutos de pose cambian la testosterona o el cortisol.","La postura por sí sola cambia de forma fiable la toma de riesgos o el rendimiento.","Una sola sesión de movimiento trata la depresión o un trastorno de ansiedad."]},note:"Basado en metaanálisis sobre ejercicio y retroalimentación facial y en una gran réplica de las poses de poder."}},{heading:"La música como atajo",paragraphs:["Un metaanálisis de 104 ensayos aleatorizados con más de 9,600 personas encontró que las intervenciones musicales redujeron el estrés, con un efecto medio sobre cuánto estrés sentían las personas y un efecto menor sobre las medidas corporales, como la frecuencia cardíaca. La música más lenta, de unos 60 a 80 pulsos por minuto, mostró una tendencia a efectos mayores sobre el estrés percibido.","Los ensayos estudiaron la calma, no la activación. Si buscas más energía, una canción y algo de movimiento combinan dos herramientas. Para bajar el ritmo, elige algo lento."],visual:{kind:"bars",title:"Intervenciones musicales y estrés: efectos promedio",bars:[{label:"Estrés percibido (psicológico)",value:.545,display:"d = 0.545"},{label:"Frecuencia cardíaca",value:.456,display:"d = 0.456"},{label:"Medidas corporales de estrés en conjunto",value:.38,display:"d = 0.380"},{label:"Presión arterial",value:.343,display:"d = 0.343"}],note:"104 ensayos aleatorizados, 9,617 participantes (de Witte et al., 2020). Tamaños del efecto de la reducción del estrés frente a los controles; muchos ensayos se hicieron en entornos sanitarios.",sourceId:"state-music-stress"}},{heading:"A lo largo de semanas, no solo de minutos",paragraphs:["Moverte con regularidad aporta más que una mejora breve del ánimo. Una revisión que reunió 97 revisiones encontró que los programas de actividad física redujeron los síntomas de depresión, ansiedad y malestar psicológico, y que los programas más cortos e intensos mostraron efectos mayores. La mayoría de esas revisiones eran de baja calidad, y el ejercicio no reemplaza el tratamiento cuando lo necesitas."]}],example:{title:"Marcus, 41 años, supervisor de almacén",text:"A las 2 p. m. Marcus llega a su bajón habitual justo antes de la reunión semanal de seguridad que le toca dirigir. Antes se paraba al frente con los brazos cruzados y la voz apagada, esperando que terminara pronto. Esta semana prueba primero una pausa activa de dos minutos. Sube y baja las escaleras hasta el muelle de carga a paso rápido, pone una canción animada en los auriculares y abre los hombros mientras suena. No se siente transformado, pero su energía pasa de un 3 a un 5 sobre 10, y su voz vuelve a sonar como de costumbre. Dos personas hacen preguntas después, algo que rara vez ocurre. Decide quedarse con las escaleras y dejar de esperar un milagro."},practice:["Ponte de pie, echa los hombros hacia atrás y camina a paso rápido durante dos minutos, usando escaleras, un pasillo o la calle.","Pon una canción que corresponda al estado que quieres, lenta para relajarte o animada para activarte, y muévete con ella.","Valora tu energía de 0 a 10 antes y después, y anota qué parte marcó más la diferencia."],reflection:"Cuando tu energía baja, ¿cuál es el movimiento más pequeño que realmente podrías hacer donde estás?",question:"¿Qué encontró una gran réplica de las poses de poder?",options:["Las hormonas cambiaron mucho después de dos minutos de pose.","Las personas se sintieron más poderosas, pero las hormonas y la toma de riesgos no cambiaron.","La postura no tiene ninguna relación con las emociones."],correct:1,feedback:"Correcto. Con 200 participantes, las poses de poder no cambiaron la testosterona, el cortisol ni la toma de riesgos, pero las personas dijeron sentirse más poderosas. La postura puede ayudarte un poco a sentirte mejor. No esperes cambios hormonales.",takeaway:"Muévete primero: unos minutos de movimiento son una de las formas más fiables de cambiar cómo te sientes.",sources:["state-acute-exercise","state-facial-feedback","state-many-smiles","state-power-pose-replication","state-power-pose-review","state-music-stress","state-exercise-mental-health","state-robbins-triad"],visual:{kind:"steps",title:"Activa tu cuerpo en dos minutos",steps:[{label:"Nota",text:"¿Cómo se refleja este estado en tu cuerpo? ¿Estás encorvado, tenso o respirando de forma superficial?"},{label:"Abre",text:"Ponte de pie, estira la espalda y baja los hombros."},{label:"Muévete",text:"Camina a paso rápido, sube escaleras o sacude los brazos durante uno o dos minutos."},{label:"Añade una señal",text:"Pon una canción o prueba una sonrisa de verdad mientras te mueves."},{label:"Revisa",text:"Valora otra vez tu energía y nota qué cambió."}],note:"Las sesiones únicas de ejercicio aeróbico elevaron la sensación de energía con un efecto promedio moderado en un metaanálisis de 158 estudios; la postura y la sonrisa tienen efectos menores."},technique:{name:"Cambia tu fisiología",origin:"Tony Robbins · Discover your peak state, tonyrobbins.com",steps:["Fíjate en cómo se refleja tu estado actual en el cuerpo.","Ponte de pie y adopta la postura que tendrías si ya te sintieras tranquilo y capaz.","Muévete con algo de intensidad durante uno o dos minutos: camina a paso rápido, sube escaleras o sacude los brazos.","Respira más profundamente, con una exhalación larga y lenta.","Añade una sonrisa genuina o una canción que corresponda al estado que quieres.","Revisa cómo estás y mantén esa postura al pasar a la siguiente tarea."],evidence:"Una sola sesión de ejercicio aeróbico ayudó a sentir más energía y emociones positivas con un efecto promedio moderado que duró alrededor de media hora. Las expresiones faciales tienen un efecto pequeño y variable, y las posturas expansivas cambiaron las sensaciones de poder pero no las hormonas ni la toma de riesgos en una gran réplica.",sourceId:"state-robbins-triad"},photo:{id:"1692933216024-8de20c41321a",alt:"Una mujer caminando por un paseo de madera entre plantas verdes"}},{id:"state-3",title:"Calma en dos respiraciones",minutes:8,goal:"Aprende el suspiro cíclico y practícalo durante cinco minutos. Detente de inmediato si te mareas.",reading:["Respirar es la única parte de tu respuesta al estrés que puedes dirigir directamente. El suspiro cíclico usa dos inhalaciones y una exhalación larga: inhala por la nariz, completa con una segunda inhalación corta y luego exhala despacio por la boca hasta que sientas los pulmones vacíos. Los investigadores David Spiegel, Andrew Huberman y Melis Yilmaz Balban, de Stanford, lo pusieron a prueba frente a otros métodos. En su ensayo, 108 personas practicaron cinco minutos al día durante 28 días, asignadas al azar a suspiro cíclico, respiración en caja, hiperventilación cíclica rápida o meditación de atención plena.","Los grupos de respiración, en conjunto, mostraron un aumento diario del ánimo positivo mayor que el grupo de atención plena y una mayor caída de la frecuencia respiratoria en reposo. La ansiedad bajó en una cantidad similar en todos los grupos. Los tres métodos de respiración se diferenciaron muy poco entre sí. Conviene tener presentes los límites: los grupos eran pequeños, los propios participantes informaron de su práctica, el estudio duró cuatro semanas y se excluyó a las personas con trastornos psiquiátricos de moderados a graves. El suspiro cíclico es una herramienta cotidiana prometedora, no un tratamiento para los trastornos de ansiedad ni de pánico."],deeper:[{heading:"Cómo hacerlo",paragraphs:["Puedes tomar bastante aire en la primera inhalación; la segunda es corta y añade algo más de aire para terminar de llenar los pulmones. La exhalación es la parte importante: más lenta y más larga que la inhalación, como un suspiro relajado. Ve a un ritmo cómodo, no lo más rápido posible.","El estudio probó cinco minutos al día. En un momento de tensión, de uno a tres ciclos son una dosis pequeña razonable, pero ese uso exacto no se probó."],visual:{kind:"steps",title:"Suspiro cíclico, un ciclo",steps:[{label:"Ponte cómodo",text:"Siéntate o ponte de pie con comodidad y deja que los hombros caigan."},{label:"Inhala",text:"Inhala despacio por la nariz."},{label:"Completa",text:"Haz una segunda inhalación más corta por la nariz para llenar los pulmones."},{label:"Exhalación larga",text:"Exhala despacio por la boca hasta que sientas los pulmones vacíos."},{label:"Repite",text:"Continúa hasta cinco minutos y luego respira con normalidad."}],note:"Tal como lo describe Stanford Medicine. Detente y respira con normalidad si sientes mareo o malestar."}},{heading:"Seguridad y límites",paragraphs:["La orientación del NHS sobre los ejercicios de respiración es sencilla: detente si sientes molestias, quédate sentado un momento antes de ponerte de pie y habla primero con tu médico si tienes una afección respiratoria o del corazón. El hormigueo, el aturdimiento o el corazón acelerado indican que te estás excediendo; vuelve a respirar con normalidad. Este curso no enseña el método de hiperventilación rápida del estudio.","Si tienes ataques de pánico repetidos e inesperados, el NHS recomienda acudir a un médico. La terapia psicológica, como la terapia cognitivo-conductual, y, para algunas personas, la medicación son los tratamientos con respaldo científico. Respirar despacio puede ayudarte durante un ataque, pero no reemplaza esa atención. En una crisis, llama al número de emergencias de tu país."]}],example:{title:"Aylin, 27 años, abogada júnior",text:"Aylin tiene la costumbre de contener la respiración mientras lee correos hostiles de la parte contraria. Decide probar el suspiro cíclico durante cinco minutos cada mañana en el autobús durante un mes, y usar dos o tres ciclos antes de responder correos difíciles. Las primeras mañanas se siente rara y le preocupa que la gente la oiga. En la segunda semana ya puede hacerlo en silencio. Nota que, cuando llega un correo agresivo, la exhalación larga le da un momento de pausa antes de escribir. Sus respuestas se vuelven más cortas y más calmadas. Sigue sintiendo la sacudida de la rabia; solo que ya no decide lo que escribe. Un día se sintió aturdida, así que se detuvo y respiró con normalidad, y la siguiente vez fue más despacio."},practice:["Siéntate con comodidad y haz tres ciclos lentos: inhalación por la nariz, inhalación corta para completar, exhalación larga por la boca.","Si te sientes bien al hacerlo, pon un temporizador de cinco minutos y continúa a un ritmo relajado, deteniéndote si sientes mareo.","Después, valora de 0 a 10 qué tan calmado te sientes y elige un momento de mañana para usar dos o tres ciclos."],reflection:"¿En qué momento del día te ayudaría más una exhalación lenta y larga?",question:"¿Qué debes hacer si sientes mareo durante el suspiro cíclico?",options:["Detenerte, respirar con normalidad y quedarte sentado un momento.","Seguir adelante, porque el mareo significa que está funcionando.","Respirar más rápido para compensar."],correct:0,feedback:"Sí. El mareo o el hormigueo son una señal para detenerte y volver a respirar con normalidad. El método está pensado para ser suave y lento, no forzado.",takeaway:"Dos inhalaciones, una exhalación larga: una forma sencilla de relajar el cuerpo estés donde estés.",sources:["state-cyclic-sighing","state-stanford-sighing","state-nhs-breathing-tips","state-nhs-panic"],visual:{kind:"bars",title:"Aumento diario del ánimo positivo durante 28 días (5 minutos al día)",bars:[{label:"Suspiro cíclico",value:1.89,display:"1.89"},{label:"Respiración en caja",value:1.84,display:"1.84"},{label:"Hiperventilación cíclica",value:1.97,display:"1.97"},{label:"Meditación de atención plena",value:1.22,display:"1.22"}],note:"Aumento diario promedio de la puntuación de afecto positivo por grupo (Balban et al., 2023; 108 participantes). Los grupos de respiración se diferenciaron poco entre sí; combinados, superaron a la atención plena (1.91 frente a 1.22). Grupos pequeños, cuatro semanas, voluntarios sanos.",sourceId:"state-cyclic-sighing"},technique:{name:"Suspiro cíclico",origin:"David Spiegel, Andrew Huberman & Melis Yilmaz Balban · Stanford Medicine (2023)",steps:["Siéntate o ponte de pie con comodidad y relaja los hombros.","Inhala despacio por la nariz.","Añade una segunda inhalación más corta por la nariz para llenar los pulmones.","Exhala despacio y por completo por la boca, más tiempo que la inhalación.","Repite a un ritmo relajado hasta cinco minutos.","Detente y respira con normalidad si sientes mareo, hormigueo o malestar."],evidence:"En un pequeño ensayo de un mes con voluntarios sanos, cinco minutos al día de ejercicios de respiración, incluido el suspiro cíclico, elevaron el ánimo positivo más que la atención plena y redujeron la frecuencia respiratoria en reposo. No se ha probado como tratamiento de los trastornos de ansiedad ni de pánico.",sourceId:"state-stanford-sighing"},photo:{id:"1763713383838-5cd702c13160",alt:"Una mujer con los ojos cerrados, abrazándose suavemente en un bosque"}},{id:"state-4",title:"Cambia tu enfoque y tus preguntas",minutes:8,goal:"Detecta una pregunta que te repites y te desgasta. Cámbiala por otra que dirija tu atención hacia algo útil.",reading:["Robbins sostiene que gran parte del pensamiento consiste en hacer y responder preguntas, y que las preguntas que te haces habitualmente deciden en qué te enfocas. Pregúntate por qué siempre te pasa esto a ti, y tu mente buscará pruebas de que tienes mala suerte. Pregúntate cuál sería un paso útil, y buscará opciones. Sugiere tratar las preguntas como una práctica diaria: unas pocas por la mañana para marcar el rumbo y unas pocas por la noche para notar qué salió bien y qué aprendiste.","La investigación sobre la atención respalda la idea general, aunque con resultados más modestos. Un metaanálisis de Thomas Webb y sus colegas reunió 190 estudios sobre regulación emocional. La distracción, es decir, llevar deliberadamente la atención a otra cosa, ayudó un poco en promedio. Concentrarse en la situación que angustia y en lo que sientes al respecto empeoró ligeramente las cosas. Una buena pregunta es una forma suave de mover la atención. No se trata de ignorar problemas reales. Te orienta hacia la parte en la que puedes actuar, para que puedas volver a la parte difícil con más calma."],deeper:[{heading:"Qué dice la investigación sobre la atención",paragraphs:["En el metaanálisis de Webb, las estrategias de atención en conjunto tuvieron un efecto medio nulo, porque las dos direcciones se cancelan: apartar la atención ayudó un poco y dar vueltas al lado emocional de la situación perjudicó un poco.","La distracción es una herramienta de corto plazo. Te da tiempo, pero los problemas siguen necesitando resolverse después. Las preguntas que llevan a un siguiente paso hacen las dos cosas: cambian el enfoque y te hacen avanzar."],visual:{kind:"table",title:"Cómo influye dirigir la atención: efectos medios",columns:["Estrategia","Qué significa","Efecto promedio"],rows:[["Distracción","Llevar la atención a algo neutral o agradable","Beneficio pequeño (d = 0.27)"],["Concentración","Dar vueltas a la situación y a lo que sientes","Ligeramente peor (d = −0.26)"],["Estrategias de atención en conjunto","Ambas direcciones combinadas","Aproximadamente cero (d = 0.00)"]],note:"Webb, Miles y Sheeran (2012), 190 estudios, en su mayoría experimentos breves de laboratorio."}},{heading:"Preguntas de la mañana y de la noche",paragraphs:["Unos ejemplos con las palabras de ODA. Mañana: ¿Qué espero con ilusión hoy? ¿Qué agradezco hoy? ¿Cuál es la tarea que haría que hoy valiera la pena? Noche: ¿Qué di hoy? ¿Qué aprendí? ¿Qué salió mejor de lo que esperaba?","Si la respuesta honesta es “nada”, reduce la pregunta: ¿qué pequeña cosa estuvo bien? Una pregunta que exige fingir alegría puede sonar vacía. Una que invita a una respuesta honesta y concreta es más fácil de creer."]},{heading:"Errores comunes",paragraphs:["Usar las preguntas para negar un problema real, o convertirlas en un interrogatorio duro (“¿Qué te pasa?”), echa por tierra el propósito. Las mejores preguntas suenan como algo que preguntaría un amigo amable y práctico."]}],example:{title:"Javier, 38 años, representante de ventas",text:"Javier pierde un acuerdo en el que llevaba tres meses trabajando. De camino a casa se oye preguntarse: “¿Por qué siempre estropeo los acuerdos importantes?”, y nota que va recordando, uno tras otro, todos sus fracasos anteriores. En un semáforo en rojo prueba otra pregunta: “¿Qué puedo aprender de este acuerdo?” La respuesta llega despacio: nunca habló con la persona que de verdad aprueba los presupuestos. Luego, una segunda pregunta: “¿Qué paso puedo dar mañana?” Decide identificar quién toma las decisiones en los dos acuerdos que aún está negociando. Esa noche sigue decepcionado, pero duerme mejor, y a la mañana siguiente tiene una lista corta en lugar de una larga historia sobre su mala suerte."},practice:["Anota una pregunta que te haces a menudo cuando las cosas salen mal.","Reescríbela como una pregunta que apunte a aprender o a un paso que dependa de ti.","Elige tres preguntas de la mañana y hazlas mañana antes de mirar el móvil."],reflection:"¿Qué pregunta ha estado dirigiendo tu enfoque últimamente y adónde te ha estado llevando?",question:"¿Qué pregunta te ayuda más a ver qué opciones tienes?",options:["¿Por qué me pasa esto siempre a mí?","¿Quién es el responsable de arruinarme el día?","¿Cuál es un paso pequeño que puedo dar en los próximos diez minutos?"],correct:2,feedback:"Exacto. Una pregunta sobre un paso pequeño y posible dirige la atención hacia lo que puedes controlar. Las otras dos mandan a tu mente a buscar pruebas de mala suerte o a alguien a quien culpar.",takeaway:"Cambia la pregunta y cambias adónde va tu atención.",sources:["state-robbins-questions","state-regulation-meta"],visual:{kind:"compare",title:"Preguntas que desgastan y preguntas que orientan",left:{label:"Preguntas que desgastan",items:["¿Por qué me pasa esto siempre a mí?","¿Qué me pasa?","¿Quién tiene la culpa de esto?"]},right:{label:"Preguntas que orientan",items:["¿Qué puedo hacer en los próximos diez minutos?","¿Qué le diría a un amigo en este apuro?","¿Qué sigue yendo bien?","¿Qué puedo aprender de esto?"]},note:"Preguntas de ejemplo con las palabras de ODA, inspiradas en la idea de Tony Robbins de las preguntas que dan fuerza."},technique:{name:"Preguntas que dan fuerza",origin:"Tony Robbins · How to ask questions and better yourself every day, tonyrobbins.com",steps:["Nota la pregunta que tu mente repite cuando te sientes atascado o molesto.","Pregúntate hacia dónde está dirigiendo esa pregunta tu atención.","Sustitúyela por una pregunta que apunte al aprendizaje, la gratitud o un paso que dependa de ti.","Respóndela con honestidad y concreción, aunque la respuesta sea pequeña.","Prepara una lista breve de preguntas de la mañana y de la noche y úsalas a diario durante una semana."],evidence:"Ningún estudio ha probado directamente los conjuntos de preguntas de Robbins. La investigación sobre la atención muestra que adónde la diriges cambia las emociones: apartarla del lado angustiante de una situación ayudó un poco en promedio, mientras que detenerse en la emoción empeoró ligeramente las cosas.",sourceId:"state-robbins-questions"},photo:{id:"1543379232-77ee894c85dd",alt:"Una mujer con un gorro de punto frente al sol bajo"}},{id:"state-5",title:"Palabras y significado",minutes:9,goal:"Pon nombre a lo que sientes con una o dos palabras. Después, busca otra forma de interpretar la situación.",reading:["La tercera palanca es el lenguaje. Robbins sugiere notar las palabras intensas que sueles asociar con los momentos difíciles y cambiarlas por otras más suaves que sigan siendo honestas: frustrado en lugar de furioso, un contratiempo en lugar de un desastre. La investigación sobre nombrar las emociones apunta en la misma dirección. En un estudio de neuroimagen dirigido por Matthew Lieberman, elegir una palabra para la emoción de un rostro produjo menos actividad en la amígdala, una región que interviene en las respuestas de amenaza, que elegir una palabra para el género de la persona. Una revisión posterior sostuvo que poner las emociones en palabras tiende a reducir su intensidad, aunque las personas esperan que ocurra lo contrario.","El significado va un paso más allá. El psicólogo James Gross lo llama reevaluación cognitiva: cambiar cómo interpretas una situación para que cambie su impacto emocional. En su trabajo, la reevaluación redujo tanto la emoción como sus señales externas, mientras que simplemente ocultar una emoción no la redujo por dentro. Un metaanálisis de 190 estudios encontró que la reevaluación tenía un efecto promedio de pequeño a moderado, y que adoptar la perspectiva de otra persona tuvo un efecto algo mayor. Reevaluar no es fingir. Es buscar una interpretación que sea al menos igual de cierta y más útil."],deeper:[{heading:"Nombra y luego reformula",paragraphs:["Nombrar funciona mejor cuando es específico. “Mal” te dice poco; “avergonzado y un poco ansioso” te dice más y a menudo reduce algo la intensidad. Una vez que la emoción tiene nombre, puedes preguntarte qué más podría significar la situación.","No necesitas una palabra perfecta. Una etiqueta aproximada, dicha con calma, basta para empezar."],visual:{kind:"steps",title:"Nombra y reformula en un minuto",steps:[{label:"Pausa",text:"Haz una respiración lenta y nota que hay una emoción presente."},{label:"Nómbrala",text:"Dila o escríbela: estoy notando frustración y algo de preocupación."},{label:"Valórala",text:"Ponle un número de 0 a 10."},{label:"Reformula",text:"Pregunta: ¿qué más podría significar esto y cómo lo vería un amigo imparcial?"},{label:"Siguiente paso",text:"Elige una acción que encaje con el nuevo significado."}],note:"Combina el etiquetado emocional (Lieberman) y la reevaluación cognitiva (Gross)."}},{heading:"Suavizar no es negar",paragraphs:["El reto de vocabulario de Robbins no se ha estudiado directamente; las líneas de investigación más cercanas son el etiquetado emocional y la reevaluación. La clave es la exactitud. Llamar “un poco incómodo” a un peligro real no es reevaluar, es negar. Si alguien te está haciendo daño o una situación no es segura, lo correcto es actuar y buscar apoyo, no una palabra más suave.","Ocultar las emociones también es distinto de reformularlas. Suprimir una emoción redujo la expresión externa pero hizo poco por cómo se sentían las personas por dentro, y elevó el estrés fisiológico."]}],example:{title:"Priya, 45 años, administradora escolar",text:"Priya nota que describe casi todos los problemas de horarios como “un desastre total”, y que cada vez los hombros se le suben hacia las orejas. Durante diez días prueba un pequeño experimento. Cuando aparece un problema, primero nombra la emoción, casi siempre “frustrada y con prisas”, y luego se pregunta qué más podría significar. Un maestro que avisa que está enfermo pasa a ser “un problema de organización para la próxima hora” en lugar de “un desastre”. Cuando un padre envía un correo cortante, recuerda que probablemente es un padre preocupado, no un enemigo. Sigue ocupada y algunos días siguen siendo malos. Pero le contesta menos mal a su equipo, y el día nueve un colega le pregunta cómo hace para mantenerse tan tranquila."},practice:["Piensa en una situación de hoy que te molestó y nombra la emoción con una o dos palabras precisas.","Escribe una interpretación alternativa que sea al menos tan cierta como la primera.","Anota dos palabras intensas que uses a menudo y elige para cada una una alternativa más suave y precisa."],reflection:"¿Qué palabra usas más para describir un mal momento? ¿Refleja lo que ocurre?",question:"¿Cuál de estos es un ejemplo de reevaluación cognitiva?",options:["Sonreír en una reunión mientras te consume la rabia por dentro.","Pensar: este comentario tan directo es información sobre el borrador, no un veredicto sobre mí.","Decirte que no pasó nada malo cuando claramente sí pasó."],correct:1,feedback:"Correcto. La reevaluación cambia el significado de una situación de una manera que sigue siendo honesta. Ocultar una emoción es supresión, y fingir que no pasó nada es negación.",takeaway:"Ponle nombre y luego busca un significado más cierto y más útil.",sources:["state-robbins-words","state-affect-labeling","state-labeling-review","state-reappraisal-gross","state-regulation-meta"],visual:{kind:"bars",title:"Cambiar el significado frente a cambiar la respuesta",bars:[{label:"Tomar otra perspectiva",value:.45,display:"d = 0.45"},{label:"Reevaluar la situación",value:.36,display:"d = 0.36"},{label:"Reevaluar tu respuesta",value:.23,display:"d = 0.23"},{label:"Modular la respuesta (en conjunto)",value:.16,display:"d = 0.16"}],note:"Efectos promedio sobre los resultados emocionales en Webb, Miles y Sheeran (2012), 190 estudios. Suprimir la experiencia de una emoción promedió −0.04 y suprimir los pensamientos sobre el suceso −0.12. En su mayoría, estudios breves de laboratorio.",sourceId:"state-regulation-meta"},technique:{name:"Vocabulario transformacional",origin:"Tony Robbins · Harness the power of words, tonyrobbins.com",steps:["Durante unos días, nota las palabras intensas que usas para los momentos frustrantes o dolorosos.","Elige dos o tres que aparezcan con más frecuencia.","Elige para cada una un reemplazo más suave que siga siendo honesto, como frustrado en lugar de furioso.","Cuando te venga la palabra de siempre, di la nueva en su lugar, en voz alta o en tu cabeza.","Mantenlo durante diez días y nota cualquier cambio en cómo se sienten los momentos intensos."],evidence:"El reto de vocabulario en sí no se ha probado. La investigación relacionada respalda dos de sus partes: poner las emociones en palabras tiende a reducir su intensidad, y reinterpretar una situación tuvo un efecto promedio de pequeño a moderado sobre las emociones. Ocultar las emociones hace poco por cómo te sientes por dentro.",sourceId:"state-robbins-words"},photo:{id:"1534330207526-8e81f10ec6fc",alt:"Un hombre de pie, en silencio, frente a una ventana luminosa"}},{id:"state-6",title:"Preparación matutina y declaraciones con cuerpo y voz",minutes:10,goal:"Prepara una rutina matutina de diez minutos y una declaración que puedas decir en voz alta sin sentir que te engañas.",reading:["Robbins empieza sus días con lo que llama priming, una rutina de menos de diez minutos. Según sus materiales y un resumen de CNBC, combina rondas de respiración enérgica con movimientos de brazos, tres momentos de gratitud de tu pasado, presente o futuro, una visualización de luz que llena el cuerpo y la concentración en tres metas como si ya estuvieran cumplidas. La versión de ODA conserva la estructura y propone empezar con respiración lenta, ya que respirar rápido puede causar mareos. Su propósito es simple: decidir tu estado antes de que lo decida tu bandeja de entrada.","Robbins distingue las declaraciones con cuerpo y voz de las afirmaciones. Una afirmación es una frase que dices. En lo que llama incantation, acompañas esa frase con la voz, la postura, el movimiento y la convicción. Aquí lo llamamos declaración con cuerpo y voz. Esa diferencia importa, pero también importa la credibilidad. En experimentos de Joanne Wood y sus colegas, las personas con baja autoestima que repitieron 16 veces “Soy una persona digna de cariño” se sintieron peor después, mientras que las de alta autoestima se sintieron un poco mejor. Cuando una afirmación está lejos de lo que crees, tu mente te contradice. Elige declaraciones concretas, creíbles y ligadas a una acción."],deeper:[{heading:"Lo que muestra la investigación sobre la gratitud",paragraphs:["Los ejercicios de gratitud ayudan, pero de forma modesta. Un metaanálisis de 25 muestras aleatorizadas encontró que expresar gratitud mejoraba el bienestar con un efecto promedio pequeño. Otro, de 27 estudios, encontró efectos pequeños sobre los síntomas de depresión y ansiedad, y sus autores recomiendan tratamientos mejor respaldados para esas afecciones.","En tu priming puedes hacerlo concreto: imagina una escena real, como la risa de un amigo o un café tranquilo, y quédate con ella durante unas cuantas respiraciones."],visual:{kind:"bars",title:"Expresar gratitud y bienestar: efectos promedio",bars:[{label:"Bienestar en general",value:.22,display:"g = 0.22"},{label:"Satisfacción con la vida",value:.22,display:"g = 0.22"},{label:"Emociones positivas",value:.21,display:"g = 0.21"},{label:"Felicidad",value:.16,display:"g = 0.16"}],note:"Kirca, Malouff y Meynadier (2023): 25 muestras aleatorizadas, 6,745 participantes, comparadas con condiciones neutras. Efectos pequeños.",sourceId:"state-gratitude-expressed"}},{heading:"¿Afirmación o declaración con cuerpo y voz?",paragraphs:["El tercer estudio de Wood ofrece una pista: las personas con baja autoestima mejoraron cuando se les permitió notar que una afirmación positiva era cierta y a la vez no del todo cierta. Dejar espacio para la duda reduce la discusión interna.","Estas declaraciones con cuerpo y voz no se han estudiado por sí mismas. Nuestra versión toma de Robbins el uso de la voz, la postura y el movimiento. La investigación aporta la importancia de que las palabras resulten creíbles."],visual:{kind:"compare",title:"Una afirmación simple o una declaración que puedes creer",left:{label:"Afirmación simple que puede salir mal",items:["Una afirmación absoluta, como “soy perfecto”.","Repetida de forma pasiva mientras tu mente discute.","Ignora por completo la duda.","No está ligada a nada que vayas a hacer."]},right:{label:"Declaración que puedes creer",items:["Específica y creíble, como “hoy puedo hacer esa llamada aunque me dé miedo”.","Dicha en voz alta con postura erguida y una respiración firme.","Deja espacio para la duda: “aunque una parte de mí no esté segura”.","Ligada a una acción que harás hoy."]},note:"Basado en la distinción de Robbins y en Wood et al. (2009). Las frases de ejemplo son de ODA."}},{heading:"Sobre la visualización de la luz y la respiración rápida",paragraphs:["Imaginar luz moviéndose por tu cuerpo puede ser una imagen que te calme. Úsala si te ayuda. No puede curar enfermedades y no es una razón para retrasar la atención médica. La respiración rápida y enérgica puede marearte; mantén las rondas cortas, detente si sientes mareo u hormigueo, y nunca la hagas mientras conduces, en el agua o de pie en un lugar donde podrías caerte."]}],example:{title:"Sam, 52 años, conductor de autobús",text:"Sam empieza turnos tempranos y antes pasaba sus primeros veinte minutos mirando noticias en el móvil en la sala de descanso, llegando al volante ya irritado. Prueba un priming de diez minutos en la mesa de la cocina antes de salir. Dos minutos de suspiro cíclico, ya que respirar rápido lo mareó la única vez que lo intentó. Tres minutos con tres escenas de gratitud: el dibujo de su nieta, el amanecer sobre la cochera, el café de su esposa. Tres minutos imaginando que el recorrido sale bien y que mantiene la paciencia con el pasajero que siempre discute por el cambio. Luego se pone de pie, echa los hombros hacia atrás y dice: “Hoy puedo mantener la calma, incluso cuando los demás la pierdan”. Nota que tarda un poco más en perder la paciencia, y mantiene la rutina cuatro mañanas de cada cinco."},practice:["Escribe tres escenas concretas de gratitud de tu pasado, presente o futuro, una línea cada una.","Escribe una declaración concreta y creíble, ligada a una acción que harás hoy. La dirás con cuerpo y voz.","Pon un temporizador de diez minutos mañana por la mañana y haz los pasos del priming antes de mirar el móvil."],reflection:"¿Qué te dirías por la mañana que de verdad pudieras creer?",question:"¿Qué encontraron Wood y sus colegas sobre repetir una autoafirmación positiva?",options:["Ayudó a todos, sin importar la autoestima.","Hizo que las personas con baja autoestima se sintieran peor, mientras que las de alta autoestima se sintieron un poco mejor.","No tuvo ningún efecto en nadie, en un sentido ni en otro."],correct:1,feedback:"Correcto. Las afirmaciones que están lejos de lo que crees pueden provocar una discusión interna y salir mal, sobre todo en personas que se sienten mal consigo mismas. Las palabras concretas y creíbles te resultan más fáciles de aceptar.",takeaway:"Empieza el día eligiendo cómo quieres sentirte y con palabras que puedas creer.",sources:["state-robbins-priming","state-priming-cnbc","state-robbins-rituals","state-positive-self-statements","state-gratitude-expressed","state-gratitude-meta","state-cyclic-sighing","state-nhs-breathing-tips"],visual:{kind:"steps",title:"Priming de diez minutos, versión ODA",steps:[{label:"Respira (2 min)",text:"Suspiro cíclico como primera opción; si pruebas rondas más rápidas, mantenlas cortas y detente si te mareas."},{label:"Gratitud (3 min)",text:"Revive tres momentos concretos de tu pasado, presente o futuro."},{label:"Visualiza (3 min)",text:"Imagina que hoy sale bien, incluyendo cómo manejas un obstáculo probable."},{label:"Tres resultados (1 min)",text:"Nombra los tres resultados que harían que hoy valiera la pena."},{label:"Declaración con cuerpo y voz (1 min)",text:"Ponte erguido y di en voz alta un compromiso creíble."}],note:"Adaptado del priming de Tony Robbins. La rutina completa no se ha estudiado. Sus componentes muestran efectos pequeños o tienen respaldo parcial."},technique:{name:"Priming",origin:"Tony Robbins · Train your brain in minutes, tonyrobbins.com",steps:["Siéntate derecho con los ojos cerrados o la mirada baja.","Respira durante unos dos minutos, despacio como primera opción; detente si sientes mareo.","Recuerda tres momentos concretos por los que estás agradecido y siente cada uno.","Si quieres, imagina una luz o una sensación de calor que recorra tu cuerpo y te calme.","Enfócate en tres resultados de hoy e imagínalos cumplidos, incluyendo cómo manejas un obstáculo.","Ponte de pie y di en voz alta, con energía, una declaración concreta y creíble, acompañándola con el cuerpo y la voz."],evidence:"La rutina de priming completa no se ha estudiado. Sus partes tienen respaldo parcial: respirar despacio elevó el ánimo positivo en un pequeño ensayo de un mes, los ejercicios de gratitud muestran efectos promedio pequeños y las autoafirmaciones positivas pueden salir mal en personas con baja autoestima. Las imágenes de luz sanadora no pueden tratar enfermedades.",sourceId:"state-robbins-priming"},photo:{id:"1552838671-0e948f9f69b5",alt:"Una mujer sentada en el césped verde mirando hacia el sol de la mañana"}},{id:"state-7",title:"El proceso Dickens y los nuevos estándares",minutes:11,goal:"Usa una versión breve y amable del proceso Dickens para ver qué te cuesta una conducta habitual. Después, fija un nuevo estándar con una pequeña acción diaria.",reading:["Robbins bautizó el proceso Dickens en honor a los tres fantasmas de Cuento de Navidad. Eliges una creencia limitante o un patrón y luego miras lo que te ha costado en el pasado, lo que te cuesta a ti y a tus seres queridos ahora y lo que te costará dentro de uno, tres, cinco y diez años si nada cambia. Después imaginas el futuro si lo cambias. Robbins lo dirige con gran intensidad para impulsar el cambio. ODA usa una versión más suave: breve, escrita, basada en hechos, y que dedica la mayor parte del tiempo al futuro que quieres y a un primer paso.","Robbins también sostiene que el cambio duradero viene de elevar tus estándares, convirtiendo un “debería” vago en un “debo” claro. La investigación sugiere cómo lograrlo sin crueldad. Un metaanálisis sobre el contraste mental, que consiste en imaginar un futuro deseado y luego los obstáculos en el camino, combinado con planes «si… entonces…», encontró un efecto promedio de pequeño a medio sobre el logro de metas. Y en cuatro experimentos de Juliana Breines y Serena Chen, tratar un fracaso con autocompasión aumentó la motivación para mejorar, incluido más tiempo de estudio después de un examen suspendido. No necesitas avergonzarte para cambiar."],deeper:[{heading:"Por qué la amabilidad gana a la vergüenza",paragraphs:["La autocrítica dura puede parecer el precio del cambio. Sin embargo, en los estudios de Breines y Chen, la autocompasión hizo que las personas estuvieran más dispuestas a ver una debilidad como algo que se puede cambiar, a reparar el daño y a esforzarse.","La autocompasión no es eludir tu responsabilidad. Es mantener un estándar alto tratándote como alguien que merece ayuda."],visual:{kind:"compare",title:"Dos formas de revisar un viejo patrón",left:{label:"Revisión movida por la vergüenza",items:["Soy patético por seguir haciendo esto.","Una gran promesa sin un plan.","Un tropiezo significa que volví a fracasar."]},right:{label:"Revisión autocompasiva",items:["Esto importa, y soy humano.","Un estándar y una pequeña acción diaria.","Un tropiezo es información; empiezo de nuevo mañana."]},note:"Basado en Breines y Chen (2012), cuatro experimentos sobre autocompasión y motivación."}},{heading:"Convertir un “debería” en un estándar",paragraphs:["Es más fácil mantener un estándar si lo concretas. Decide cuál será, identifica el obstáculo más probable y prepara un plan «si… entonces…». Después, haz una pequeña acción diaria que lo cumpla y revisa cada semana qué ha pasado, sin castigarte."],visual:{kind:"cycle",title:"Cómo se mantiene un nuevo estándar",nodes:[{label:"Decide",text:"Un estándar claro, como: respondo a mi familia antes que a mi bandeja de entrada."},{label:"Planea",text:"Si aparece el obstáculo probable, entonces hago algo concreto."},{label:"Actúa",text:"La acción diaria más pequeña que demuestre el estándar."},{label:"Revisa",text:"Mira con amabilidad lo que funcionó y ajusta."}],center:"Nuevo estándar",note:"El contraste mental con planes «si… entonces…» mostró un efecto promedio de pequeño a medio sobre el logro de metas (g = 0.336) en un metaanálisis de 21 estudios."}},{heading:"Cuándo saltarte este ejercicio",paragraphs:["Mirar los costes puede remover emociones fuertes. Si estás de duelo, te sientes muy decaído o deprimido, salta el paso de los costes futuros y ve directo al futuro que quieres, o deja esta lección para otro día y habla con alguien de confianza o con un profesional. Si tienes pensamientos de hacerte daño, llama ahora mismo al número de emergencias de tu país."]}],example:{title:"Elena, 36 años, diseñadora gráfica",text:"Elena lleva años diciéndose que actualizará su portafolio “cuando me sienta lista”. Un domingo por la tarde pone un temporizador de veinte minutos y escribe el proceso Dickens suave. Pasado: dos ofertas de trabajo a las que nunca se presentó. Presente: se siente atascada en el trabajo y resentida, aunque no lo expresa. Futuro sin cambios: dentro de cinco años, el mismo escritorio y la misma historia. Nota que se le aprieta el pecho, así que sigue adelante y dedica la mayor parte del tiempo al futuro que quiere: un puesto en un estudio y un trabajo que muestre con orgullo. Su nuevo estándar es trabajar en su portafolio antes que en las redes sociales las mañanas entre semana. Su primera acción son quince minutos el lunes. El miércoles no lo hace, se encoge de hombros y vuelve a empezar el jueves."},practice:["Elige un patrón o una creencia que te frena y escríbelo en una frase.","Escribe dos o tres líneas basadas en hechos sobre los costes pasados, presentes y futuros, y luego el doble sobre el futuro que quieres.","Conviértelo en un estándar con un plan «si… entonces…» y una pequeña acción que harás mañana."],reflection:"¿Cuál es un “debería” de tu vida que está listo para convertirse en un estándar?",question:"¿Qué hace que la versión de ODA del proceso Dickens sea distinta de limitarte a castigarte por tus errores?",options:["Es breve y basada en hechos, y termina con el futuro que quieres y un primer paso.","Se detiene en cada error hasta que te sientas lo bastante mal como para cambiar.","Se salta los costes y solo imagina el éxito."],correct:0,feedback:"Sí. Ver los costes con claridad puede motivarte a cambiar. La versión suave mantiene esa revisión breve y basada en hechos, y pone la mayor parte del esfuerzo en el futuro que quieres y en un primer paso concreto. La investigación sugiere que la autocompasión apoya el cambio mejor que la vergüenza.",takeaway:"Mira el coste con claridad, luego elige un nuevo estándar y demuéstralo con una pequeña acción diaria.",sources:["state-robbins-dickens","state-robbins-standards","state-mental-contrasting","state-self-compassion-motivation"],visual:{kind:"table",title:"El proceso Dickens suave",columns:["Etapa","Pregunta","Trátate con amabilidad"],rows:[["Pasado","¿Qué me ha costado este patrón hasta ahora?","Escribe hechos, no insultos."],["Presente","¿Qué nos está costando a mí y a las personas que quiero ahora?","Bastan dos o tres líneas."],["Futuro, sin cambios","¿Adónde lleva dentro de uno, cinco y diez años?","Detente si te resulta abrumador."],["Futuro, con cambios","¿Qué puedo hacer realidad si lo cambio?","Dedica aquí la mayor parte del tiempo."],["Primer paso","¿Qué acción de mañana demuestra el nuevo estándar?","Hazla lo bastante pequeña como para cumplirla."]],note:"Adaptado del proceso Dickens de Tony Robbins. El proceso en sí no se ha estudiado."},technique:{name:"El proceso Dickens (versión suave)",origin:"Tony Robbins · Unlocking potential, tonyrobbins.com",steps:["Nombra en una sola frase una creencia limitante o un patrón.","Escribe brevemente lo que te ha costado en el pasado, con hechos y no con insultos.","Escribe lo que te cuesta ahora a ti y a las personas que quieres.","Imagina adónde lleva dentro de uno, cinco y diez años si nada cambia, y detente si se vuelve abrumador.","Dedica la mayor parte del tiempo a imaginar el futuro si lo cambias, con detalle concreto.","Escribe una nueva creencia o estándar y una pequeña acción que harás mañana."],evidence:"El proceso Dickens en sí no se ha estudiado. Un método relacionado, imaginar un futuro deseado y luego los obstáculos, más planes «si… entonces…», tiene efectos promedio de pequeños a medios sobre el logro de metas. La autocompasión tras un fracaso elevó la motivación para mejorar en experimentos; no hay evidencia de que avergonzarte funcione mejor.",sourceId:"state-robbins-dickens"},photo:{id:"1633210155534-e43f00c1d627",alt:"Una mujer sentada sobre una roca al aire libre, escribiendo en un cuaderno"}}]},k=Object.freeze(Object.defineProperty({__proto__:null,COURSE:C,SOURCES:S},Symbol.toStringTag,{value:"Module"})),P=[{id:"stoic-epictetus-iep",title:"Keith H. Seddon · Epictetus (Internet Encyclopedia of Philosophy)",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epicteto (c. 55–135 d. C.) nació esclavo en Hierápolis, fue liberado más tarde y enseñó filosofía en Nicópolis, Grecia; su alumno Arriano recogió sus enseñanzas en los Discursos y en el Manual. El artículo explica su distinción central entre lo que depende de nosotros (nuestras opiniones, intenciones, deseos, aversiones y el uso que hacemos de las impresiones) y lo que no (el cuerpo, las posesiones, la reputación, la salud, el estatus y los resultados de nuestras acciones), y su enseñanza de que a las personas las perturban sus juicios sobre los hechos y no los hechos en sí.",limitation:"Es una descripción enciclopédica de la filosofía, no investigación psicológica; no trata la terapia moderna. Se consultó la página; los textos antiguos se parafrasean en este curso, no se citan."},{id:"stoic-seneca-iep",title:"Robert Wagoner · Seneca (Internet Encyclopedia of Philosophy)",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Séneca (c. 4 a. C.–65 d. C.) fue un filósofo estoico que fue tutor del joven Nerón y más tarde uno de sus consejeros. El artículo explica la visión estoica, tal como la presenta Séneca, de que emociones como la ira implican juicios de valor: el primer movimiento ante una situación es involuntario, pero enojarse requiere dar por buena la idea de que te han agraviado.",limitation:"Es una descripción enciclopédica, no investigación. No describe el repaso nocturno de Séneca ni su consejo de anticipar la adversidad; en este curso esas prácticas se apoyan en el manual de la Semana Estoica. Se consultó la página."},{id:"stoic-week-handbook",title:"Stoicism Today (Gill, Ussher, Sellars, LeBon, Evans, Garratt, Robertson) · Stoic Week 2016 Handbook (Modern Stoicism)",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"El manual enseña ejercicios estoicos diarios junto con sus fuentes antiguas: la dicotomía del control del Manual de Epicteto (preguntarse ante cada situación si depende de ti); una meditación matutina que ensaya las dificultades probables del día y planea buenas respuestas; la premeditación de la adversidad hecha de forma realista, con una intensidad que puedas tolerar y sin rumiar; un repaso nocturno de cinco a diez minutos basado en Séneca y Epicteto (qué hice mal, qué hice bien, qué podría hacer de otra manera, revisado como lo haría un amigo y no con dureza); y la mirada desde lo alto de Marco Aurelio. Rechaza la idea de que el estoicismo signifique reprimir las emociones y describe la psicología estoica como una influencia en la terapia cognitivo-conductual moderna.",limitation:"Es una guía de práctica escrita por filósofos, especialistas en el mundo clásico y terapeutas, no un ensayo. Indica que no sustituye el consejo ni el tratamiento médicos y que el curso no es adecuado para personas con problemas graves de salud mental, como depresión clínica o TEPT. Se consultó el PDF."},{id:"stoic-week-report",title:"Tim LeBon · Report on Stoic Week 2021 (Modern Stoicism)",url:"https://modernstoicism.com/wp-content/uploads/2022/01/Stoic-Week-2021-Results-Tim-LeBon-1-1.pdf",type:"research",finding:"1,369 personas completaron cuestionarios válidos al inicio del curso en línea gratuito de siete días y 459 al final (una tasa de finalización del 33%); los participantes dedicaron en promedio 42 minutos al día. Entre quienes lo terminaron, el bienestar pleno subió un 11.5%, la satisfacción con la vida un 14.5% y las emociones positivas un 13%, mientras que las emociones negativas bajaron un 21%.",limitation:"Es un informe de los organizadores del curso. Los participantes eligieron tomar parte, no hubo grupo de control, todas las medidas se basaban en lo que contaban los participantes y dos tercios de quienes empezaron no completaron el cuestionario final, así que no puede demostrar que la práctica estoica causara los cambios. Se consultó el PDF."},{id:"stoic-kross-distancing",title:"Kross & Ayduk · 2017 · Self-distancing: theory, research, and current directions (Advances in Experimental Social Psychology, vol. 55)",url:"https://sites.lsa.umich.edu/emotion-selfcontrol-psych/wp-content/uploads/sites/1322/2017/09/Self-distancing-theory-research-future.pdf",type:"research",finding:"La revisión resume experimentos que comparan la reflexión inmersa en uno mismo (revivir un hecho con tus propios ojos) con la reflexión distanciada (verte desde lejos, como un observador externo). El distanciamiento redujo la emoción negativa y la rumiación, hizo que la reflexión pasara de repetir los detalles a comprender el hecho, aceleró la recuperación de la presión arterial, redujo las respuestas agresivas y favoreció un razonamiento más sabio; sus beneficios se mantuvieron en el tiempo mejor que los de la distracción. Imaginar cómo te sentirás dentro de diez años redujo el malestar, al parecer porque resalta que los sentimientos pasan. Usar tu propio nombre o “tú” en el diálogo interno produjo beneficios similares. Los autores relacionan la idea en parte con el concepto de distanciamiento de Aaron Beck en la terapia cognitiva.",limitation:"Son sobre todo estudios breves de laboratorio, a menudo con estudiantes. Los beneficios fueron más claros en las personas con más malestar y pequeños o ausentes en algunas muestras con poco malestar; los autores distinguen entre distanciarse para comprender los sentimientos y distanciarse para evitarlos. Se consultó el PDF del capítulo."},{id:"stoic-kross-self-talk",title:"Kross et al. · 2014 · Self-talk as a regulatory mechanism: how you do it matters (Journal of Personality and Social Psychology)",url:"https://doi.org/10.1037/a0035173",type:"research",finding:"Siete estudios con 585 participantes: reflexionar sobre uno mismo con pronombres que no están en primera persona y con el propio nombre, en lugar de “yo”, aumentó el autodistanciamiento. En tareas de primera impresión y de hablar en público, este grupo rindió mejor, sintió menos malestar y rumió menos después, y valoró futuras situaciones de estrés más como desafíos que como amenazas. Un metaanálisis de los estudios halló que los beneficios no dependían de la ansiedad social.",limitation:"Tareas breves de laboratorio; no se evaluaron los efectos a largo plazo ni los clínicos. Solo se leyó el resumen (a través de Europe PMC)."}],A={id:"stoic",title:"¿Te agota controlarlo todo? Cómo mantenerte firme cuando todo cambia",subtitle:"6 lecciones de 8 a 9 minutos. Usa ejercicios estoicos para distinguir lo que depende de ti.",description:"¿Qué cambiaría si gastaras tu energía solo en lo que de verdad depende de ti? Este curso convierte cinco prácticas estoicas en ejercicios diarios breves y contrasta cada una, con honestidad, con la psicología moderna.",scope:"Para adultos que quieren responder con más serenidad al estrés, los contratiempos y la incertidumbre. Aquí el estoicismo no significa reprimir las emociones ni poner buena cara; los sentimientos son bienvenidos, y la práctica trata de lo que haces a continuación. Es un curso educativo con ejercicios personales. No es terapia ni sustituye un tratamiento. Si vives con ansiedad, depresión, trauma o preocupaciones intrusivas, algunos ejercicios, sobre todo el de imaginar contratiempos, quizá no sean adecuados para ti; trabaja con un profesional cualificado. Si estás en una crisis o piensas en hacerte daño, llama ahora al número de emergencias de tu zona.",outcome:"Una forma de separar lo que depende de ti de lo que no ante cualquier preocupación, una forma de detectar el juicio que hay entre un hecho y tu reacción, una versión suave de ensayar los contratiempos, una técnica para tomar distancia en los momentos de tensión, un repaso nocturno de cinco minutos y una pequeña decisión que pones en práctica hoy.",photo:{id:"1439066615861-d1af74d74000",alt:"Un muelle de madera en un lago de montaña en calma"},lessons:[{id:"stoic-1",title:"Lo que depende de ti",minutes:8,goal:"Separa, en una preocupación actual, lo que depende de ti de lo que no. Dedica tu energía a la primera lista.",reading:["Epicteto nació esclavo en el siglo I y más tarde enseñó filosofía en Grecia. Su alumno Arriano puso por escrito sus lecciones en dos obras, los Discursos y un breve Manual. La idea con la que se abre el Manual es sencilla y exigente. Algunas cosas dependen de nosotros: nuestros juicios, nuestras intenciones, lo que queremos y lo que evitamos, y cómo elegimos actuar. Otras no: nuestro cuerpo, nuestras posesiones, nuestra reputación, las demás personas y, sobre todo, los resultados de nuestras acciones. Epicteto sostenía que gran parte de nuestro malestar viene de tratar la segunda lista como si perteneciera a la primera.","Esto no es una invitación a que deje de importarte lo que ocurre. Una entrevista de trabajo puede importarte mucho. Pero la oferta no depende de ti; tu preparación, tu honestidad durante la entrevista y lo que hagas después, sí. Si te preocupas solo por la oferta, no puedes hacer mucho con esa preocupación. Si la orientas hacia la preparación, puedes convertirla en algo útil. Los maestros estoicos modernos consideran este el ejercicio más básico de la tradición: pregúntate ante cada situación si depende de ti y pon tu esfuerzo donde la respuesta sea sí. Con lo demás intentas no aferrarte tanto, no porque no importe, sino porque aferrarte a ello no ayuda."],deeper:[{heading:"Por qué funciona",paragraphs:["La preocupación tiende a dar vueltas alrededor de los resultados: si les gustaré, si funcionará, si ocurrirá. Los resultados dependen de muchas cosas que no puedes ver ni dirigir, así que pensar en ellos rara vez tiene un final. Las acciones son distintas. Una acción tiene un primer paso, un momento y un lugar, de modo que pensar en ella puede terminar en hacerla.","El ejercicio no elimina la sensación incómoda. Te ayuda a dirigirla hacia algo útil. Esa idea práctica une este antiguo ejercicio con la investigación moderna sobre planificación que conocerás en la última lección de este curso."],visual:{kind:"steps",title:"Qué depende de ti",steps:[{label:"Nómbrala",text:"Escribe la preocupación en una frase sencilla."},{label:"Divídela",text:"Dibuja dos columnas: depende de mí y no depende de mí."},{label:"Revisa la primera columna",text:"Deja ahí solo tus propios juicios, intenciones y acciones; pasa los resultados al otro lado."},{label:"Elige",text:"Escoge un elemento de la primera columna para dar un paso hoy."},{label:"Suelta",text:"Ante lo que no depende de ti, recuerda que ya has hecho tu parte."}],note:"Nuestra versión paso a paso de la dicotomía del control, tal como se enseña en el manual de la Semana Estoica."}},{heading:"Errores comunes",paragraphs:["El primer error es poner los resultados en la primera columna. Conseguir el empleo, caer bien, recuperarte de una enfermedad: puedes influir en ello, pero no lo decides tú. Lo que decides es tu esfuerzo, tu actitud y tu siguiente paso. Mantener esas cosas separadas es todo el ejercicio.","El segundo error es usar esta idea para justificar la pasividad. Si está ocurriendo algo injusto, tu respuesta depende de ti, y esa respuesta puede incluir alzar la voz, pedir ayuda o irte. La dicotomía del control te pide actuar bien, no encogerte de hombros."]}],example:{title:"Leyla, 31 años, enfermera",text:"Leyla tenía una evaluación de desempeño el viernes y pasó la noche del miércoles repasando todo lo que su jefa podría decirle. A las diez tomó una hoja de papel y trazó una línea por el medio. A la derecha escribió lo que no dependía de ella: el humor de su jefa, el presupuesto para los aumentos y cómo había descrito una compañera un turno que salió mal. A la izquierda escribió lo que sí: llevar los comentarios de pacientes que había guardado, hacer una pregunta clara sobre su siguiente formación y explicar el turno difícil con calma y sin ponerse a la defensiva. Guardó la hoja en su bolso y se fue a dormir. La preocupación no desapareció, pero se había reducido a tres tareas concretas. El viernes la evaluación tuvo comentarios positivos y negativos. Salió sabiendo que había hecho su parte."},practice:["Escribe en una sola frase una preocupación que haya estado en tu mente esta semana.","Divídela en dos columnas, lo que depende de ti y lo que no, y pasa a la derecha cualquier resultado que hayas puesto a la izquierda.","Encierra en un círculo un elemento de la columna izquierda y decide cuándo hoy actuarás sobre él."],reflection:"¿En qué estás gastando energía sin que dependa de ti decidir el resultado?",question:"En la distinción de Epicteto, ¿cuál de estas cosas depende de ti?",options:["Que tu solicitud sea aceptada.","El cuidado con el que prepares tu solicitud.","Lo que otras personas piensen de tu solicitud."],correct:1,feedback:"Tu preparación es una acción tuya. La aceptación y las opiniones de los demás dependen de cosas fuera de ti, aunque tu esfuerzo pueda influir en ellas.",takeaway:"El resultado puede importarte. Dedica el esfuerzo a la parte que depende de ti.",sources:["stoic-epictetus-iep","stoic-week-handbook"],visual:{kind:"compare",title:"¿Depende de ti o no?",left:{label:"Depende de ti",items:["Tus juicios sobre lo ocurrido","Tus intenciones y tu esfuerzo","Cómo respondes, incluido lo que dices a continuación"]},right:{label:"No depende de ti",items:["Las decisiones y opiniones de otras personas","Los resultados, la reputación y el estatus","La salud, las posesiones y buena parte de lo que le pasa a tu cuerpo"]},note:"Resumen del Manual de Epicteto según lo describen la Internet Encyclopedia of Philosophy y el manual de la Semana Estoica."},technique:{name:"Qué depende de ti",origin:"Epicteto · Manual, recogido por Arriano (principios del siglo II), tal como se enseña en el Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Escribe la situación que te inquieta.","Pregúntate por cada parte: ¿depende de mí?","Enumera lo que depende de ti como acciones, juicios o intenciones, no como resultados.","Elige una de esas acciones y decide cuándo la harás.","Recuérdate que lo demás no te toca decidirlo y deja que tu atención vuelva a la acción."],evidence:"La distinción es una herramienta filosófica, no un tratamiento probado. Forma parte de la Semana Estoica, cuyos participantes que se ofrecieron por iniciativa propia informaron de un mayor bienestar en encuestas sin control, pero ningún estudio controlado ha evaluado el ejercicio sobre lo que depende de ti por sí solo.",sourceId:"stoic-week-handbook"},photo:{id:"1507525428034-b723cf961d3e",alt:"Una orilla en calma donde el agua clara se une con la arena"}},{id:"stoic-2",title:"La historia entre el hecho y el sentimiento",minutes:9,goal:"Detecta el juicio que se sitúa entre algo que sucede y lo que sientes al respecto.",reading:["Epicteto enseñaba que a las personas las perturba menos lo que sucede que los juicios que hacen sobre ello. Un mensaje sin responder es solo un mensaje sin responder. El dolor viene del veredicto que añadimos: me están ignorando, hice algo mal, no importo. Los estoicos practicaban hacer una pausa antes de aceptar un veredicto así. Séneca describía la primera sacudida de ira como algo involuntario, parecido a un sobresalto. Según su relato, la ira propiamente dicha empieza solo cuando aceptamos que nos han tratado injustamente y que devolver el golpe es lo correcto. El sobresalto surge solo; aceptar esa interpretación depende de ti.","Casi dos mil años después, el psicólogo Albert Ellis desarrolló una terapia a partir de una idea parecida. Su modelo ABC dice que un hecho activador (A) lleva a consecuencias emocionales y de conducta (C) a través de creencias (B), en especial exigencias rígidas y conclusiones catastróficas. Aaron Beck, el otro fundador de la terapia cognitiva, ayudó a las personas a tomar distancia y ver un pensamiento como un pensamiento y no como un hecho. El equipo de la Semana Estoica, que incluye terapeutas cognitivos, describe la psicología estoica como una influencia en la terapia cognitivo-conductual (TCC) moderna. La idea no es no sentir nada. Es notar la historia, ponerla a prueba y elegir una que se ajuste mejor a los hechos."],deeper:[{heading:"No reprimir, sino examinar",paragraphs:["Una imagen común del estoicismo es la del rostro imperturbable: no sentir nada, no mostrar nada. Los antiguos estoicos sí aspiraban a librarse de lo que llamaban pasiones, emociones construidas sobre juicios falsos. Pero el manual de la Semana Estoica señala que Marco Aurelio admiraba a uno de sus maestros por estar libre de pasiones y lleno de afecto al mismo tiempo. La calma estoica no es insensibilidad.","La distinción de Séneca ayuda aquí. El primer sobresalto de miedo o de ira no es un fallo; es un cuerpo haciendo su trabajo. La práctica empieza en el momento siguiente, cuando te preguntas qué te estás diciendo y si es verdad. Reprimir la emoción deja esa pregunta sin responder. Examinar el juicio te ayuda a responderla."]},{heading:"Lo que dice la investigación y lo que no",paragraphs:["La TCC, que nació en parte de estas ideas, cuenta con un amplio respaldo de investigación como terapia. Una revisión de 269 metaanálisis halló la evidencia más sólida para los trastornos de ansiedad, los problemas de ira y el estrés general, entre otros. Eso es evidencia de una terapia con un profesional cualificado, no de la lectura de una lección.","El estoicismo en sí se ha estudiado sobre todo a través de la Semana Estoica, un curso en línea gratuito de siete días. En 2021, 1,369 personas completaron el cuestionario inicial y 459 el final. Quienes lo terminaron informaron de mayor bienestar y menos emociones negativas. Pero los participantes eligieron tomar parte, no hubo grupo de control, dos tercios no completaron el cuestionario final y todo se basó en lo que contaban los participantes. Estas cifras muestran lo que dijeron quienes terminaron, no lo que causa el estoicismo."],visual:{kind:"bars",title:"Semana Estoica 2021: cambios informados por quienes terminaron",bars:[{label:"Bienestar pleno",value:11.5,display:"+11.5%"},{label:"Satisfacción con la vida",value:14.5,display:"+14.5%"},{label:"Emociones positivas",value:13,display:"+13%"},{label:"Emociones negativas (reducción)",value:21,display:"−21%"}],note:"Terminaron 459 de las 1,369 personas que empezaron. Participantes que se ofrecieron por iniciativa propia, sin grupo de control, medidas basadas en lo que contaban los participantes. Cifras del informe de la Semana Estoica 2021 de Tim LeBon.",sourceId:"stoic-week-report"}}],example:{title:"Sam, 26 años, diseñador junior",text:"La jefa de Sam respondió a su primer boceto importante con una sola línea: hablemos mañana. Para la hora del almuerzo, Sam estaba seguro de haber fracasado y redactaba una disculpa. Recordó la idea del ABC y la escribió. A: un mensaje corto pidiendo hablar. B: lo odia, esto me viene grande, debí saberlo. C: pavor y una tarde de retoques ansiosos. Entonces leyó la B como si la hubiera escrito un desconocido. El mensaje no decía nada sobre la calidad, y los mensajes cortos eran su manera de programar todas las reuniones. Una creencia que encajaba mejor era: quiere hablarlo, y todavía no sé cómo lo ve. El miedo bajó un poco. Pasó la tarde enumerando sus decisiones de diseño y sus razones. Al día siguiente ella pidió dos cambios y dijo que el resto funcionaba."},practice:["Recuerda un momento de hoy en que sentiste una emoción intensa y escribe el hecho con palabras neutras, las que registraría una cámara.","Debajo, escribe el juicio que añadiste, palabra por palabra, incluido cualquier debo, debería o siempre.","Escribe un juicio alternativo que se ajuste a los hechos al menos igual de bien y observa si el sentimiento cambia, aunque sea un poco."],reflection:"¿Qué juicio sueles añadir a los hechos sin darte cuenta?",question:"Desde la visión estoica, ¿de dónde viene la mayor parte del malestar en un momento perturbador?",options:["Del hecho en sí, que no se puede cambiar.","De sentir cualquier emoción.","Del juicio que añadimos sobre lo que significa el hecho."],correct:2,feedback:"Epicteto situaba la perturbación en nuestros juicios sobre los hechos. Los sentimientos en sí no son el enemigo; Séneca veía la primera sacudida como involuntaria. La práctica consiste en examinar la interpretación que aceptamos después.",takeaway:"Entre lo que sucede y lo que sientes hay una historia, y puedes comprobarla.",sources:["stoic-epictetus-iep","stoic-seneca-iep","stoic-week-handbook","optimism-ellis","stoic-kross-distancing","optimism-hofmann","optimism-nhs-cbt","stoic-week-report"],visual:{kind:"cycle",title:"Hecho, juicio, sentimiento, acción",nodes:[{label:"Hecho",text:"Algo sucede: un mensaje, un retraso, un comentario."},{label:"Juicio",text:"Añades un veredicto: esto es un desastre, tienen que respetarme."},{label:"Sentimiento",text:"La emoción sigue al veredicto más que al hecho."},{label:"Acción",text:"Actúas según el sentimiento, lo cual da forma a lo que ocurre después."}],center:"Haz una pausa en el juicio",note:"Resumen propio de la idea de Epicteto y del modelo ABC de Albert Ellis."},technique:{name:"La comprobación ABC, al estilo estoico",origin:"Albert Ellis · modelo ABC de la terapia racional emotivo-conductual (presentado por primera vez en 1956)",steps:["A: escribe el hecho activador con palabras sencillas y objetivas.","B: escribe la creencia que añadiste, en especial cualquier debo, debería o catástrofe.","C: anota el sentimiento y lo que hiciste, o quisiste hacer.","Cuestiona: pregúntate si la creencia es verdadera, si te ayuda y qué parte de ella puedes interpretar de otra manera.","Escribe una creencia más flexible, basada en una preferencia y no en una exigencia, y una acción que sugiera."],evidence:"El modelo ABC es una parte central de la terapia racional emotivo-conductual, y la TCC como terapia cuenta con un amplio respaldo de investigación. Esta versión de autoayuda no se ha probado por sí sola y no sustituye la terapia con un profesional cualificado.",sourceId:"optimism-ellis"},photo:{id:"1500534314209-a25ddb2bd429",alt:"Capas de colinas envueltas en bruma al atardecer"}},{id:"stoic-3",title:"Prepárate para un día difícil, con calma",minutes:9,goal:"Imagina brevemente y con realismo un contratiempo probable y planea tu respuesta, sin caer en la preocupación.",reading:["Los estoicos practicaban algo que al principio suena sombrío: imaginar las dificultades de antemano. Escritores posteriores lo llaman premeditatio malorum, la premeditación de las adversidades. Marco Aurelio, un emperador romano que llevaba un cuaderno privado que hoy conocemos como las Meditaciones, escribió sobre empezar el día esperando encontrarse con personas difíciles y decidiendo de antemano cómo las trataría. El propósito no era invitar al desastre. Era afrontar los contratiempos corrientes, como un tren retrasado o una respuesta grosera, con un plan en lugar de con un sobresalto. El manual de la Semana Estoica lo compara con la exposición moderna: mirar con calma una posibilidad temida, en dosis pequeñas, puede hacer que asuste menos.","Mal hecho, esto se convierte en rumiación: repetir los peores desenlaces una y otra vez, sin final y sin plan. El manual de la Semana Estoica es claro sobre la diferencia. Mantén el contratiempo imaginado realista, mantén la intensidad dentro de lo que puedas tolerar y acompáñalo de cómo quieres responder. Esa última parte importa. La investigación sobre el contraste mental, desarrollada por Gabriele Oettingen y sus colegas, encontró que imaginar un obstáculo real y luego hacer un plan de “si… entonces…” tenía un efecto medio de pequeño a mediano para alcanzar las metas. El ensayo estoico y el plan moderno se encuentran en el mismo punto: ver la dificultad con claridad y luego decidir qué harás al respecto."],deeper:[{heading:"¿Premeditación o preocupación?",paragraphs:["La preocupación y la premeditación miran hacia delante, pero se viven de forma distinta. La preocupación repite la misma escena, se vuelve cada vez más intensa y termina en pavor. La premeditación visita la escena una vez, anota lo que es probable y no todo lo que es posible, y termina con una respuesta que de verdad podrías dar.","Una prueba útil: pasados dos o tres minutos, ¿tienes una frase que empiece con “Si esto ocurre, yo…”? Si es así, ensayaste. Si sigues dando vueltas, detente, ponte de pie y haz algo con las manos. Puedes volver a ello más tarde."],visual:{kind:"steps",title:"Un ensayo de dos minutos",steps:[{label:"Elige",text:"Escoge un contratiempo realista para hoy o esta semana."},{label:"Imagina",text:"Imagínalo una vez, brevemente, con una intensidad que puedas tolerar."},{label:"Clasifica",text:"Observa qué partes de él dependen de ti."},{label:"Planea",text:"Escribe una frase de si… entonces… para tu respuesta."},{label:"Detente",text:"Cierra el ejercicio y vuelve a tu día."}],note:"Resumen propio, que combina las advertencias del manual de la Semana Estoica con la planificación de si… entonces…."}},{heading:"Cuándo conviene evitar este ejercicio",paragraphs:["El manual de la Semana Estoica dice que su curso no es adecuado para personas con problemas graves de salud mental, como la depresión clínica o el TEPT. También aclara que no sustituye el consejo médico. Si imaginar malos resultados te arrastra al pánico, a imágenes intrusivas o a horas de preocupación, sáltate la práctica de esta lección y habla con un profesional cualificado. Los terapeutas que usan la exposición para la ansiedad lo hacen con cuidado y con apoyo, por buenas razones."]}],example:{title:"Ana, 38 años, maestra de primaria",text:"Ana tenía una reunión a las cuatro con un padre que se había quejado dos veces por correo. Por la mañana, con el café, se dio dos minutos. Imaginó la versión probable, no la peor: él la interrumpe, alza un poco la voz y dice que es injusta con su hijo. Notó que se le tensaba el pecho y lo dejó estar. Luego se preguntó qué era suyo: su tono, los datos que llevaba y si se mantenía centrada en el progreso del niño. Escribió en una nota adhesiva: si me interrumpe, haré una pausa, diré que quiero escucharlo y luego volveré a los resultados de lectura. A las cuatro, él la interrumpió. Ana hizo la pausa, como estaba previsto. La reunión no fue cálida, pero se mantuvo en su cauce, y ella no pasó la noche repitiéndola en su cabeza."},practice:["Elige una dificultad realista que podría surgir en el próximo día o en los dos siguientes, no lo peor que puedas imaginar.","Imagínala una vez durante alrededor de un minuto, notando tus sentimientos sin apartarlos.","Escribe una frase que empiece con “Si esto ocurre, yo…”, luego cierra el ejercicio y sigue con tu día."],reflection:"¿Qué contratiempo pesaría menos si ya hubieras decidido cómo responder?",question:"¿Qué distingue la premeditación estoica de la rumiación?",options:["La premeditación imagina el peor resultado posible con la mayor viveza posible.","La premeditación es breve y realista y termina con una respuesta planeada.","La premeditación consiste en repetir la escena hasta que el miedo desaparezca."],correct:1,feedback:"El ensayo visita una dificultad probable brevemente, con una intensidad que puedas tolerar, y cierra con un plan. La rumiación repite los peores desenlaces sin un final ni una decisión.",takeaway:"Mira el momento difícil una vez, decide tu respuesta y vuelve al día de hoy.",sources:["stoic-week-handbook","state-mental-contrasting","if-then-plans"],visual:{kind:"table",title:"¿Ensayo o rumiación?",columns:["Pregunta","Ensayo estoico","Rumiación"],rows:[["¿Cuánto dura?","Uno o dos minutos","Horas, a ratos"],["¿Qué imaginas?","Una dificultad probable","El peor desenlace posible"],["¿Cómo termina?","Con un plan de si… entonces…","Con más pavor"],["¿Qué pasa después?","Vuelves a tu día","La escena se repite"]],note:"Resumen propio, basado en las advertencias del manual de la Semana Estoica."},technique:{name:"Premeditación de la adversidad",origin:"Marco Aurelio · Meditaciones (siglo II), tal como se enseña en el Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Elige una dificultad realista que puedas encontrar hoy.","Imagínala brevemente y con una intensidad que puedas tolerar.","Recuérdate qué partes de ella dependen de ti.","Decide cómo quieres responder y ponlo en una frase de si… entonces….","Termina el ejercicio y vuelve a llevar la atención al presente."],evidence:"Ningún ensayo controlado ha evaluado la premeditación estoica por sí solo. La evidencia moderna más cercana es la del contraste mental y los planes de si… entonces…, que mostraron efectos medios de pequeños a medianos para alcanzar metas en metaanálisis. No es adecuada para todas las personas que tienen dificultades con la ansiedad o los pensamientos intrusivos.",sourceId:"stoic-week-handbook"},photo:{id:"1464822759023-fed622ff2c3b",alt:"Valles con bosques bajo montañas nevadas"}},{id:"stoic-4",title:"La mirada desde lo alto",minutes:9,goal:"Toma distancia en un momento acalorado cambiando tu punto de vista, las palabras que usas o tu sentido del tiempo.",reading:["En sus Meditaciones, Marco Aurelio solía imaginar su vida desde muy lejos: la tierra entera, multitudes de personas, siglos que pasan. Los estoicos modernos lo llaman la mirada desde lo alto. Desde esa altura, la discusión del desayuno o el correo tenso se ven más pequeños, no porque no importen, sino porque ocupan su lugar entre todo lo demás. El ejercicio busca que un solo momento deje de ocupar toda tu atención, sin hacerte sentir insignificante. Sigues dentro de la escena. Simplemente ves más de ella que la parte que duele.","Los psicólogos Ethan Kross y Ozlem Ayduk han estudiado una idea muy parecida, a la que llaman autodistanciamiento. En sus experimentos, las personas que repasaban un recuerdo doloroso como un observador externo, mirándose desde lejos, informaron de menos emociones negativas que quienes lo revivían con sus propios ojos, y le encontraron más sentido a lo ocurrido. Otro camino es el lenguaje. En siete estudios con 585 personas, quienes se hablaban a sí mismas usando su propio nombre o “tú” en lugar de “yo” sintieron menos malestar, rindieron mejor en un discurso estresante según los observadores y rumiaron menos después."],deeper:[{heading:"Tres maneras de tomar distancia",paragraphs:["La revisión de Kross y Ayduk describe varias vías para tomar distancia. Puedes cambiar tu punto de vista en el espacio, como en el ejercicio del observador externo. Puedes cambiar tus palabras, dirigiéndote a ti mismo por tu nombre. O puedes cambiar tu punto de vista en el tiempo, preguntándote cómo te sentirás al respecto dentro de diez años. En sus estudios, tomar distancia en el tiempo parecía funcionar porque recordaba a las personas que los sentimientos pasan."],visual:{kind:"table",title:"Tres maneras de tomar distancia",columns:["Vía","Prueba esto","Lo que hallaron los estudios"],rows:[["Espacio","Mira la escena como un observador externo, viéndote dentro de ella.","Menos emoción negativa, más comprensión y una recuperación más rápida de la presión arterial que al revivirla."],["Palabras","Háblate usando tu nombre o tratándote de “tú”.","Menos malestar y rumiación, discursos mejor valorados, más sensación de reto que de amenaza."],["Tiempo","Pregúntate cómo verás esto dentro de diez años.","Menos malestar, vinculado a ver los sentimientos como temporales."]],note:"De Kross & Ayduk (2017) y Kross et al. (2014); sobre todo estudios breves de laboratorio."}},{heading:"Límites y preguntas razonables",paragraphs:["La mayoría de estos estudios fueron experimentos breves de laboratorio, a menudo con estudiantes. Los beneficios fueron más claros en las personas que ya estaban bastante alteradas; en algunos estudios, quienes sentían poco malestar apenas se beneficiaron. Los autores también distinguen entre tomar distancia para comprender un sentimiento y tomarla para evitarlo. El distanciamiento ayuda cuando lo usas para mirar con más claridad, no para mirar hacia otro lado.","Los estoicos y los psicólogos no describen exactamente lo mismo. Marco Aurelio apuntaba a una perspectiva amplia, a escala del universo; los experimentos piden retroceder unos pocos pasos. Ambos apuntan en la misma dirección: un poco de distancia abre espacio para una respuesta más sabia."]}],example:{title:"Priya, 33 años, analista de pruebas de software",text:"Priya estaba a punto de entrar en una videollamada donde un compañero había culpado públicamente a su equipo por una entrega que no salió a tiempo. Tenía el corazón acelerado y una respuesta mordaz preparada. Cuando faltaban tres minutos probó dos cosas. Primero se imaginó la llamada desde la esquina de la sala, como si observara a dos personas cansadas en una empresa ajetreada, una de las cuales era ella. Luego se habló por su nombre: Priya, quieres que la entrega se arregle, no ganar en el chat. Conoces el calendario. Dilo una vez, con calma. Seguía sintiendo enojo cuando empezó la llamada. Pero empezó hablando del calendario en lugar de soltar la respuesta mordaz, y la conversación pasó a lo que necesitaba cada equipo. Después notó que no estaba repitiéndola en su cabeza, algo nuevo para ella."},practice:["Piensa en una situación que te está molestando ahora mismo y fíjate en cuánto ocupa tu atención y con qué intensidad la sientes.","Repásala durante un minuto como un observador externo, viéndote en la escena desde la distancia.","Date un consejo breve usando tu propio nombre o “tú”, como lo haría un amigo tranquilo."],reflection:"¿Cómo verás esta situación dentro de diez años?",question:"En los estudios de Kross y sus colegas, ¿qué ayudó a las personas a manejar un discurso estresante?",options:["Hablarse por su nombre o como “tú” en lugar de “yo”.","Repasar los peores momentos con sus propios ojos.","Distraerse hasta que el sentimiento desapareciera."],correct:0,feedback:"El diálogo interno que no usa la primera persona aumentó la distancia, redujo el malestar y la rumiación, y dio lugar a discursos mejor valorados por los observadores. La revisión también halló que el distanciamiento se sostenía mejor en el tiempo que la distracción.",takeaway:"Tomar un poco de distancia puede ayudarte a ver con claridad lo que ahora te desborda.",sources:["stoic-week-handbook","stoic-kross-distancing","stoic-kross-self-talk"],visual:{kind:"compare",title:"¿Inmerso o distanciado?",left:{label:"Con tus propios ojos",items:["Repite los detalles: lo que dijeron, cómo se sintió.","Repite una y otra vez: ¿por qué a mí?","Los sentimientos siguen fuertes y vuelven más tarde."]},right:{label:"Desde unos pasos atrás",items:["Te permite verte en el contexto completo.","Pregunta cómo entender lo ocurrido.","La emoción se calma y el hecho se ve con más claridad."]},note:"Resumen propio de la reflexión inmersa y la distanciada en Kross & Ayduk (2017)."},technique:{name:"La mirada desde lo alto",origin:"Marco Aurelio · Meditaciones (siglo II), tal como se enseña en el Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Siéntate en silencio e imagínate donde estás ahora mismo.","Elévate despacio por encima de la habitación, la calle y la ciudad, viéndote como una figura pequeña en ella.","Sigue ampliando la vista hasta el país, el planeta y el paso de los siglos.","Desde esa altura, mira de nuevo lo que te inquieta y observa su lugar entre todo lo demás.","Regresa despacio y pregúntate cuál sería una respuesta sabia a ello."],evidence:"La mirada desde lo alto en sí no se ha probado en ensayos. Los experimentos sobre el autodistanciamiento, una idea relacionada, hallaron menos reactividad emocional y rumiación, sobre todo en estudios breves de laboratorio; los beneficios fueron mayores en las personas con más malestar.",sourceId:"stoic-week-handbook"},photo:{id:"1506905925346-21bda4d32df4",alt:"Cordilleras vistas desde arriba de un mar de nubes"}},{id:"stoic-5",title:"El repaso de la noche",minutes:8,goal:"Cierra el día con un repaso breve y justo que convierta los errores en una lección para mañana.",reading:["Séneca, un filósofo romano que fue tutor y luego consejero del emperador Nerón, es uno de los estoicos vinculados con un hábito nocturno: antes de dormir, repasar el día. Epicteto recomendaba el mismo tipo de repaso. En su forma moderna, enseñada en el manual de la Semana Estoica, lleva de cinco a diez minutos y tres preguntas. ¿Qué hice mal? ¿Qué hice bien? ¿Qué podría hacer de otra manera? El repaso debe ser específico. No “hoy fui horrible”, sino “interrumpí a Ali en la reunión cuando no estuvo de acuerdo”. De las acciones específicas se puede aprender. De los veredictos globales sobre ti mismo, no.","El manual añade una condición que lo cambia todo: repasa el día como lo haría un buen amigo o un maestro justo, no como un fiscal. Un repaso duro te mantiene despierto repitiendo escenas. Uno justo nombra el tropiezo, anota lo que salió bien y termina con un pequeño ajuste. Hay aquí un vínculo con la investigación sobre autodistanciamiento de la lección anterior. Cuando las personas reflexionan desde unos pasos atrás, tienden a pasar de repetir lo ocurrido a comprenderlo, y rumian menos. El repaso nocturno funciona mejor con ese espíritu: una mirada atrás que le da sentido al día, luego el cuaderno cerrado y a dormir."],deeper:[{heading:"Cómo evitar que se convierta en rumiación",paragraphs:["Ponle un límite: de cinco a diez minutos, en papel, más o menos a la misma hora cada noche. El papel le da un final al repaso. Cuando las tres preguntas están respondidas, el día está cerrado.","Cuenta lo bueno con el mismo cuidado que lo malo. La segunda pregunta no es un adorno. Si solo buscas fallos, el repaso se convierte en una lista de cargos. Si también buscas lo que salió bien, aprendes qué repetir."],visual:{kind:"cycle",title:"El ciclo del repaso",nodes:[{label:"Actúa",text:"Vive el día, tomando las mejores decisiones que puedas."},{label:"Repasa",text:"Por la noche, responde las tres preguntas en papel."},{label:"Ajusta",text:"Elige un pequeño cambio para mañana."},{label:"Descansa",text:"Cierra el cuaderno y deja que el día termine."}],center:"Aprender, no castigar",note:"Resumen propio de la meditación nocturna del manual de la Semana Estoica."}},{heading:"Lo que dice la evidencia",paragraphs:["Ningún ensayo controlado ha evaluado el repaso nocturno estoico por sí solo. En la Semana Estoica es una de varias prácticas diarias, y el curso en conjunto solo se ha evaluado con encuestas respondidas por voluntarios sobre sus propias experiencias, sin grupo de control. La mejor razón para probarlo es práctica: es breve, gratuito y fácil de dejar si no te ayuda.","Si un repaso nocturno te deja con frecuencia más ansioso o sin poder dormir, adelántalo, acórtalo o déjalo. Si el ánimo bajo o la autocrítica son intensos y duraderos, habla con un profesional."]}],example:{title:"Tom, 52 años, dueño de una tienda",text:"Tom solía quedarse despierto repasando todo lo que había salido mal en la tienda. Decidió probar el repaso a las nueve, en la mesa de la cocina, con un cuaderno pequeño. La primera noche escribió: mal, le contesté con brusquedad a un proveedor por teléfono cuando un pedido llegó tarde; bien, tuve paciencia con una clienta mayor confundida y le encontré la pieza correcta; de otra manera, cuando un pedido llega tarde, preguntar la nueva hora antes de decir nada más. Le tomó siete minutos. Cerró el cuaderno y lo dejó sobre el mostrador. Todavía pensó en el proveedor en la cama, pero el pensamiento ya tenía un lugar: estaba escrito, con un plan. Después de dos semanas notó que aparecían los mismos tipos de tropiezo, lo que le dijo dónde practicar."},practice:["Pon un temporizador de cinco minutos esta noche y escribe respuestas cortas a: ¿qué hice mal?, ¿qué hice bien?, ¿qué podría hacer de otra manera?","Reescribe cualquier frase dura con el tono que usaría un amigo justo, conservando los hechos.","Elige un pequeño ajuste para mañana, escríbelo al principio de una página nueva y cierra el cuaderno."],reflection:"¿Qué diría un amigo justo sobre cómo manejaste el día de hoy?",question:"¿Qué tono recomienda el repaso nocturno estoico moderno?",options:["El tono de un juez estricto, para no repetir nunca un error.","El tono de un amigo justo que nombra los errores y lo que salió bien.","Ningún juicio: anotar solo lo que salió bien para dormir mejor."],correct:1,feedback:"El repaso nombra los tropiezos reales y los logros reales, de forma concreta y amable, y termina con un ajuste. La dureza tiende a alimentar la rumiación; ignorar los errores no enseña nada.",takeaway:"Mira atrás para aprender y luego cierra el día.",sources:["stoic-seneca-iep","stoic-week-handbook","stoic-kross-distancing","stoic-week-report"],visual:{kind:"steps",title:"Tres preguntas antes de dormir",steps:[{label:"¿Qué hice mal?",text:"Nombra una acción específica, no un veredicto sobre ti."},{label:"¿Qué hice bien?",text:"Encuentra al menos una cosa que valga la pena repetir."},{label:"¿Qué podría hacer de otra manera?",text:"Convierte la lección en un pequeño cambio para mañana."}],note:"De la meditación nocturna del manual de la Semana Estoica, basada en Séneca y Epicteto."},technique:{name:"Repaso nocturno",origin:"Séneca y Epicteto, tal como se enseña en el Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Siéntate a una hora fija por la noche con un cuaderno.","Recorre el día brevemente, en orden, desde la mañana hasta ahora.","Responde: ¿qué hice mal?, ¿qué hice bien?, ¿qué podría hacer de otra manera?","Usa la voz de un amigo justo, nombrando acciones específicas en lugar de juzgarte como persona.","Escribe un ajuste para mañana y cierra el cuaderno."],evidence:"El repaso no se ha evaluado por sí solo en estudios controlados. Es una parte de la Semana Estoica, cuyos participantes que la terminaron informaron de un mayor bienestar en encuestas sin grupo de control y basadas en sus propias experiencias.",sourceId:"stoic-week-handbook"},photo:{id:"1475924156734-496f6cac6ec1",alt:"Olas en una costa rocosa al atardecer"}},{id:"stoic-6",title:"La decisión de hoy",minutes:8,goal:"Usa la idea estoica de atender a lo que depende de ti para elegir una pequeña decisión que puedas cumplir hoy.",reading:["Para los estoicos, la filosofía era una forma de vivir, no solo un conjunto de ideas que admirar. Todo en este curso conduce aquí. El ejercicio sobre lo que depende de ti te muestra dónde puedes actuar. Revisar tu juicio evita que una historia dirija tus acciones. El ensayo prepara una respuesta, la distancia calma un momento de tensión y el repaso nocturno te enseña algo sobre tu día. Nada de eso importa mucho hasta que haces una cosa de manera distinta. Esa es también la idea detrás de ODA: una decisión al día, tomada a propósito, en la parte de la vida que de verdad te toca moldear.","Una buena decisión estoica tiene tres rasgos. Está dentro de tu control: una acción, no un resultado. Es lo bastante pequeña para hacerla hoy. Y se vincula a un momento concreto, de modo que no tienes que depender de la memoria ni de la fuerza de voluntad. La investigación sobre planificación ayuda con esa última parte. En 94 pruebas, los planes con la forma “Si ocurre la situación X, entonces haré Y” tuvieron un efecto medio de mediano a grande para alcanzar las metas, aunque análisis más recientes sugieren que el efecto real puede ser menor. El método WOOP de Gabriele Oettingen añade un deseo y un obstáculo al plan; la investigación en que se apoya muestra un efecto de pequeño a mediano."],deeper:[{heading:"Por qué conviene empezar con algo pequeño y concreto",paragraphs:["Los grandes propósitos suelen quedar en la columna del resultado: ponerme en forma, estar más tranquilo, arreglar la relación. Una decisión estoica devuelve el propósito a tu propia columna: caminar diez minutos después de comer, respirar tres veces antes de responder a mi jefe, hacerle a mi pareja una pregunta de verdad durante la cena. Puedes cumplir esa decisión hoy, te trate como te trate el día.","Luego suelta el resultado. Si diste el paseo y aun así te sientes cansado, la decisión se cumplió. El resultado pertenece a la segunda columna. Lo que aprendiste va al repaso de esta noche."],visual:{kind:"compare",title:"¿Un propósito o una decisión estoica?",left:{label:"Propósito centrado en el resultado",items:["Conseguir el ascenso.","Dejar de sentir ansiedad.","Hacer que me entiendan."]},right:{label:"Decisión estoica para hoy",items:["Enviarle a mi jefe el resumen del proyecto antes de las 3 p. m.","Cuando se me tense el pecho, respirar despacio tres veces antes de responder.","Escuchar su versión durante dos minutos antes de dar la mía."]},note:"Ejemplos propios."}},{heading:"Cuando el día sale mal de todos modos",paragraphs:["Algunos días el plan no se cumplirá. Un hijo se enferma, una reunión se alarga, la energía se acaba. La respuesta estoica no es culparte. Lo que sigue dependiendo de ti es cómo respondes ahora: una versión más pequeña de la misma decisión, o simplemente anotar qué se interpuso para el repaso de esta noche. Lo importante es seguir practicando, aunque no siempre salga como esperabas.","Este curso es un conjunto de prácticas, no un tratamiento. Si el estrés, el ánimo bajo o la ansiedad están interfiriendo con tu vida diaria, la decisión más estoica puede ser pedir ayuda profesional, una acción que está por completo dentro de tu control."]}],example:{title:"Can, 29 años, asistente de ventas",text:"Can llevaba semanas preocupado por el dinero y por una relación tensa con su hermano. Las dos cosas le parecían demasiado grandes para abordarlas. Un domingo por la mañana hizo el ejercicio sobre lo que dependía de él. El humor de su hermano y el aumento del alquiler fueron a la segunda columna. En la primera puso revisar sus gastos del mes y ponerse en contacto con su hermano. Eligió una decisión para el día: si terminaba de almorzar, entonces le enviaría a su hermano un mensaje corto preguntándole cómo le iba en su nuevo trabajo. Lo escribió en la pantalla de bloqueo de su teléfono. Después de almorzar casi lo dejó pasar, luego lo envió. La respuesta llegó por la noche, breve pero amable. Nada quedó resuelto. Pero esa noche, en su repaso, Can escribió que había actuado sobre algo que era suyo, y eligió la decisión de mañana: revisar los gastos."},practice:["Elige una preocupación o una meta y escribe la parte de ella que depende de ti como una acción, no como un resultado.","Reduce esa acción hasta que puedas hacerla hoy en menos de quince minutos.","Vincúlala a un momento concreto con una frase de si… entonces…, como “Si termino de almorzar, entonces…”, y luego hazla."],reflection:"¿Cuál es una pequeña cosa, totalmente en tus manos, que podrías hacer hoy?",question:"¿Cuál de estas es una decisión de estilo estoico para hoy?",options:["Convertirme en una persona más tranquila este año.","Asegurarme de que mi equipo apruebe mi propuesta.","Si abro mi portátil después de comer, entonces dedicaré diez minutos a esbozar la propuesta."],correct:2,feedback:"Es una acción dentro de tu control, lo bastante pequeña para hoy y vinculada a un momento concreto por un plan de si… entonces…. Las otras dos describen resultados o esperanzas a largo plazo.",takeaway:"Haz hoy algo pequeño que dependa de ti e intenta soltar lo demás.",sources:["stoic-epictetus-iep","stoic-week-handbook","if-then-plans","oettingen-woop-method","mcii"],visual:{kind:"table",title:"De la preocupación a una decisión",columns:["Preocupación","Depende de ti","La decisión de hoy"],rows:[["¿Conseguiré el trabajo?","La preparación y el seguimiento","Practicar mi respuesta a la pregunta más difícil durante diez minutos después de cenar."],["¿Mi amiga está molesta conmigo?","Acercarme y escuchar","Enviar un mensaje corto y honesto antes del mediodía."],["¿Estoy descuidando mi salud?","El movimiento y la hora de dormir","Dar un paseo de diez minutos después de comer."]],note:"Ejemplos propios de cómo convertir lo que depende de ti en decisiones de si… entonces…."},technique:{name:"WOOP",origin:"Gabriele Oettingen · Rethinking Positive Thinking (2014)",steps:["Wish (deseo): nombra algo que quieres conseguir, que suponga un reto pero sea posible.","Outcome (resultado): imagina por un momento el mejor resultado de ello.","Obstacle (obstáculo): encuentra el principal obstáculo en tu camino, a menudo un hábito o un sentimiento tuyo.","Plan: escribe “Si [obstáculo], entonces haré [acción]” y elige un momento de hoy para empezar."],evidence:"El contraste mental combinado con planes de si… entonces… mostró un efecto medio de pequeño a mediano para alcanzar metas en 21 estudios (g = 0.336). El sitio oficial de WOOP pertenece a los desarrolladores del método y no es una evaluación independiente.",sourceId:"oettingen-woop-method"},photo:{id:"1502082553048-f009c37129b9",alt:"Un solo árbol en un paisaje abierto"}}]},D=Object.freeze(Object.defineProperty({__proto__:null,COURSE:A,SOURCES:P},Symbol.toStringTag,{value:"Module"})),a=[o,s,y,n,i,r,h,t,E,l,c,L,u,d,k,D,p,m],F=a.map(e=>e.COURSE).filter(e=>e.lessons.length>0),J=a.flatMap(e=>e.SOURCES);export{F as ES_COURSES,J as ES_SOURCES};
